COLLDATA("qenc","ur",[[380,"§صلاۃعشا\nدیکھیے: عشاء","",{}],[381,"§صلاۃعصر\nدیکھیے: عصر","",{}],[382,"§صلوات\nصلوات کا لفظ یہودیوں کی عبادت گاہ کے معنی میں قرآن کریم کے اندر استعمال ہوا ہےاوربتایا گیا ہے کہ اللہ تعالی اپنے قانون کے مطابق لوگوں کو ایک دوسرے کے ذریعے ہٹاتا رہتا ہے۔ اگر ایسا نہ ہوتا تو عبادت گاہیں،گرجا گھر، یہودیوں کی عبادت گاہیں(صلوات) مسلمانوں کی مسجدیں، جن میں اللہ کا نام لیاجاتا ہے۔سب کے سب گرادیئے جاتےاور یہ دنیا فساد کی جگہ بن جاتی اور قیامت کے آنے سے پہلے ہی تہس نہس اور برباد ہوجاتی قرآن کریم میں اسی قانون کی طرف اشارہ کیا گیا ہے:﴿ٱلَّذِينَ أُخۡرِجُواْ مِن دِيَٰرِهِم بِغَيۡرِ حَقٍّ إِلَّآ أَن يَقُولُواْ رَبُّنَا ٱللَّهُۗ وَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم بِبَعۡضࣲ لَّهُدِّمَتۡ صَوَٰمِعُ وَبِيَعࣱ وَصَلَوَٰتࣱ وَمَسَٰجِدُ يُذۡكَرُ فِيهَا ٱسۡمُ ٱللَّهِ كَثِيرࣰ اۗ وَلَيَنصُرَنَّ ٱللَّهُ مَن يَنصُرُهُۥٓۚ إِنَّ ٱللَّهَ لَقَوِيٌّ عَزِيزٌ﴾ [الحج: ۴۰] \"یہ وہ لوگ ہیں کہ اپنے گھروں سے ناحق نکال دیئے گئے (انھوں نے کچھ قصور نہیں کیا) ہاں یہ کہتے ہیں کہ ہمارا رب صرف اللہ تعالی ہے اوراگر اللہ تعالی لوگوں کو ایک دوسرے سے نہ ہٹاتا رہتا تو (راہبوں کے) صومعےاور (عیسائیوں کے) گرجےاور(یہودیوں کے) عبادت خانے(صلوات) اور (مسلمانوں کی) مسجدیں جن میں اللہ تعالی کا بہت سا ذکر کیا جاتا ہے ویران ہوچکی ہوتیں۔ اور جو شخص اللہ تعالی کی مدد کرتا ہے اللہ تعالی اس کی ضرور مدد کرتا ہے۔ بےشک اللہ تعالی قوی وعزیز(بہت طاقت ور اور غالب) ہے\"۔","",{}],[383,"§صمد\nدیکھیے: اسماےحسنی","",{}],[384,"§صنم خانہ\nدیکھیے: انصاب","",{}],[385,"§صنم کدہ\nدیکھیے: انصاب","",{}],[386,"§صوامع\nصوامع صومعہ کی جمع ہے۔اس کے معنیٰ اس خانقاہ کے ہیں،جہاں عیسائی سادھو، سنیاسی (راہب) تنہا یا اپنے کچھ چیلوں کے ساتھ عبادت کرتے ہیں۔ قرآن میں صوامع کا استعمال اس دنیا میں جاری اللہ تعالیٰ کےایک اہم قانون کے تحت ہوا ہے۔اللہ تعالیٰ نے دنیا کے لیے یہ قانون بنایا ہے کہ ایک دوسرے کے ذریعے سے ایک دوسرا کا دفاع ہوتا رہے۔اگر ایسا نہ ہوتا تو عبادت گاہیں،گرجا گھر، یہودیوں کی عبادت گاہیں، مسلمانوں کی مسجدیں جن میں اللہ کا نام لیا جاتا ہے۔سب کے سب گرادیے جاتےاور یہ دنیا فساد کی جگہ بن جاتی اور قیامت کے آنے سے پہلے ہی تہس نہس اور برباد ہوجاتی۔ قرآن میں اسی قانون کی طرف اشارہ کیا گیا ہے:﴿ٱلَّذِينَ أُخۡرِجُواْ مِن دِيَٰرِهِم بِغَيۡرِ حَقٍّ إِلَّآ أَن يَقُولُواْ رَبُّنَا ٱللَّهُۗ وَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم بِبَعۡضࣲ لَّهُدِّمَتۡ صَوَٰمِعُ وَبِيَعࣱ وَصَلَوَٰتࣱ وَمَسَٰجِدُ يُذۡكَرُ فِيهَا ٱسۡمُ ٱللَّهِ كَثِيرࣰ اۗ وَلَيَنصُرَنَّ ٱللَّهُ مَن يَنصُرُهُۥٓۚ إِنَّ ٱللَّهَ لَقَوِيٌّ عَزِيزٌ﴾ [الحج: ۴۰] \"یہ وہ لوگ ہیں کہ اپنے گھروں سے ناحق نکال دیے گئے (انھوں نے کچھ قصور نہیں کیا) ہاں یہ کہتے ہیں کہ ہمارا پروردگار صرف اللہ تعالی ہے۔ اور اگر اللہ تعالی لوگوں کو ایک دوسرے سے نہ ہٹاتا رہتا تو (راہبوں کے) صومعے اور (عیسائیوں کے) گرجے اور (یہودیوں کے) عبادت خانے اور (مسلمانوں کی) مسجدیں جن میں اللہ تعالی کا بہت سا ذکر کیا جاتا ہے ویران ہوچکی ہوتیں۔ اور جو شخص اللہ تعالی کی مدد کرتا ہے اللہ تعالی اس کی ضرور مدد کرتا ہے۔ بےشک اللہ تعالی قوی اور عزیز(بہت طاقت ور اور غالب) ہے\"۔","",{}],[387,"§صور\nصور کےمعنیٰ سینگ یا نرسنگھا ہے۔ قرآن مجیدمیں اس کا ذکر دس جگہوں پر آیا ہے۔ ہر جگہ اس کا استعمال اس معنیٰ میں ہے کہ قیامت آنےسے پہلے صور پھونکا جائے گا۔جس کی آواز اتنی تیز اور بھیانک ہوگی کہ سارے لوگ بے ہوش ہو جائیں گے۔ پھر دوسری بار صور پھونکا جائے گا تو سارے لوگ اپنی اپنی قبروں سے نکل کھڑے ہوں گےاور اپنا اپنا حساب کتاب دینے کے لیے حشر کے میدان میں اکٹھا ہوں گے۔ارشادباری تعالیٰ ہے:\n۱- ﴿وَهُوَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۖ وَيَوۡمَ يَقُولُ كُن فَيَكُونُۚ قَوۡلُهُ ٱلۡحَقُّۚ وَلَهُ ٱلۡمُلۡكُ يَوۡمَ يُنفَخُ فِي ٱلصُّورِۚ عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِۚ وَهُوَ ٱلۡحَكِيمُ ٱلۡخَبِيرُ﴾ [الأنعام: ۷۳] \"اور جس دن صور پھونکا جائے گا\"۔\n۲- ﴿وَتَرَكۡنَا بَعۡضَهُمۡ يَوۡمَئِذࣲ يَمُوجُ فِي بَعۡضࣲۖ وَنُفِخَ فِي ٱلصُّورِ فَجَمَعۡنَٰهُمۡ جَمۡعࣰ ا﴾ [الکهف: ۹۹] \"اور صور پھونکا جائے گا تو ہم سب کو جمع کرلیں گے\"۔\n۳- ﴿يَوۡمَ يُنفَخُ فِي ٱلصُّورِۚ وَنَحۡشُرُ ٱلۡمُجۡرِمِينَ يَوۡمَئِذࣲ زُرۡقࣰ ا﴾ [طه: ۱۰۲] \"جس روز صور پھونکا جائے گا اور ہم گنہگاروں کو اکھٹا کریں گے اور ان کی آنکھیں نیلی نیلی ہوں گی\"۔\n۴- ﴿فَإِذَا نُفِخَ فِي ٱلصُّورِ فَلَآ أَنسَابَ بَيۡنَهُمۡ يَوۡمَئِذࣲ وَلَا يَتَسَآءَلُونَ﴾ [المومنون: ۱۰۱] \"پھر جب صور پھونکا جائے گا تو نہ تو ان میں قرابتیں ہوں گی اور نہ ایک دوسرے کو پوچھیں گے\"۔\n۵- ﴿وَيَوۡمَ يُنفَخُ فِي ٱلصُّورِ فَفَزِعَ مَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِ إِلَّا مَن شَآءَ ٱللَّهُۚ وَكُلٌّ أَتَوۡهُ دَٰخِرِينَ﴾ [النمل: ۸۷] \"اورجس روز صور پھونکا جائے گا تو جو لوگ آسمانوں اور زمین میں ہیں سب گھبرا اُٹھیں گے۔ مگر وہ جسے اللہ تعالی چاہے اور سب اس کے پاس عاجز ہو کر چلے آئیں گے\"۔\n۶- ﴿وَنُفِخَ فِي ٱلصُّورِ فَإِذَا هُم مِّنَ ٱلۡأَجۡدَاثِ إِلَىٰ رَبِّهِمۡ يَنسِلُونَ﴾ [یس: ۵۱] \"اور (جس وقت) صور پھونکا جائے گا یہ قبروں سے (نکل کر) اپنے رب کی طرف دوڑ پڑیں گے\"۔\n۷- ﴿وَنُفِخَ فِي ٱلصُّورِ فَصَعِقَ مَن فِي ٱلسَّمَٰوَٰتِ وَمَن فِي ٱلۡأَرۡضِ إِلَّا مَن شَآءَ ٱللَّهُۖ ثُمَّ نُفِخَ فِيهِ أُخۡرَىٰ فَإِذَا هُمۡ قِيَامࣱ يَنظُرُونَ﴾ [الزمر: ۶۸] \"اور جب صور پھونکا جائے گا تو جو لوگ آسمان میں ہیں اور جو زمین میں ہیں سب بےہوش ہو کر گر پڑیں گے، مگر وہ جس کو اللہ تعالیٰ چاہے، پھر دوسری دفعہ پھونکا جائے گا تو فوراً سب کھڑے ہو کر دیکھنے لگیں گے\"۔\n۸- ﴿وَنُفِخَ فِي ٱلصُّورِۚ ذَٰلِكَ يَوۡمُ ٱلۡوَعِيدِ﴾ [ق: ۲۰] \"اور صور پھونکا جائے گا۔ یہی (عذاب کے) وعید کا دن ہے۔\n۹- ﴿وَحُمِلَتِ ٱلۡأَرۡضُ وَٱلۡجِبَالُ فَدُكَّتَا دَكَّةࣰ وَٰحِدَةࣰ فَيَوۡمَئِذࣲ وَقَعَتِ ٱلۡوَاقِعَةُ﴾ [الحاقة: ۱۴-۱۵] \"تو جب صور میں ایک (بار) پھونک مار دی جائے گی۔ اور زمین اور پہاڑ دونوں اٹھا لیے جائیں گے۔ پھر ایک بارگی توڑ پھوڑ کر برابر کردیئے جائیں گے۔تو اس روز ہو پڑنے والی (یعنی قیامت) ہو پڑے گی\"۔\n۱۰- ﴿يَوۡمَ يُنفَخُ فِي ٱلصُّورِ فَتَأۡتُونَ أَفۡوَاجࣰ ا﴾ [النبأ: ۱۸] \"جس دن صور پھونکا جائے گا تو تم لوگ فوج کے فوج آ موجود ہو گے\"۔\nعبداللہ بن عمر و رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:«يُنْفَخُ فِي الصُّورِ فَلا يَسْمَعُهُ أَحَدٌ إِلا أَصْغَی لِيتًا وَرَفَعَ لِيتًا، قَالَ: وَأَوَّلُ مَنْ يَسْمَعُهُ رَجُلٌ يَلُوطُ حَوْضَ إِبِلِهِ، قَالَ: فَيَصْعَقُ وَيَصْعَقُ النَّاسُ ثُمَّ يُرْسِلُ اللَّهُ -أَوْ قَالَ: يُنْزِلُ اللَّهُ- مَطَرًا کَأَنَّهُ الطَّلُّ أَوْ الظِّلُّ -نُعْمَانُ الشَّاکُّ- فَتَنْبُتُ مِنْهُ أَجْسَادُ النَّاسِ، ثُمَّ يُنْفَخُ فِيهِ أُخْرَی، فَإِذَا هُمْ قِيَامٌ يَنْظُرُونَ، ثُمَّ يُقَالُ: يَا أَيُّهَا النَّاسُ! هَلُمَّّوا إِلَی رَبِّکُمْ وَقِفُوهُمْ إِنَّهُمْ مَسْئُولُونَ، قَالَ: ثُمَّ يُقَالُ: أَخْرِجُوا بَعْثَ النَّارِ فَيُقَالُ: مِنْ کَمْ؟ فَيُقَالُ: مِنْ کُلِّ أَلْفٍ تِسْعَ مِائَةٍ وَتِسْعَةً وَتِسْعِينَ، قَالَ: فَذَاکَ يَوْمَ يَجْعَلُ الْوِلْدَانَ شِيبًا وَذَلِکَ يَوْمَ يُکْشَفُ عَنْ سَاقٍ». (صحیحمسلم: ۱۱۶/۲۹۴۰) \"صور پھونکا جائے گا۔ جو کوئی اسے سنے گا،اس کی گردن ایک طرف جھک جائے گی اور دوسری طرف سے اٹھ جائے گی۔ سب سے پہلے اس کی آواز وہ سنے گا جو اپنے اونٹ کے حوض کو لیپ رہا ہو گا۔ وہ بے ہوش ہوکر گر پڑے گا اور لوگ بھی گر جائیں گے۔ پھر اللہ بھیجےگایا نازل کرے گا۔ بارش جو شبنم کی طرح ہو گی، اس سے لوگوں کے بدن اگ آئیں گے۔ پھر صور پھونکا جائے گا تو سب کھڑے دیکھ رہے ہوں گے، پھر کہا جائے گا: اے لوگو! اپنے رب کی طرف آؤ اور (فرشتوں سے کہا جائے گا:) ان لوگوں کو کھڑا کرو۔ ان سے سوال ہو گا۔ پھر کہا جائے گا: ایک لشکر نکالو۔ جہنم کے لیے۔ پوچھا جائے گا: کتنے لوگ؟ ارشاد ہوگا: ہر ہزار میں سے نو سو ننانوے(۹۹۹) لوگ۔ یہی وہ دن ہو گا جو بچوں کو بوڑھا کر دے گا۔ اور یہی وہ دن ہے جب پنڈلی کھلے گی\"۔\nبعض علما کا خیال ہے کہ تین بار صور پھونکا جائے گا۔ جب پہلی بار پھونکا جائے گا تو زمین و آسمان پر موجودساری مخلوق گھبرا اٹھے گی۔ جیسا کہ (سورہ النمل: ۸۷)میں آیا ہے۔\nدوسری بار جب صور پھونکا جائے گا،تو زمین و آسمان پر جو لوگ ہوں گے وہ سب بیہوش ہو جائیں گے اورجب تیسری بار صور پھونکا جائے گا تو لوگ اپنی اپنی قبروں سے اٹھ کھڑے ہوں گے۔ جیسا کہ سورہ الزمر (آیت نمبر: ۶۸) سے پتا چلتا ہے۔\nلیکن ہمارے خیال سے صور صرف دو ہی بار پھونکا جائے گا۔ سورہ النمل (آیت نمبر: ۸۷) میں جو گھبرا جانے اور سورہ الزمر(آیت نمبر: ۶۸) میں بے ہوش ہونے کا جو ذکر ہے تو دونوں کا مطلب ایک ہی ہے کیوں کہ کچھ لوگوں کو اللہ تعالیٰ اس گھبراہٹ سے بچا لےگا۔ جیسا کہ سورہ النمل [آیت نمبر: ۸۷]میں ہی آیا ہےجس کا مطلب یہ ہے کہ کچھ لوگوں کو اللہ تعالیٰ بے ہوش ہونے سے بچا لےگا۔\nاس کی تصدیق اس صحیح حدیث سے بھی ہوتی ہے،ابوہریرہ رضی اللہ عنہ کہتےہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «لا تُفَضِّلُوا بَيْنَ أَنْبِيَاءِ اللَّهِ، فَإِنَّهُ يُنْفَخُ فِي الصُّورِ فَيَصْعَقُ مَنْ فِي السَّمَوَاتِ وَمَنْ فِي الأَرْضِ، إِلا مَنْ شَاءَ اللَّهُ، ثُمَّ يُنْفَخُ فِيهِ أُخْرَی، فَأَکُونُ أَوَّلَ مَنْ بُعِثَ، فَإِذَا مُوسَی آخِذٌ بِالْعَرْشِ، فَلا أَدْرِي أَحُوسِبَ بِصَعْقَتِهِ يَوْمَ الطُّورِ أَمْ بُعِثَ قَبلي». (صحیحالبخاری: ۳۴۱۴وصحیحمسلم: ۲۳۷۳/۱۵۹) \"اللہ تعالیٰ کے انبیامیں آپس میں ایک کودوسرےپر فضیلت نہ دیا کرو، جب صور پھونکا جائے تو آسمان وزمین کی تمام مخلوق پر بے ہوشی طاری ہو جائے گی، سوائے ان کے جنھیں اللہ تعالیٰ چاہے گا۔ پھر دوسری مرتبہ صور پھونکا جائے گا اور سب سے پہلے مجھے اٹھایا جائے گا، لیکن میں دیکھوں گا کہ موسیٰڠ عرش کو پکڑے ہوے کھڑے ہوں گے، اب مجھے معلوم نہیں کہ یہ انھیں طور کی بے ہوشی کا بدلا دیا گیا ہے یا مجھ سے بھی پہلے ان کی بے ہوشی ختم کر دی گئی ہے\"۔\nصحیح معنوں میں اس حدیث کے مطابق سورہ النمل میں جس گھبراہٹ کا ذکر ہوا ہے، اس سے بے ہوش ہونا ہی معلوم ہوتا ہے۔ کیوں کہ اسی آیت کے آخر میں آیا ہے کہ جسے اللہ چاہے وہ بے ہوش نہیں ہوگا۔\nیہاں یہ بات بھی واضح کردینی ضروری ہے کہ کچھ حدیثوں میں صور پھونکنے والے فرشتے کا نام بھی بیان کیا گیا ہے لیکن وہ حدیث صحیح نہیں ہے۔ (اس کے لیے دیکھیے: میری کتاب: الجامع الکامل)","",{}],[388,"§صوم،صیام\nاردومیں صوم اورصیام کوروزہ کہتے ہیں،جس کا مطلب ہے رک جانا۔صوم(روزہ) رکھنے والا صبح اذان فجر سے لے کرسورج ڈوبنے تک کھانے پینے اور ہم بستری سے رک جاتا ہے۔صوم(روزہ) حقیقت میں خواہشوں کو قابو میں رکھنے کاایک بڑا عمدہ ذریعہ ہے۔زیادہ کھانے پینے سے آدمی کی شہوت بڑھتی رہتی ہے۔ شیطان جو ہمارے خون کے ساتھ دوڑتا رہتا ہے ہمیں آسانی سے گمراہ کر سکتا ہے۔ اس لیے صوم (روزہ) ہی خواہش نفسانی کو قابو میں رکھنے کا عمدہ ذریعہ ہے۔\nاسلام سے پہلے بھی لوگوں پر ٍصوم(روزہ) فرض کیا گیا تھا۔ تاہم انھوں نے صوم(روزے) کو ہی اپنی زندگی کا اصل مقصد بنا لیا اور پھر وہ رہبانیت اورترک دنیا کی طرف نکل گئے۔ اسلام چونکہ ایک معتدل دین ہے، اس لیے اس نے صوم(روزے) کو عبادت تو بنایا، لیکن سب کچھ نہیں، اس لیے جہاں ہمیشہ صوم (روزہ) رکھنے سے منع فرمایا، وہیں الگ الگ مقام پر صوم(روزہ) رکھنے کا حکم بھی دیا۔ تاہم فرض صیام (روزہ) صرف رمضان کے ماہ کاہی ہے۔ارشادباری تعالیٰ ہے:﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُتِبَ عَلَيۡكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبۡلِكُمۡ لَعَلَّكُمۡ تَتَّقُونَ﴾ [البقرة: ۱۸۳] \"اے ایمان والو! تم پرصوم(روزہ) فرض کیے گئے ہیں جس طرح تم سے پہلے لوگوں پر فرض کیے گئے تھے\"۔\nیہاں صوم(روزے)سےمراد رمضان کے صوم(روزے)ہیں، کیونکہ رمضان وہ مبارک مہینہ ہےجس میں قرآن اتارا گیا۔ اس لیے اس مہینے کوصوم(روزے) جیسی اہم عبادت کا مہینہ بنا دیا گیا: ﴿شَهۡرُ رَمَضَانَ ٱلَّذِيٓ أُنزِلَ فِيهِ ٱلۡقُرۡءَانُ هُدࣰ ى لِّلنَّاسِ وَبَيِّنَٰتࣲ مِّنَ ٱلۡهُدَىٰ وَٱلۡفُرۡقَانِۚ فَمَن شَهِدَ مِنكُمُ ٱلشَّهۡرَ فَلۡيَصُمۡهُۖ وَمَن كَانَ مَرِيضًا أَوۡ عَلَىٰ سَفَرࣲ فَعِدَّةࣱ مِّنۡ أَيَّامٍ أُخَرَۗ يُرِيدُ ٱللَّهُ بِكُمُ ٱلۡيُسۡرَ وَلَا يُرِيدُ بِكُمُ ٱلۡعُسۡرَ وَلِتُكۡمِلُواْ ٱلۡعِدَّةَ وَلِتُكَبِّرُواْ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡ وَلَعَلَّكُمۡ تَشۡكُرُونَ﴾ [البقرة: ۱۸۵] \"رمضان وہ مہینا ہے جس میں قرآن اتارا گیا، جو لوگوں کی رہ نمائی کرنے والا ہے اور جس میں ہدایت کی اور حق و باطل کی تمیز کی نشانیاں ہیں۔ تم میں سے جو شخص اس ماہ کو پائے اسےصوم(روزہ) رکھنا چاہیے۔ ہاں جو بیمار ہے یا مسافر ہو اسے دوسرے دنوں میں یہ گنتی پوری کرنی چاہیے۔ اللہ کا ارادہ تمھارے ساتھ آسانی کا ہے سختی کا نہیں۔ وہ چاہتا ہے کہ تم گنتی پوری کرلو اور اللہ کی دی ہوئی ہدایت پر اس کی بڑائیاں بیان کوکرو اور اس کا ذکر کرو\"۔\n§صوم(روزہ) کیا ہے؟\nاللہ کی رضا جوئی کے لیے صبح صادق سے لے کر سورج ڈبنے تک کھانے پینے اورجماع سے پرہیزکو صوم(روزہ) کہتے ہیں۔ اس عبادت سے نفس کی پاکیزگی اور اسے اپنے قابوں میں رکھنے میں مدد ملتی ہے۔ اس لیے ان لوگوں کی مذمت کی گئی ہے جو صبح صادق سےسورج ڈوبنے تک بھوکے اور پیاسے رہ کر بھی اپنے نفس کو قابو میں نہیں کرپاتے۔\nابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نےفرمایا: «مَنْ لَمْ يَدَعْ قَوْلَ الزُّورِ وَالْعَمَلَ بِهِ فَلَيْسَ لِلَّهِ حَاجَةٌ فِي أَنْ يَدَعَ طَعَامَهُ وَشَرَابَهُ». (صحیح البخاری: ۱۹۰۳) \"جس نے جھوٹ بولنا اور اس پر عمل کرنا نہ چھوڑا، تو اللہ اس کے بھوکے پیاسے رہنے کا محتاج نہیں\"۔\nابوہریرہ رضی اللہ عنہ سےمروی ایک صحیح حدیث میں صوم(روزے) کی اہمیت بتاتے ہوےنبی اکرم صلی اللہ علیہ وسلم نے فرمايا:«قَالَ اللَّهُ: کُلُّ عَمَلِ ابْنِ آدَمَ لَهُ إِلا الصِّيَامَ فَإِنَّهُ لِي وَأَنَا أَجْزِي بِهِ، وَالصِّيَامُ جُنَّةٌ، وَإِذَا کَانَ يَوْمُ صَوْمِ أَحَدِکُمْ فَلا يَرْفُثْ وَلا يَصْخَبْ، فَإِنْ سَابَّهُ أَحَدٌ أَوْ قَاتَلَهُ فَلْيَقُلْ: إِنِّي امْرُؤٌ صَائِمٌ، وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ لَخُلُوفُ فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ الْمِسْکِ، لِلصَّائِمِ فَرْحَتَانِ يَفْرَحُهُمَا: إِذَا أَفْطَرَ فَرِحَ وَإِذَا لَقِيَ رَبَّهُ فَرِحَ بِصَوْمِهِ». (صحیحالبخاری: ۱۹۰۴، وصحیح مسلم: ۱۱۵۱/۱۶۳) \"اللہ کا کہنا ہے کہ ہر عمل کابدلہ آدمی کو ملتا ہے سوائے صوم(روزے) کے۔ چونکہ وہ میرے لیے (یعنی میری رضاجوئی کے لیے) کھانا پینا چھوڑ دیتا ہے، اس لیے اس کا اجر میں خود دوں گا۔صوم(روزہ) (برائیوں سے رکنے کی) ایک ڈھال ہے تو جس کا صوم(روزہ) ہو اسے چاہیے کہ بے حیائی کی باتیں اور لغو باتیں نہ کرے اور اگر اسے کوئی گالی دے تو کہہ دے کہ بھائی میں صوم(روزے) سے ہوں۔ اللہ کی قسم، صوم (روزے) دار کے منہ سےجو بو نکلتی ہے وہ اللہ کی نظرمیں مشک کی خوشبو سے بھی اچھی ہے۔روزے دار کے لیے دوخوشیاں ہیں: ایک جب وہ صوم (روزہ) کھولتا ہے (یعنی شام کو اور عید کے دن)، دوسری وہ جب اللہ سے ملے گا\"۔\nرمضان کا صوم(روزہ) بغیرکسی شرعی عذرکے چھوڑ نا منع ہے۔ لیکن یہ حدیث جس میں کہا گیا ہے کہ اگر کوئی شخص رمضان میں بغیر کسی علت کے صوم(روزہ) چھوڑ دے تو پوری زندگی کاصوم(روزہ) بھی اس کابدلہ نہیں ہوسکتا۔ یہ سنن کی کتابوں (جیسے: سنن ابی داود: ۲۳۹۶، سنن ترمذی: ۷۲۳، سنن ابن ماجہ: ۱۶۷۲ وغیرہ) میں پائی جاتی ہے۔ مگر یہ ضعیف ہے۔\nچونکہ صوم (روزہ) کی حالت میں کھانا پینا اور جماع منع ہے، تاہم اگرکوئی جماع کرلے تو اسے ایک غلام آزاد کرنا پڑے گا، ایسا نہ کرسکے تو دو مہینے کے(مسلسل)روزے رکھنے پڑیں گے۔ اگر یہ بھی نہ کرسکے تو ساٹھ مسکینوں کو کھانا کھلانا پڑے گا۔ (دیکھیے : صحیح البخاری:۱۹۳۶ وصحیح مسلم:۱۱۱۱)\nیہ اس صورت میں ہے جب کہ شوہر نے بیوی کی مرضی کے خلاف ہم بستری کی ہو۔ لیکن اگر دونوں نے باہم رضامندی سے ایسا کیا ہو تو دونوں پر کفارہ لازم ہوگا۔\nہاں رات میں شوہر بیوی ہم بستری کرسکتے ہیں۔ جان بوجھ کر کھاپی لینے میں صرف قضا ہے کفارہ نہیں جیسا کہ عام محدثین کا قول ہے۔ بہرحال مسئلہ اختلافی ہے۔ (دیکھیے:فتح الباری: شرح حدیث ۱۹۳۵)\n§نفلی صیام کابیان:\nاب بعض ایسےنفلی روزوں کا تذکرہ کیا جاتا ہے جو فرض نہیں ہیں۔\n۱- شوال کے چھ روزے:\nعیدالفطرکے بعدکےچھ دن کے نفلی روزوں کوشش عیدبھی کہتے ہیں۔ ابوایوب انصاری رضی اللہ عنہ سے مروی حدیث میں آیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «مَنْ صَامَ رَمَضَانَ ثُمَّ أَتْبَعَهُ سِتًّا مِنْ شَوَّالٍ کَانَ کَصِيَامِ الدَّهْرِ». (صحیح مسلم: ۲۰۴-(۱۱۶۴) \"جس نے رمضان کے صوم(روزے)رکھے اور اس کے بعد شوال کے چھ صوم(روزے) رکھے تووہ ایسا ہے جیسے کہ اس نے پوری زندگی صوم(روزے) رکھے\"۔\n۲-صیام یوم عرفہ :\n۹ذی الحجہ عرفہ کا دن ہے، جس میں حاجی عرفات کے میدان میں اللہ کی عبادت کے لیے اکٹھا ہوتے ہیں،عرفہ کےدن کےروزے کی بڑی فضیلت آئی ہے۔ابوقتادہ رضی اللہ عنہ سے مروی حدیث میں نبی اکرم صلی اللہ علیہ وسلم نےفرمایا: «صِيَامُ يَوْمِ عَرَفَةَ أَحْتَسِبُ عَلَی اللَّهِ أَنْ يُکَفِّرَ السَّنَةَ الَّتِي قَبْلَهُ وَالسَّنَةَ الَّتِي بَعْدَهُ». (صحیحمسلم: ۱۹۶/۱۱۶۲) \"اس دن کا ٍصوم(روزہ) رکھنے والے کے ایک سال پچھلے اور ایک سال (اگلے) آنے والے میں سارے گناہ معاف ہوجاتے ہیں\"۔\nالبتہ حاجیوں کے لیے بہتر یہی ہے کہ وہ یہ صوم (روزہ) نہ رکھیں۔ (فتح الباری: شرح حدیث ۱۹۸۹)\nالبتہ عام مسلمانوں کے لیے عرفہ کے دن روزہ رہنے کی بڑی فضیلت ہےاوریہ روزہ اس دن رکھیں جس دن مکے میں عرفہ کا دن ہوتا ہے،جو اب ہر فرد بشر کو معلوم ہوجاتا ہے، یہ نہیں کہ ہندوپاک کے حساب سے ۹ ذی الحجہ کو رکھیں، پہلے جب عرفہ کے دن کا علم نہیں ہوپاتا تھا تب بّرصغیروالوں کے لیے ممکن ہو کہ عذر رہا ہو کہ اپنے حساب سے ۹ ذی الحجہ کو رکھیں، لیکن اب یہ عذر باقی نہیں رہ گیا ہے۔\n۳- صیام یوم عاشوراء:\nماہِ محرم کی دسویں تاریخ کے روزے کوعاشوراء کا روزہ کہتے ہیں۔ پہلےیہ فرض تھا، لیکن جب رمضان کےروزے فرض ہوگئے تو یہ نفل ہوگیا۔نبی اکرم صلی اللہ علیہ وسلم نے محرم کی دسویں تاریخ کو عاشوراء کا روزہ رکھاتھااوریہ فرمایاتھا کہ اگر اگلےسال زندگی رہی تو اس کے ساتھ نومحرم کا روزہ بھی رہوں گا، لیکن زندگی نےوفانہ کی،اس لیے سنت یہ ہے کہ نواوردس محرم یا دس اور گیارہ دودن روزے رکھےجائیں اور اگرصرف دس تاریخ ہی کے روزے پراکتفاکیاجائے تویہ جائزہے۔صحیح مسلم میں ہے کہ نبی اکرم صلی اللہ علیہ وسلم سےعاشوراء کے روزے کے بارے میں پوچھاگیا توآپ نے فرمایا: «يُکَفِّرُ السَّنَةَ الْمَاضِيَةَ».\"وہ گزرے ہوئے سال کے لیے کفارہ ہے\"۔\nصحیح مسلم میں آیاہے کہ عبد اللہ بن عباس رضی اللہ عنہما کہتے ہیں : «حِينَ صَامَ رَسُولُ اللَّهِ صلی اللہ علیہ وسلم يَوْمَ عَاشُورَاءَ وَأَمَرَ بِصِيَامِهِ قَالُوا يَا رَسُولَ اللَّهِ إِنَّهُ يَوْمٌ تُعَظِّمُهُ الْيَهُودُ وَالنَّصَارَی فَقَالَ رَسُولُ اللَّهِ صلی اللہ علیہ وسلم فَإِذَا کَانَ الْعَامُ الْمُقْبِلُ إِنْ شَاءَ اللَّهُ صُمْنَا الْيَوْمَ التَّاسِعَ قَالَ فَلَمْ يَأْتِ الْعَامُ الْمُقْبِلُ حَتَّی تُوُفِّيَ رَسُولُ اللَّهِ صلی اللہ علیہ وسلم ».جب رسول اللہ صلی اللہ علیہ وسلم نے عاشوراء کا صوم رکھا اور اسے رکھنے کا حکم دیا تو صحابہ نے عرض کیا: اللہ کے رسول! یہ ایک ایسا دن ہے جس کی یہود و نصاری تعظیم کرتے ہیں تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جب آیندہ سال آئے گا تو ان شاء اللہ ہم نویں تاریخ کو بھی صوم رکھیں گے، ابن عباس کہتے ہیں : آیندہ سال آیا بھی نہیں کہ رسول اللہ صلی اللہ علیہ وسلم کا انتقال ہو گیا۔\n۴- ہر ایک عربی مہینے کی تیرہ، چودہ اور پندرہ تاریخ کےروزے جن کوایام بیض کہاگیاہے،اس لیے کہ ان راتوں میں چاندپورے طورپررہتاہے۔صحیح حدیثوں میں آتا ہے کہ نبی اکرم صلی اللہ علیہ وسلم ان تین دنوں کے صوم(روزے) رکھنا کبھی نہیں چھوڑتے تھے۔\n۵-صیام شعبان :\nام المومنین عائشہڤ کہتی ہیں: «لَمْ يَکُنْ النَّبِيُّ صلی اللہ علیہ وسلم يَصُومُ شَهْرًا أَکْثَرَ مِنْ شَعْبَانَ فَإِنَّهُ کَانَ يَصُومُ شَعْبَانَ کُلَّهُ». (صحیحالبخاری: ۱۹۶۹، وصحیحمسلم: ۱۱۵۶/۱۷۵) \"نبی اکرم صلی اللہ علیہ وسلم رمضان کے علاوہ جس مہینے میں سب سے زیادہ صوم(روزے) رکھتے تھے وہ شعبان کا مہینا تھا\"۔\nخاص پندرہ شعبان کے روزے کے بار میں آئی ہوئی حدیث نہایت ضعیف ہے، یکم شعبان سے ۱۵ تک لگاتار صوم (روزہ)رکھےجا سکتے ہیں، پندرہ شعبان کے بعدنبی اکرم صلی اللہ علیہ وسلم نے امت کو روزہ رکھنے سے منع فرمایا ہے۔(سنن ابن ماجہ:۱۶۵۱)\n۶- پیر اور جمعرات کےصیام:\nنبی اکرم صلی اللہ علیہ وسلم پیر(سوموار،دوشنبہ)اورجمعرات کےروزےپابندی سےرکھتےتھے،کیونکہ ان دونوں دنوں میں آدمی کے عمل کا حساب کتاب اللہ تعالیٰ کے پاس بھیجا جاتا ہے۔ نبی اکرم صلی اللہ علیہ وسلم فرماتے ہیں: میں دوشنبےکے دن پیدا ہوا۔ اسی دن مجھ پر قرآن اتارا گیا،اس لیے میں اس دن صوم(روزہ) رکھتا ہوں۔(دیکھیے:صحیح مسلم:۱۱۶۲/۱۹۷)\n۷- صیام داود :\nایک دن روزہ رکھنےاورایک دن چھوڑنے کو صیام داودی کہتے ہیں۔عبداللہ بن عمروبن العاص رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «صُمْ صَوْمَ دَاوُدَ عليهِ السَّلام: کَانَ يَصُومُ يَوْمًا وَيُفْطِرُ يَوْمًا». (صحیح البخاری: ۱۱۳۱، وصحیحمسلم: ۱۱۵۹/۱۸۷) \"داود علیہ السلام کا صوم رکھو وہ ایک صوم رکھتے ایک دن بغیرصوم کے رہتے\"۔\nیہ نفلی روزوں کا بیان ہے، ان کا رکھناسنت ہے، فرض نہیں۔ تاہم ان روزوں کے اجر وثواب بہت ہیں۔ اس میں مرد و زن دونوں شامل ہیں۔ لیکن عورت کو چاہیے کہ اگر نفلی روزے رکھتی ہے تو اپنے شوہرسے اجازت لےلے۔ ابوہریرہ رضی اللہ عنہ سے مروی حدیث میں نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «لا تَصُومُ الْمَرْأَةُ وَبَعْلُهَا شَاهِدٌ إِلا بِإِذْنِهِ». (صحیح البخاری: ۵۱۹۲،وصحیحمسلم: ۱۰۲۶/۸۴) \"کسی بیوی کے لیے مناسب نہیں کہ شوہر کے گھر میں ہوتے ہوے اس کی اجازت کے بغیر (نفل) صوم(روزے) رکھے\"۔\n§حرام اورناجائزصیام کابیان:\nاب کچھ ایسے روزوں کا ذکر کیا جاتا ہے جن کا رکھناناجائزہے۔\n۱- صوم الدہر:\nعمر بھر روزےرکھنے کوصیام دہرکہتے ہیں، انھیں ناپسندیدہ (مکروہ) کہا گیا ہے۔ایک صحیح حدیث میں عبداللہ بن عمروبن العاص رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «لا صَامَ مَنْ صَامَ الدَّهْرَ». (صحیح البخاری:۱۹۷۹وصحیح مسلم: ۱۱۵۹/۱۸۷) \"جس نےعمر بھر صوم(روزے)رکھے تو سمجھ لو اس نے صوم (روزے)رکھے ہی نہیں\"۔\n۲- جمعہ کاصیام:\nصرف جمعہ کے دن روزہ رکھنا منع ہے۔جابر رضی اللہ عنہ سے سوال کیا گیا کہ کیانبی اکرم صلی اللہ علیہ وسلم نے جمعہ کے صوم (روزے) سے منع فرمایاہے؟ تو انھوں نے کہا:ہاں\"۔(صحیح البخاری: ۱۹۸۴، صحیح مسلم: ۱۱۴۳/۱۱۴۶)۔\nایک دوسری حدیث میں ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم کوفرماتے سنا:\n«لا يَصُومَنَّ أَحَدُکُمْ يَوْمَ الْجُمُعَةِ إِلا يَوْمًا قَبْلَهُ أَوْ بَعْدَهُ». (صحیح البخاری: ۱۹۸۵،صحیح مسلم: ۱۱۴۳/۱۱۴۷) \"صرف جمعہ کاصوم(روزہ) ہرگزمت رکھو۔ اس سے پہلے ایک دن ملا لو یا اس کے بعد کا دن ملا لو\"۔\nاس کے ناپسندیدہ (مکروہ) ہونے کی ایک وجہ یہ بتائی گئی ہے کہ جمعہ عید کا دن ہے، اس لیے اپنے عید کےدن کو صوم(روزے) کا دن نہ بنالو۔ ہاں، اگر اس سے پہلے ایک دن کا ٍصوم(روزہ) رکھنا ہو، یا بعد کے ایک دن کاٍصوم(روزہ) رکھنا ہو تو کوئی حرج نہیں۔\n۳- رمضان کے استقبال میں اس سے پہلے ایک یادودن صوم رکھنا:\nرمضان کے استقبال میں اس سے پہلے ایک یادودن روزہ رکھناجائز نہیں ہے۔ابوہریرہ رضی اللہ عنہ کہتے ہیں نبی اکرم صلی اللہ علیہ وسلم نےفرمایا:«لاَ يَتَقَدَّمَنَّ أَحَدُکُمْ رَمَضَانَ بِصَوْمِ يَوْمٍ أَوْ يَوْمَيْنِ، إِلاَّ أَنْ يَکُونَ رَجُلٌ کَانَ يَصُومُ صَوْمَهُ فَلْيَصُمْ ذَلِکَ الْيَوْمَ». (صحیح البخاری: ۱۹۱۴،صحیح مسلم: ۱۰۸۲/۲۱) \"تم میں سے کوئی رمضان سے ایک دو دن پہلے روزہ نہ رکھے الّا یہ کہ کوئی (مہینہ کے ہر آخری دن) روزہ رکھتا ہو، تو وہ اس دن روزہ رکھ لے\"۔\n۴- عیدیں کےدن کے صیام:\nعید الفطراور عیدالاضحیٰ کےدن روزہ رکھناممنوع ہے۔ابوسعیدخدری رضی اللہ عنہ کہتے ہیں نبی اکرم صلی اللہ علیہ وسلم نےفرمایا: «لاَصَوْمَ فِي يَوْمَيْنِ الْفِطْرِ وَالأَضْحَی». (صحیحالبخاری: ۱۱۹۷، وصحیحمسلم: ۸۲۷/۴۱۵) \"عید الفطر اور عید الاضحیٰ کے دن صوم رکھنا منع ہے\"۔\n۵-ایام تشریق کے صیام:\nذی الحجہ کی گیارہ، بارہ اور تیرہ تاریخوں کو ایام تشریق کہا جاتا ہے۔ان دنوں میں قربانی کی جاتی ہے۔یہ اللہ کی یاداورکھانے پینے کے دن ہیں۔اس لیے ان دنوں میں روزہ رکھنے کی ممانعت آئی ہے۔ کعب بن مالک رضی اللہ عنہ کہتے ہیں کہ ایام تشریق میں ان کو اور اوس بن حدثان کویہ اعلان کرنے کے لیے بھیجا: «إِنَّهُ لا يَدْخُلُ الْجَنَّةَ إِلا مُؤْمِنٌ وَأَيَّامُ مِنًی أَيَّامُ أَکْلٍ وَشُرْبٍ». (صحیحمسلم: ۱۴۵/۱۱۴۲) \" جنت میں صرف مومن داخل ہوگا اور یہ کہ ایام تشریق کھانے پینے کے دن ہیں\"۔\nسعد بن ابی وقاص رضی اللہ عنہ کہتے ہیں:«أَمَرَنِی رَسُولُ اللَّهِ صلی اللہ علیہ وسلم أَنْ أُنَادِیَ أَيَّامَ مِنًی إِنَّهَا أَيَّامُ أَکْلٍ وَشُرْبٍ فَلاَ صَوْمَ فِيهَا يَعْنِی أَيَّامَ التَّشْرِيقِ». (مسند احمد: ۱۴۷۳) \"نبی اکرم صلی اللہ علیہ وسلم نے مجھے حکم دیا کہ منی میں یہ اعلان کردوں کہ یہ کھانے پینے کے دن ہیں۔ان دنوں میں صوم(روزہ) نہیں ہوتا\"۔\nان دنوں میں حج تمتع والا حاجی صوم(روزہ) رکھ سکتا ہے،جوہدی (قربانی)نہ پیش کرسکے۔جس کی طرف قرآن کریم اشارہ کرتا ہے: [آیت] [البقرة:۹۶ا] \"جو شخص عمرے سے لے کر حج تک تمتع کرلے، تو وہ جوقربانی کر سکتا ہوکرے اور جسے قربانی میسر نہ ہو تو حج کے دنوں میں تین دنوں کے صوم(روزے) رکھے اور سات دنوں کے صوم(روزے) واپسی پر(رکھے) یہ پورے دس دن ہوے\"۔\nاگر وہ تین دن حج سے پہلے ٍصوم(روزہ) نہ رکھ سکا ہو اور ایام تشریق میں رکھنا چاہتا ہو تو رکھ سکتا ہے۔ (صحیح البخاری:۱۹۹۹) یہ رائے ابن عمر اور عائشہ کی ہے اور یہی رائے دوسرے فقہا کا بھی ہے۔ اس کے متعلق کوئی صحیح حدیث نہیں آئی ہے۔","",{}],[389,"§ضحی\nضحیٰ کے معنیٰ ہیں دن چڑھا وقت۔ وہ وقت جوسورج نکلنے کےتقریباً پندرہ منٹ کے بعد سے زوال یعنی سورج ڈھلنے سے کچھ پہلے اوربعض علماکے بقول ظہر کے وقت سے دس منٹ پہلے تک ہے۔یہ وقت دُنیوی کاموں کے لیے بہت اچھا سمجھا جاتا ہے۔اس لیے موسیٰ علیہ السلام کے ساتھ جادوگروں کو مقابلے کے لیے یہی وقت طے کیا گیا۔ قرآن میں ہے: ﴿قَالَ مَوۡعِدُكُمۡ يَوۡمُ ٱلزِّينَةِ وَأَن يُحۡشَرَ ٱلنَّاسُ ضُحࣰ ى﴾ [طه: ۵۹] \"اس موسیٰ نے کہا:تم سے مقابلے کا وقت جشن منانے کا دن ہے اور یہ کہ لوگ دن چڑهے جمع ہوجائیں\"۔\nاس وقت اللہ سے غافل ہوجا نا بہت ممکن ہے۔اس سے بچنے کا مناسب وسیلہ صلاۃ الضحیٰ (چاشت کی نماز)ہے،جس کا تفصیلی بیان لفظ \"صلاۃ\" میں دیکھیں۔رات کو سوتے ہوے اور دن کو کام کاج کرتے ہوئےبہت سے لوگ غافل ہوجاتے ہیں، اس کی قرآن میں مذمت کی گئی ہے:﴿أَفَأَمِنَ أَهۡلُ ٱلۡقُرَىٰٓ أَن يَأۡتِيَهُم بَأۡسُنَا بَيَٰتࣰ ا وَهُمۡ نَآئِمُونَ أَوَأَمِنَ أَهۡلُ ٱلۡقُرَىٰٓ أَن يَأۡتِيَهُم بَأۡسُنَا ضُحࣰ ى وَهُمۡ يَلۡعَبُونَ﴾ [الأعراف: ۹۷-۹۸] \"تو کیا بستیوں کے لوگ اس سے غافل ہوگئے کہ ہمارا عذاب رات کے وقت ان پر آجائے، جب کہ وہ پڑے سورہے ہوں یا بستیوں کے لوگ اس سے غافل ہیں کہ ہمارا عذاب دن چڑهنے پر ان پر آجائے، جب کہ وہ کھیل کود میں لگے ہوں\"۔\nاس لیے نبی اکرم صلی اللہ علیہ وسلم اللہ کی یاد سے کبھی غافل نہیں ہوتے تھے۔ بلکہ صحیح احادیث میں آتا ہے کہ آپ صلی اللہ علیہ وسلم اللہ کی یاد ہر لمحہ کیا کرتے تھے۔ اللہ کی یاد کا سب سے اچھا ذریعے تہجد اور ضحیٰ کی نماز ہے۔\nاس لیے سورة الشمس میں اللہ نے چڑهتے دن کی قسم کھائی ہے۔ بلکہ ضحیٰ نام کی ایک سورة بھی نازل فرمائی، جس کی ابتدا ضحیٰ (چڑهتے دن) کی قسم سے کی۔چونکہ اس چڑهتے دن کے وقت گرمیوں میں دھوپ تیز ہوجاتی ہے،اس لیے جنت میں جانے والوں کو یہ خوشخبری دی جاتی ہے : ﴿وَأَنَّكَ لَا تَظۡمَؤُاْ فِيهَا وَلَا تَضۡحَىٰ﴾ [طه: ۱۱۹] \"تم نہ اس میں پیاسے رہو گے اور نہ دھوپ کی تکلیف اٹهاؤ گے\"۔","",{}],[390,"§ضفدع\nضفدع،اس کی جمع ضفادع ہے، اس کو اردو میں مینڈک کہتےہیں۔یہ زمین اور پانی میں رہنے والا جانور ہے۔ اللہ تعالیٰ نے فرعون اور اس کی قوم پر جو عذاب نازل کیا، ان میں مینڈک بھی تها۔مینڈک جھنڈ کے جھنڈ سارے مصر میں پهیل گئے تھے۔قرآن مجیدمیں ہے:﴿فَأَرۡسَلۡنَا عَلَيۡهِمُ ٱلطُّوفَانَ وَٱلۡجَرَادَ وَٱلۡقُمَّلَ وَٱلضَّفَادِعَ وَٱلدَّمَ ءَايَٰتࣲ مُّفَصَّلَٰتࣲ فَٱسۡتَكۡبَرُواْ وَكَانُواْ قَوۡمࣰ ا مُّجۡرِمِينَ﴾ [الأعراف: ۱۳۳] \"پھرہم نے ان پر طوفان، ٹڈیاں، جوئیں،مینڈک اور خون کی نشانیاں ظاہری طور پر بھیجیں۔لیکن انھوں نے سرکشی ہی کی اور وہ تھے مجرم لوگ\"۔بائبل میں بھی مینڈکوں کے عذاب کاذکر تفصیل سے آیا ہے۔(بائبل-خروج :۸:اـ۴ا)","",{}],[391,"§ضيافت\nضیافت یعنی مہمان نوازی کی اسلام میں بڑی اہمیت ہے۔قرآن مجید میں ابراہیم علیہ السلام کے معزز مہمانوں کا ذکر اس طرح آیاہے: ﴿هَلۡ أَتَىٰكَ حَدِيثُ ضَيۡفِ إِبۡرَٰهِيمَ ٱلۡمُكۡرَمِينَ إِذۡ دَخَلُواْ عَلَيۡهِ فَقَالُواْ سَلَٰمࣰ اۖ قَالَ سَلَٰمࣱ قَوۡمࣱ مُّنكَرُونَ فَرَاغَ إِلَىٰٓ أَهۡلِهِۦ فَجَآءَ بِعِجۡلࣲ سَمِينࣲ فَقَرَّبَهُۥٓ إِلَيۡهِمۡ قَالَ أَلَا تَأۡكُلُونَ﴾ [الذاریات: ۲۴-۲۷] \"کیا تجھ کو ابراہیم علیہ السلام کے معزز مہمانوں کی خبر بھی پہنچی ہے؟وہ جب ان کے ہاں آئے توسلام کیاابراہیم نے جواب سلام دیا(اورکہایہ تو)اجنبی لوگ ہیں۔پھر (چپ چاپ جلدی جلدی) اپنے گھروالوں کی طرف گئے اور ایک فربہ بچھڑے(کاگوشت) لائےاور اسے ان کے پاس رکھا اور کہا: آپ لوگ کھاتے کیوں نہیں؟\"۔\nیہ مہمان درحقیقت فرشتے تهےجوابراہیم علیہ السلام کویہ خوش خبری دینے آئے تھے کہ آپ کے یہاں ایک بچہ پیدا ہونے والا ہے۔ابراہیم علیہ السلام کا بھنے ہوےبچھڑے کے ذریعےسے اپنے مہمانوں کی ضیافت کرنا ان کی اہمیت کوظاہر کرتاہے۔خاتم النبین محمد صلی اللہ علیہ وسلم نےبھی مہمان کی ضیافت اور اس کی فضیلت کا مختلف انداز سے ذکر فرمایا ہے۔ابوہریرہ رضی اللہ عنہ سےمروی حدیث میں نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «مَنْ کَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ فَلْيُکْرِمْ ضَيْفَهُ». (صحیح البخاری: ۶۰۱۸، صحیحمسلم: ۴۷/۷۵) \"جوااللہ اور قیامت کے دن پر ایمان رکھتاہے وہ اپنے مہمان کی تکریم کرے\"۔\nمگر اس کے ساتھ ہی مہمان کے بھی کچھ فرائض بتائے گئے ہیں۔ان میں سے ایک یہ ہے کہ تین دن سے زیادہ وہ کسی کے یہاں قیام نہ کرے۔ابوشریح کعبی رضی اللہ عنہ سے مروی حدیث میں نبی اکرم صلی اللہ علیہ وسلم نے فرمایا:«مَنْ کَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ فَلْيُکْرِمْ ضَيْفَهُ، جَائِزَتُهُ يَوْمُهُ وَلَيْلَتُهُ، الضِّيَافَةُ ثَلاثَةُ أَيَّامٍ، وَمَا بَعْدَ ذَلِکَ فَهُوَ صَدَقَةٌ، وَلا يَحِلُّ لَهُ أَنْ يَثْوِيَ عِنْدَهُ حَتَّی يُحْرِجَهُ». (سنن ابی داود: ۳۷۴۸) \"جو اللہ اور یوم آخرت پر ایمان رکھتا ہے، وہ اپنے مہمان کی تکریم کرے۔ مہمان کی تکریم ایک دن ورات ہے اور ضیافت تین دن۔ اس کے بعد صدقہ ہے۔مہمان کے لیے جائز نہیں کہ وہ میزبان کے پاس تین دن سے زیادہ قیام کرےاور اسے تنگی میں ڈال دے\"۔\nایک دوسری روایت میں ابوہریرہ رضی اللہ عنہ سے مروی ہے نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «الضِّيَافَةُ ثَلاثَةُ أَيَّامٍ، فَمَا سِوَی ذَلِکَ فَهُوَ صَدَقَةٌ». (سنن ابی داود: ۳۷۴۹) \"مہمانی تین روز ہے اس کے بعد صدقہ ہے\"۔","",{}],[392,"§ضیف\nدیکھیے: ضيافت (مہمان نوازی)","",{}],[393,"§طاغوت\nقرآن مجیدمیں طاغوت کالفظ آٹھ بار استعمال ہوا ہے۔(سورہ البقرہ :۲۵۶، ۲۵۷،سورہ النساء: ۷۶،۶۰،۵۱، سورہ المائدہ: ۶۰، سورہ النحل: ۳۶ اورسورہ الزمر: ۱۷)\nہر جگہ پر ایک ہی معنیٰ ہے کہ اگراللہ تعالیٰ کو چھوڑ کر کسی غیر کی عبادت کی جائے خواہ وہ انسان ہوں، بت ہوں یا شیطان۔یہ سب طاغوت ہیں،کیونکہ انھوں نے اللہ کا جو حق اس کے بندوں پر ہوتا ہے اس میں زیادتی کی اور عبادت کے حق کو اس کے بندوں کو دے دیا۔ ارشاد باری تعالیٰ ہے :\n۱-﴿لَآ إِكۡرَاهَ فِي ٱلدِّينِۖ قَد تَّبَيَّنَ ٱلرُّشۡدُ مِنَ ٱلۡغَيِّۚ فَمَن يَكۡفُرۡ بِٱلطَّٰغُوتِ وَيُؤۡمِنۢ بِٱللَّهِ فَقَدِ ٱسۡتَمۡسَكَ بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰ لَا ٱنفِصَامَ لَهَاۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ﴾ [البقرة: ۲۵۶] \"جو طاغوت کو ٹھکرا دے اور اللہ پر ایمان لائے، اس نے مضبوط سہارا تھام لیا\"۔\n۲-﴿ٱللَّهُ وَلِيُّ ٱلَّذِينَ ءَامَنُواْ يُخۡرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۖ وَٱلَّذِينَ كَفَرُوٓاْ أَوۡلِيَآؤُهُمُ ٱلطَّٰغُوتُ يُخۡرِجُونَهُم مِّنَ ٱلنُّورِ إِلَى ٱلظُّلُمَٰتِۗ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ﴾ [البقرة: ۲۵۷] \"اللہ ان لوگوں کا ولی(محافظ)ہے جو ایمان لائیں۔وہ انھیں اندھیروں سے نکال کر روشنی کی طرف لاتا ہےاور جن لوگوں نے کفر کیا ان کے ولی(محافظ) طاغوت ہیں۔وہ انھیں روشنی سے نکال کراندهیروں کی طرف لے جاتے ہیں۔یہی لوگ جہنم والے ہیں جس میں وہ ہمیشہ رہیں گے\"۔\n۳-﴿أَلَمۡ تَرَ إِلَى ٱلَّذِينَ أُوتُواْ نَصِيبࣰ ا مِّنَ ٱلۡكِتَٰبِ يُؤۡمِنُونَ بِٱلۡجِبۡتِ وَٱلطَّٰغُوتِ وَيَقُولُونَ لِلَّذِينَ كَفَرُواْ هَٰٓؤُلَآءِ أَهۡدَىٰ مِنَ ٱلَّذِينَ ءَامَنُواْ سَبِيلًا﴾ [النساء: ۵۱] \"کیا تم نے ان لوگوں کو نہیں دیکھا جنھیں کتاب کا ایک حصہ دیا گیا؟ وہ جبت اور طاغوت(شیطان، بت،کاہن، ساحراورماسوااللہ ہرمعبود)پر ایمان لاتے ہیں\"۔\n۴- ﴿فَلَمَّا جَآءَ سُلَيۡمَٰنَ قَالَ أَتُمِدُّونَنِ بِمَالࣲ فَمَآ ءَاتَىٰنِۦَ ٱللَّهُ خَيۡرࣱ مِّمَّآ ءَاتَىٰكُمۚ بَلۡ أَنتُم بِهَدِيَّتِكُمۡ تَفۡرَحُونَ﴾ [النمل: ۳۶] \"ہم نے ہر قوم میں کوئی نہ کوئی رسول بھیجا کہ اللہ کی عبادت کرو اور طاغوت(معبودان باطل) سے بچو\"۔\n۵- ﴿وَٱلَّذِينَ ٱجۡتَنَبُواْ ٱلطَّٰغُوتَ أَن يَعۡبُدُوهَا وَأَنَابُوٓاْ إِلَى ٱللَّهِ لَهُمُ ٱلۡبُشۡرَىٰۚ فَبَشِّرۡ عِبَادِ﴾ [الزمر: ۱۷] \"جو لوگ طاغوت(معبودان باطل) کی عبادت سے بچے اور اللہ کی طرف پلٹے ان کے لیے خوشخبری ہے،تو میرے بندوں کو خوش خبری دے دو \"۔","",{}],[394,"§طالوت\nطالوت کو بائبل میں شاول کہا گیا ہے۔ بائبل میں آیا ہے کہ شاؤل بہت لمبا چوڑا تھا۔(دیکھیے: شموئیل اوّل: ۲۳؛ ۱۰) قرآن نے بھی اس کی تصدیق کی ہے۔(دیکھیے: سورہ البقرہ: ۲۴۷)اس لیےشاؤل عربوں میں اپنے بھاری جسم کی وجہ سے طالوت کے لقب سے مشہور ہوگیا تھا۔جس کے معنی ہیں لمبا چوڑا۔اس لیے قرآن نے اس کے نام کی جگہ پر اس کے لقب کا استعمال کیا ہے جو جالوت کے وزن پر ہے۔\nطالوت کے بارے میں جو معلومات ملی ہیں، وہ یہ ہیں کہ بنی اسرئیل فلسطین میں داخل ہوتے ہی مختلف طرح کی پریشانیوں میں گهرگئے۔سب سے بڑی پریشانی یہ تھی کہ فلسطین اور آس پاس کے ملک کے باشندوں کے ساتھ جنگ شروع ہوگئی، کیونکہ بنی اسرئیل وہاں طاقت کےزور پرداخل ہوے تهے۔وہاں کےباشندوں پر بہت ظلم کیا۔اس لیے ان کے دلوں میں بنی اسرئیل کے خلاف شدید نفرت تهی۔ایک وقت ایسا بھی آیا کہ فلسطینیوں نے بنی اسرائیل کو شکست دے دی اور ان سے وہ تابوت بھی چھین لیا، جس کو لے کر وہ مصر سے آئے تهے۔چونکہ ان کا کوئی بادشاہ نہیں تھا،اس لیے وہ بے ڈھنگی اور بے کار زندگی گزارا کرتے تھے۔اب انھوں نے اپنے نبی شمویل سے گزارش کی کہ ہمارے لیےایک بادشاہ منتخب کر دیجیے جس کے ساتھ مل کر ہم اپنے دشمنوں سے جنگ کریں۔نبی چونکہ ان کے رویّے کو جانتے تھے، اس لیے کہا: ہر گز تم ایسا نہ کرو۔ انھوں نے کہا:کیوں نہیں،ہم ایساہی کریں گے۔کیونکہ ہم گھر سے بے گھر ہوگئے ہیں۔ لیکن وہی ہوا جس بات پر نبی شمویل نے شک ظاہر کیا تھا۔قرآن مجید اس واقعےکو یوں بیان کرتا ہے: ﴿أَلَمۡ تَرَ إِلَى ٱلۡمَلَإِ مِنۢ بَنِيٓ إِسۡرَٰٓءِيلَ مِنۢ بَعۡدِ مُوسَىٰٓ إِذۡ قَالُواْ لِنَبِيࣲّ لَّهُمُ ٱبۡعَثۡ لَنَا مَلِكࣰ ا نُّقَٰتِلۡ فِي سَبِيلِ ٱللَّهِۖ قَالَ هَلۡ عَسَيۡتُمۡ إِن كُتِبَ عَلَيۡكُمُ ٱلۡقِتَالُ أَلَّا تُقَٰتِلُواْۖ قَالُواْ وَمَا لَنَآ أَلَّا نُقَٰتِلَ فِي سَبِيلِ ٱللَّهِ وَقَدۡ أُخۡرِجۡنَا مِن دِيَٰرِنَا وَأَبۡنَآئِنَاۖ فَلَمَّا كُتِبَ عَلَيۡهِمُ ٱلۡقِتَالُ تَوَلَّوۡاْ إِلَّا قَلِيلࣰ ا مِّنۡهُمۡۚ وَٱللَّهُ عَلِيمُۢ بِٱلظَّٰلِمِينَ﴾ [البقرة: ۲۴۶] \"کیاتم نے بنی اسرائیل کے سرداروں کو نہیں دیکھا، جب موسیٰ کے بعد انھوں نے اپنے ایکنبی سے کہا کہ ہمارے لیے ایک بادشاہ منتخب کردیجیے تاکہ ہم اللہ کی راہ میں جنگ کریں۔اس نے کہا:ایسا نہ ہو کہ تم پر جنگ فرض کر دی جائے تو تم جنگ نہ کرو۔کہنے لگے: ہم اللہ کی راہ میں جنگ کیوں نہ کریں گے جب کہ ہمیں اپنے گھروں سے نکال دیا گیا ہے اور اپنی آل اولادسے بھی الگ کردیا گیا ہے۔ پھر جب ان پر جنگ واجب کردی گئی تو ان میں سے تھوڑے لوگوں کے سوا سب منہ موڑگئےاور اللہ ظالموں کو اچھی طرح جانتا ہے\"۔\nنبی شمویل نے ان کی درخواست پر طالوت نامی ایک شخص (شاول) کو بادشاہ منتخب کردیا، جو بنیامین کےخاندان سے تھا،غریب بھی تھا۔بنی اسرائیل بول اٹھے: تم نے ایسے شخص کو ہمارا بادشاہ بنادیا ہے جوادنیٰ خاندان کا ہے اور غریب ہے۔نبی نے کہا: اللہ نے طالوت کو اس وجہ سے بادشاہ بنا یا ہے کہ وہ بہت عقل مند اور طاقتور ہے۔\nقرآن مجیدمیں ارشاد ہے:﴿وَقَالَ لَهُمۡ نَبِيُّهُمۡ إِنَّ ٱللَّهَ قَدۡ بَعَثَ لَكُمۡ طَالُوتَ مَلِكࣰ اۚ قَالُوٓاْ أَنَّىٰ يَكُونُ لَهُ ٱلۡمُلۡكُ عَلَيۡنَا وَنَحۡنُ أَحَقُّ بِٱلۡمُلۡكِ مِنۡهُ وَلَمۡ يُؤۡتَ سَعَةࣰ مِّنَ ٱلۡمَالِۚ قَالَ إِنَّ ٱللَّهَ ٱصۡطَفَىٰهُ عَلَيۡكُمۡ وَزَادَهُۥ بَسۡطَةࣰ فِي ٱلۡعِلۡمِ وَٱلۡجِسۡمِۖ وَٱللَّهُ يُؤۡتِي مُلۡكَهُۥ مَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمࣱ‏﴾ [البقرة: ۲۴۷] \"ان کے نبی نے ان سے کہا: اللہ نے تمھارے لیے طالوت کوبادشاہ منتخب کیا ہے۔وہ بولے: یہ کیسے ہوسکتاہےکہ وہ ہمارا بادشاہ بن جائے جب کہ اس کے مقابلے میں ہم بادشاہت کے زیادہ حق دار ہیں۔جب کہ اسے تو مال و دولت کی وسعت بھی حاصل نہیں ہے۔اس نے کہا: اللہ نے تم پر اسی کو منتخب کیا ہےاوراسے علم اور جسمانی طاقت میں برتری عطا کی ہےاور اللہ جسے چاہتا ہے اپنی حکومت عطا کرتا ہے۔اللہ بہت کشادگی والا اور علم والا ہے\"۔\nطالوت نے جو بنی اسرئیل کا پہلا بادشاہ تھا جوانوں کی ایک فوج بنائی اور اپنی فوج لے کر فلسطینیوں سے مقابلہ کے لیےنکل پڑا۔کیونکہ فلسطینی بنی اسرئیل سے جنگ کرنے کے لیے جمع ہوگئے تھے، فلسطینی فوج میں ایک شخص تھا جس کا نام جالوت تھا جو بڑابہادر، با رعب اورلمبا چوڑا تھا۔ بائبل نے اس کی لمبائی چھے ہاتھ کی بتائی ہے، جس کا پورا جسم لشکری لباس سے ڈهکاہوا تھا۔(دیکھیے :شمویل:۱۔ ۱۷:۴)\nداودنےپتهر مار کر اسےہلاک کر دیا۔ (دیکھیے: شمویل:۱/۱۷:۴۹)یہ دیکھتے ہی فلسطینی گھبرا گئے اور بهاگے۔ طالوت کی فوج نے ان کا پیچھاکیا اور بہت سارے فلسطینیو ں کو قتل کرڈالا۔طالوت نے داودکو اپناوزیربنا لیا اور اپنی بیٹی سے ان کی شادی کردی۔ لیکن جب دیکھا کہ بنی اسرئیل داود کو زیادہ چاہتے ہیں تو اسے ڈر ہوا کہ کہیں وہ اس کی حکومت نہ چھین لیں، اس لیے ان کو قتل کرنے کا ارادہ کرلیا۔جب داودکو اس کا علم ہوا تو وہ بھاگ پڑے۔ادهرطالوت اور فلسطینیوں میں جلووع کی جگہ پر دوبارہ جنگ چھڑگئی۔اس بارطالوت اپنے تین بیٹوں کے ساتھ مارا گیا۔کہا جاتا ہے کہ اس نے خود کشی کرلی تھی اس لیے کہ وہ نہیں چاہتا تھا کہ شکست ہونے پر کوئی فلسطینی اس کا قتل کرے۔یہ تقریباً۱۰۵۵ ق م کا واقعہ ہے۔اس کے بعد لوگوں نے داود علیہ السلام کو اپنا بادشاہ بنا لیا۔ انھوں نے تقریباً ۱۰۱۵ق م تک حکومت کی اس طرح داود علیہ السلام انبیامیں پہلے اور بنی اسرئیل میں دوسرے بادشاہ مانے جاتے ہیں۔","",{}],[395,"§طس\nدیکھیے: الم","",{}],[396,"§طسم\nدیکھیے: الم","",{}],[397,"§طلاق\nطلاق کا مطلب میاں بیوی میں جدائی ہے۔ یہ ایک ناگزیر عمل ہے جس کا آدمی چار وناچار سامنا کرتا ہے۔ دراصل شادی کرنے کا مقصد یہ ہوتا ہے کہ میاں بیوی دونوں مل کراچھی زندگی گزاریں اوراپنی آنےوالی اولادکی پرورش کریں۔لیکن کبھی کبھی کچھ ایسے حالات پیدا ہوجاتے ہیں جن میں دونوں کا ایک ساتھ رہنا ناممکن ہوجاتا ہے۔ایسی صورت میں طلاق کے سوا کوئی اور راستا نہیں بچتا۔یہ ایک قدیم طریقہ ہے۔بائبل میں بھی طلاق کا ذکر آتا ہے۔ لوقا کی انجیل میں ہے :\nجوکوئی اپنی بیوی کو چھوڑ کر دوسری عورت سے شادی کرتا ہے، وہ زنا کرتا ہے اور جو شخص شوہر کی چھوڑی ہوئی عورت سے شادی کرتا ہے وہ بھی زنا کرتا ہے۔ (لوقا:۱۶:۱۸)\nلیکن انجیل متی میں حرامکاری کرنے کی حالت میں طلاق کا حکم ملتا ہے :\nلیکن میں تم سے یہ کہتا ہوں کہ جو کوئی اپنی بیوی کو حرام کاری کے سوا کسی اور وجہ سے چھوڑے گا وہ اس سے زنا کراتا ہے اور جو کوئی اس چھوڑی ہوئی عورت سے شادی کرے گا وہ زنا کرتا ہے(متی:۵:۳۲)\nاس کا مطلب یہ ہوا کہ زنا کا عمل سرزد ہونے کے سوا کوئی عیسائی اپنی بیوی کو کسی دوسری وجہ سے طلاق نہیں دے سکتا اور اگر طلاق دے دی تو دوسرا مرد اس سے شادی نہیں کرسکتا۔اس طرح کی تعلیمات کے سبب عیسائی معاشرے نے طلاق کے اصول کو ہی چھوڑدیا اور پھر ایسی سخت پابندی لگا دی جن کی بجاآوری ناممکن ہوگئی۔\nاسلام ایک اعتدال پسند مذہب ہے۔قرآن کریم میں آیا ہے:﴿وَكَذَٰلِكَ جَعَلۡنَٰكُمۡ أُمَّةࣰ وَسَطࣰ ا لِّتَكُونُواْ شُهَدَآءَ عَلَى ٱلنَّاسِ وَيَكُونَ ٱلرَّسُولُ عَلَيۡكُمۡ شَهِيدࣰ اۗ وَمَا جَعَلۡنَا ٱلۡقِبۡلَةَ ٱلَّتِي كُنتَ عَلَيۡهَآ إِلَّا لِنَعۡلَمَ مَن يَتَّبِعُ ٱلرَّسُولَ مِمَّن يَنقَلِبُ عَلَىٰ عَقِبَيۡهِۚ وَإِن كَانَتۡ لَكَبِيرَةً إِلَّا عَلَى ٱلَّذِينَ هَدَى ٱللَّهُۗ وَمَا كَانَ ٱللَّهُ لِيُضِيعَ إِيمَٰنَكُمۡۚ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفࣱ رَّحِيمࣱ‏﴾ [البقرة: ۱۴۳] \"اسی طرح ہم نے تمھیں ایک وسط امت بنا دیا۔ تاکہ تم سارے انسانوں کے لیے گواہ بنو\"۔\nاس لیےمیاں بیوی کے درمیان تعلقات خراب ہوجانے کے بعد اگر نباہ مشکل ہوجائے تو اسلام میں مرد کوطلاق دینے کی اجازت دی ہے۔بعض صورتوں میں طلاق کو لازم اوربعض حالتوں میں مناسب بتایاگیاہے۔کیوں کہ جب شوہربیوی باہمی محبت کےساتھ زندگی نہیں گزار سکتے،تو پھر نفرت کے ساتھ زندگی گزارنا، زندگی کی لذتوں کو بربادکرنا ہے۔ بلکہ ان دونوں اور ان کی اولادکے لیے بھی یہ ایک بہت بڑا عذاب بن جاتا ہے۔ اس لیے اس مسئلے کا صرف ایک ہی حل ہے کہ دونوں الگ ہو جائیں۔\n§طلاق دینے کا صحیح طریقہ:\nاگرشوہراور بیوی کاایک ساتھ رہناناممکن ہو اور طلاق دینا لازم ہو جائے تو اس کا صحیح طریقہ یہ ہےکہ جب بیوی حیض سے پاک ہو اور شوہر نے اس کے ساتھ ہمبستری نہ کی ہوتو ایک بار طلاق دے اور اسی ایک طلاق پر عدت (تین حیض) گزرجانے دے۔ اس عدت کے درمیان بیوی شوہر کے گھرمیں ہی رہےگی۔اس کا نان ونفقہ شوہر کے ذمہ ہوگا۔ اس طرح ایک ہی طلاق پر عدت گزر جانے کا فائدہ یہ ہوگا کہ (۱) یاتو اسی عدت کے دوران دونوں کےمابین صلح وصفائی کی نوبت آجائے تو صرف رجعت سے کام چل جائے گا، (۲) اور اگر عدت گزر گئی تو بھی بغیر حلالہ کے نکاحِ جدید کے ذریعے دونوں دوبارہ رشتہٴ ازدواج میں منسلک ہوسکتے ہیں اور اگر شوہر تین طلاق دینا ہی چاہتا ہے توپھر جب ایک ماہ پاکی کا گزر جائے پھر حیض آجائے اور پھر اس سے پاک ہوجائے تو اس مدت میں دوسری طلاق دے۔پهر اسی طرح وہ پاک ماہ گزر جائے اور پھر حیض آجائے اور پھر اس سے پاک ہوجائے تو اس مدت میں تیسری بار طلاق دے۔ اس تیسری طلاق کے بعد دونوں کو ہمیشہ کے لیے الگ کر دیا جائے گا۔اسے طلاق مغلظہ کہتے ہیں۔طلاق مغلظہ کے بعد اگر بیوی نے کسی اور سے ہمیشگی کی نیت سے شادی کرلی اور اس سے ہمبستری کرنے کے بعد طلاق ہوگئی یا شوہر کا انتقال ہوگیا۔تو ایسی صورت میں وہ اپنے پہلے شوہر سے دوبارہ شادی کرسکتی ہے۔اس کے بغیر وہ پہلے شوہر سے شادی نہیں کرسکتی۔\nعدت کے لیے پورے تین ماہ اس لیے رکھے گئے ہیں کہ اگر اس درمیان میں وہ دونوں آپس میں رہنے پر راضی ہوجائیں تو شوہر کو چاہیے کہ طلاق سے رجوع کر لے، جس کا طریقہ یہ ہے کہ یا تو :\n۱- دو گواہوں کے سامنے زبان سے یہ کہے کہ میں طلاق سے رجوع کرتا ہوں۔ یہی صورت افضل ہے۔\n۲-یا بیوی سے ہمبستری کرلے۔ یہ بہتر نہیں ہے۔ یاد رہے کہ ان تین مہینوں میں نہ بیوی شوہر کے گھر سے نکلے اور نہ ہی شوہر اس کو اپنے گھر سے نکالے۔اس کی وجہ یہ ہے کہ اس طرح ندامت کرتے ہوے ممکن ہے کہ دونوں کو اپنی غلطی کا احساس ہوجائے اور دونوں اپنے اپنے رویّے کودرست کرلیں، تاکہ دو دل جو کبھی ایک ہوگئے تھے،اب جدا ہونے سے بچ جائیں۔\n§طلاق دینے کا غلط طریقہ:\nا-حیض کی حالت میں طلاق دینا غلط ہے:عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ جب انھوں نے اپنی بیوی کو حیض کی حالت میں طلاق دے دی تھی تو نبی اکرم صلی اللہ علیہ وسلم نےان کو حکم دیا کہ اس سے رجوع کرلیں پھر جب وہ حیض سےپاک ہوجائے پھر حیض آئے، پھر اس دوسرے حیض سے پاک ہوجائے تو چاہیں اس کو روک لیں اور چاہیں تو طلاق دے دیں۔لیکن اگر کسی نے حیض کی حالت میں طلاق دے دی تواس کو ایک طلاق شمار کیا جائے گا یا نہیں؟علماء کا اس میں اختلاف ہے۔ صحیح یہی ہے کہ اسے ایک طلاق شمار کیا جائے گا۔ جیسا کہ ابن عمر رضی اللہ عنہما نے خود بتایا ہے کہ اسے ایک طلاق مانا گیا۔(صحیح البخاری: ۵۲۵۲، وصحیح مسلم: ۱۴۷۱)۔\n۲-اسی طرح پاکی والے مہینے میں طلاق دینا جس میں ہمبستری کی ہو،لیکن حمل نہ ہو۔اس طرح طلاق دینے والا گناہ گار ہوگا البتّہ اس کی طلاق شمار کی جائے گی۔\n۳-ایک بار میں ایک سے زیادہ طلاق دینا گناہ ہے۔کوئی ایک بار میں تین طلاق دے دے تو اب اس کی تین طلاق شمار کی جائےگی یا نہیں؟ اس بارے میں علما میں اختلاف ہے۔لیکن تحقیقی بات یہی ہے کہ وہ ایک ہی شمار کی جائے گی۔ مزید معلومات حاصل کرنے کے لیے میری عربی کتاب(المنۃ الکبری) دیکھیے۔ لیکن یہاں پراس بات پر تنبیہ ضروری ہےکہ یک بارگی تین طلاقوں کو تین لاگو ماننے والے یہ کام بہت ہی غلط کرتے ہیں کہ ایک رات کے لیے کسی دوسرے مرد سے پلاننگ کے تحت اس مطلقہ عورت کا نکاح کراتے ہیں، پھر یہ دوسرا آدمی صبح کو طلاق دے دیتا ہے، پھر عدت گزار کراس کی پہلے شوہر سے شادی کرا دیتے ہیں اور اس کا نام شرعی حلالہ رکھتے ہیں۔ جب کہ اس کا نام ملعون حلالہ رکھناچاہیےکیوں کہ ایسے حلالہ کرنے اور کروانے والے دونوں پر رسول اللہ صلی اللہ علیہ وسلم نےلعنت فرمائی ہے۔(دیکھیے: سنن نسائی: کتاب الطلاق: ۳۴۴۵)","",{}],[398,"§طواف\nاس کا لغوی معنی \"گھومنا اور چکر لگانا\" ہے۔\nشرعی اصطلاح میں خانہ کعبہ کے ارد گرد سات چکر لگانے کو \"طواف\" کہتے ہیں۔\nطواف صرف بیت اللہ ہی کا کیا جاسکتا ہے, کسی اور کا طواف کرنا اسلام میں قطعاً جائز نہیں۔\nاللہ تعالی کا ارشاد ہے: ﴿وَإِذۡ بَوَّأۡنَا لِإِبۡرَٰهِيمَ مَكَانَ ٱلۡبَيۡتِ أَن لَّا تُشۡرِكۡ بِي شَيۡـࣰٔ ا وَطَهِّرۡ بَيۡتِيَ لِلطَّآئِفِينَ وَٱلۡقَآئِمِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ﴾ [الحج: ۲۶] \"یاد کرو جب ہم نے ابراہیم کے لیے اس گھر(کعبہ) کی نشاندہی فرمائی، اس حکم کےساتھ کہ میرے ساتھ کسی کو شریک نہ کرنا اور میرے گھر کو طواف کرنے والوں اورقیام رکوع اور سجود کرنے والوں کے لیے پاک صاف رکھنا\"۔\nاس آیت کریمہ میں یہ بات وضاحت کے ساتھ بیان کی گئ ہے کہ طواف صرف خانہ کعبہ ہی کا کیا جاتا ہے۔\nطواف کسی بھی وقت کیا جاسکتا ہے, جیسا کہ حدیث شریف میں آتا ہے: ((یا بَني عبدِ مَناف، لا تَمْنَعُوْا أحدًا يطوفُ بهذا البيتِ، ويُصلّي أيَّ ساعةٍ شاءَ مِنْ ليلٍ أو نهارٍ))\n\"اے قبیلہ عبد مناف! دن یا رات کے کسی بھی وقت اس گھر کے طواف کرنے والے نیز اس میں نماز پڑھنے والے کو طواف اور نماز سے نہیں روکنا \"۔\nیعنی چاہے وہ وقت مباح ہو یا مکروہ, کعبۃ اللہ اس سے مستثنی ہے, اس میں مکروہ وقت میں بھی نماز ادا کرسکتے ہیں, البتہ حاکم وقت کسی مصلحت کی بناء پر وقتی طور پر طواف کرنے پر پابندی لگا ئےجیسے صفائی ستھرائی , اصلاح وترمیم یا کسی خطرناک وباء کے پھیلتے کے خوف سے نفس کی حفاظت کے لئے تو اس کی اطاعت کرنا واجب ہے۔\n﴿يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَ وَأُوْلِي ٱلۡأَمۡرِ مِنكُمۡۖ﴾ [النِّسَاء: ۵۹]\nترجمہ: اے ایمان والو! اللہ کی اطاعت کرو اور اس کے رسول کی اور اپنے حاکم کی۔\nبلکہ اگر بقیہ مساجد میں بھی نماز باجماعت پر پابندی لگا دے تو اس کی اطاعت واجب ہے۔ ایسا ہی ایک واقعہ ۷۴۹ میں پیش آیا۔ جس کی وجہ سے اذانیں بند ہوگئیں اور مساجد میں باجماعت نماز پر پابندی لگادی گئی۔ اور یہ مرض ایسا تھا جو بلاد عرب اور عجم میں پھیل گیا۔ جس کا ذکر مقریزی نے \"السلوک لمعرفۃ دول الملوک (۴/۸۸) میں ذکر کیا ہے۔\n§طواف کی قسمیں:\nطواف کی چار قسمیں ہیں۔\n۱- طواف قدوم : جو حاجی خانہ کعبہ میں داخل ہوتے ہی کرتا ہے۔ جیسے عمرہ کا طواف\n۲- طواف افاضہ: حج کے دیگر ارکان ادا کرنے کے بعد ۱۰/ ذی الحجہ کو جو طواف کیا جاتا ہے اسے \"طواف افاضہ\" کہتے ہیں۔ حج کے جملہ ارکان میں \"طواف افاضہ\" فرض ہے, جس کے بغیر حج نہیں ہوسکتا۔\n۳- طواف وداع: حاجی حج کے تمام اعمال, ارکان وواجبات سے فارغ ہونے کے بعد اپنے ملک روانہ ہونے سے پہلے جو طواف کرتا ہے اسے \"طواف وداع\" کہتے ہیں۔\n۴- طواف نفل: وہ طواف جو بغیر سبب کے محض ثواب کی نیت سے کیا جاتا ہے۔\nاس طواف کی صحیح حدیثوں میں بڑی فضیلت آئی ہے۔\nنبی اکرم صلی اللہ علیہ وسلم کا ارشاد ہے: \" مَنْ طَافَ بِهَذَا الْبَيْتِ أُسْبُوعًا فَأَحْصَاهُ کَانَ کَعِتْقِ رَقَبَةٍ\" (سنن ترمذی: ۹۵۹)\nجس نے ثواب کی نیت سے خانہ کعبہ کا طواف کیا تو گویا اس نے ایک غلام کو آزاد کیا۔\nاسی طرح فرمایا: «مَنْ طَافَ بِالْبَيْتِ لَمْ يَرْفَعْ قَدَمًا وَلَمْ يَضَعْ إِلاَّ کَتَبَ اللَّهُ لَهُ حَسَنَةً وَيَحُطُّ عَنْهُ خَطِيئَةً، وَکَتَبَ لَهُ دَرَجَةً وَرُفِعَتْ لَهُ بِهَا دَرَجَةٌ». (صحیح ابن خزیمہ: ۲۷۵۳) \"اسی طرح جب کوئی آدمی کعبے کا طواف کرتا ہے تو ہر قدم پر اس کا ایک گناہ کم ہوتاہے اور ایک ثواب لکھا جاتا ہے اور اس کا درجہ اونچا ہوجاتا ہے\"۔","",{}],[399,"§طور\nطور ایک پہاڑ کا نام ہے۔جو ریگستانِ سینا کے جنوب میں واقع ہے۔اس کے مشرق میں خلیج عقبہ اور مغرب میں نہر سویزہے۔اب اس کو جبل موسیٰ کہتے ہیں۔طویٰ کا میدان اسی کے دامن میں ہے، جہاں موسیٰ علیہ السلام کے ساتھ اللہ نے باتیں کی اور انھیں تورات دی۔اسی پہاڑ کو سروں پہ اٹھاکر قسم لی گئی تھی کہ تم توریت کی تعلیمات کو مضبوطی کے ساتھ پکڑے رہو گے۔ ان کو چھوڑوگے نہیں۔لیکن وہ اپنی بگڑی ہوئی فطرت کے سبب توریت کو چھوڑ بیٹھے۔ایک اللہ کو چھوڑ کر بے شمار بتوں کی عبادت کرنے لگے۔قرآن مجیدمیں ہے:﴿وَإِذۡ أَخَذۡنَا مِيثَٰقَكُمۡ وَرَفَعۡنَا فَوۡقَكُمُ ٱلطُّورَ خُذُواْ مَآ ءَاتَيۡنَٰكُم بِقُوَّةࣲ وَٱذۡكُرُواْ مَا فِيهِ لَعَلَّكُمۡ تَتَّقُونَ﴾ [البقرة: ۶۳] \"جب ہم نے تم سے عہد لیااور طور کو تمھارے اوپر کھڑا کردیا۔کہا کہ جو تمھیں ہم دے رہے ہیں، اس کو مضبوطی سے پکڑ لو اور جو اس میں ہے اسے یاد رکھو تاکہ تم (عذاب سے) محفوظ رہ سکو\"۔\nاورفرمایا: ﴿وَنَٰدَيۡنَٰهُ مِن جَانِبِ ٱلطُّورِ ٱلۡأَيۡمَنِ وَقَرَّبۡنَٰهُ نَجِيࣰّ ا﴾ [مریم: ۵۲] \"ہم نے اسے طور کے داہنے کنارے سے آواز دی اور باتیں کرنے کےلیے نزدیک کرلیا\"۔","",{}],[400,"§طوی\nطویٰ کا ذکر قرآن کریم میں دومقامات پر آیا ہے اور دونوں مقامات پر موسیٰ علیہ السلام کو اللہ تعالیٰ حکم دیتا ہے کہ تم طویٰ کے مقدس میدان میں ہو، اس لیے اپنے جوتے اتار لو اور جو میں کہہ رہا ہوں اس کو غور سے سنو: ﴿إِنِّيٓ أَنَا۠ رَبُّكَ فَٱخۡلَعۡ نَعۡلَيۡكَ إِنَّكَ بِٱلۡوَادِ ٱلۡمُقَدَّسِ طُوࣰ ى وَأَنَا ٱخۡتَرۡتُكَ فَٱسۡتَمِعۡ لِمَا يُوحَىٰٓ﴾ [طه: ۱۲-۱۳] \"بے شک میں تیرا رب ہوں۔ تو اپنے جوتے اتاردے۔کیوں کہ تو مقدس میدان طویٰ میں ہےاور میں نے تجھے منتخب کر لیا ہے۔اس لیے جو تجھے وحی کی جارہی ہے اسے پوری توجہ سے سن\"۔\nدوسری جگہ فرمايا: ﴿هَلۡ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ إِذۡ نَادَىٰهُ رَبُّهُۥ بِٱلۡوَادِ ٱلۡمُقَدَّسِ طُوًى ٱذۡهَبۡ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ﴾ [النازعات: ۱۵-۱۷] \"کیا موسیٰ کے قصے کا تمھیں علم ہے؟ جب اس کے رب نے اسے مقدس میدان طویٰ میں پکارا۔تم فرعون کے پاس جاؤ جو بہت مغرور ہوگیا ہے\"۔\nیہ قصہ اس وقت کا ہے،جب موسیٰ علیہ السلام مدین سے اپنے بیوی اور بچوں کے ساتھ مصر واپس آرہے تھے۔ طویٰ کے میدان میں ان کو نبوت کی خوش خبری دی گئی اور اسی کے ساتھ یہ حکم بھی ہوا کہ فرعون کے پاس جاؤ۔وہ بہت مغرور اور ظالم بن گیا ہے۔پہلے اسے توحید کا پیغام دو اور پھر بنی اسرائیل کو اس کی گرفت سے نکالو۔\nیہ ميدانِ طویٰ کہاں واقع ہے؟ قرآن مجیدکے بیان سے معلوم ہوتا ہے کہ یہ کوہ طور کے دامن میں ہے:﴿فَلَمَّا قَضَىٰ مُوسَى ٱلۡأَجَلَ وَسَارَ بِأَهۡلِهِۦٓ ءَانَسَ مِن جَانِبِ ٱلطُّورِ نَارࣰ اۖ قَالَ لِأَهۡلِهِ ٱمۡكُثُوٓاْ إِنِّيٓ ءَانَسۡتُ نَارࣰ ا لَّعَلِّيٓ ءَاتِيكُم مِّنۡهَا بِخَبَرٍ أَوۡ جَذۡوَةࣲ مِّنَ ٱلنَّارِ لَعَلَّكُمۡ تَصۡطَلُونَ فَلَمَّآ أَتَىٰهَا نُودِيَ مِن شَٰطِيِٕ ٱلۡوَادِ ٱلۡأَيۡمَنِ فِي ٱلۡبُقۡعَةِ ٱلۡمُبَٰرَكَةِ مِنَ ٱلشَّجَرَةِ أَن يَٰمُوسَىٰٓ إِنِّيٓ أَنَا ٱللَّهُ رَبُّ ٱلۡعَٰلَمِينَ﴾ [القصص: ۲۹-۳۰] \"جب موسیٰ علیہ السلام نے (شعیب علیہ السلام کے یہاں قیام کی) مدت پوری کرلی اور اپنے اہل و عیال کو لے کر نکل پڑے تو کوہ طور کی طرف ا نھوں نے آگ دیکھی۔انھوں نے اپنے اہل سے کہا:ٹھہرو میں نے آگ دیکھی ہے،ممکن ہے میں وہاں سے کوئی خبر لاؤں یا آگ کاکوئی ٹکڑا۔ تاکہ تم گرمی حاصل کرلو۔ اور جب وہ وہاں پہنچےتو اس مقدس زمین کے میدان کے داہنے کنارے کے درخت سے آواز آئی: اے موسیٰ! میں ہی اللہ ہوں، سارے جہان کا رب\"۔(مزید معلومات کے لیے دیکھیے: موسی علیہ السلام)","",{}],[401,"§طٰہ\nدیکھیے: الم","",{}],[402,"§طہارت\nپاکی اورصفائی ستھرائی کوعربی میں طہارت کہتے ہیں۔ چونکہ اللہ تعالیٰ پاک لوگوں سے محبت کرتا ہے، اس لیے اسلام میں اس کی بہت اہمیت ہے۔\nایک صحیح حدیث میں ابومالک اشعری رضی اللہ عنہ سےروایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «الطُّهُورُ شَطْرُ الإِيمَانِ». (صحیح مسلم: ۱/۳۲۳) \"پاکی نصف ایمان ہے\"۔\nیہ پاکی جسم کی بھی ہوسکتی ہے اور دل کی بھی۔\n§جسمانی پاکی:\nقرآن اورصحیح احادیث میں صبح سے شام تک اور پھر پوری زندگی میں پاک و صاف رہنے کی شرائط اور طریقے بتائے گئے ہیں :\n(۱)صبح اٹھتے ہی پہلے ہاتھوں کو دھونا چاہیے۔ کیونکہ رات کو سوتے ہوے ہاتھ کہاں کہاں لگا ہوگا؟ سونے والے کو کچھ پتا نہیں۔ (صحیح البخاری:۱۶۲ وصحیح مسلم:۲۷۸)\n(۲) پیشاب کرنے کے بعد عضو خاص کو پانی سے دھونا چاہیے۔\n(۳) بیت الخلا میں قبلے کی طرف منہ نہیں کرنا چاہیے اور پاکی حاصل کرنے کے لیے داہنے ہاتھ کا استعمال بھی نہیں کرنا چاہیے۔ مٹی کے تین ڈھیلوں یا تین پتھروں سے پاکی حاصل کرنی چاہیے،جن میں نہ گوبر ہو نہ ہڈی۔ (صحیح مسلم:۲۶۲)اس کے بعد پانی کا استعمال بہتر ہے۔\n(۴) آدمی نے بیوی سے ہم بستری کی ہو تو اس پر غسل کرنا واجب ہے، چاہے منی خارج ہو یا نہ ہو۔(صحیح البخاری:۲۹۱ وصحیح مسلم:۳۴۸)\n(۵) احتلام خواہ مرد کو ہو یا عورت کو دونوں پر غسل واجب ہے۔(صحیح البخاری:۱۳ وصحیح مسلم:۳۱)\n(۶) اگر عورت نے اپنے سر کے بالوں کو باندھ رکھا ہے تو غسل کرتے ہوے ان کو کھولنا واجب نہیں ہے۔(صحیح مسلم: ۳۳)\n(۷)لیکن اگر حیض کے بعد پاک ہونے کے لیے غسل کرے تو بالوں کی لٹوں کوکھولنا واجب ہے۔ (صحیح البخاری: ۳۱۷ وصحیح مسلم:۱۲۱۱)\n(۸)غسل کرتے ہوے کسی پردہ یا آڑ والی جگہ میں ہوجانا چاہیے۔ (صحیح البخاری :۲۸ وصحیح مسلم:۳۳۶)\n(۹)بہتر ہے کہ غسل کرتے وقت ننگا نہ ہو۔ کیونکہ اللہ سے بھی تو شرم آنی چاہیے۔\n(۱۰)عورتوں کوحمام( عام غسل خانے جہاں لوگ نہانے اور علاج معالجے کے لیے جاتے تھے) میں نہیں جانا چاہیے۔(مسند احمد:۲۸۰۴۱)ابوملیح ہذلی سے روایت ہے کہ حمص (شام) کی کچھ عورتوں نے ام المومنین عائشہ ڤ سے ملاقات کی اجازت طلب کی تو انہوں نے کہا کہ شاید تم ان عورتوں میں سے ہو جو حمام میں جاتی ہیں، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا ہے : «أَيُّمَا امْرَأَةٍ وَضَعَتْ ثِيَابَهَا فِي غَيْرِ بَيْتِ زَوْجِهَا، فَقَدْ هَتَکَتْ سِتْرَ مَا بَيْنَهَا وَبَيْنَ اللَّهِ». \"جس عورت نے اپنے شوہر کے گھر کے علاوہ کسی اور جگہ اپنے کپڑے اتارے تو اس نے اس پردہ کو پھاڑ ڈالا جو اس کے اور اللہ کے درمیان ہے\"۔ (سنن ابی داود:۴۰۱۰،۲۶۹۳، سنن الترمذی: ۲۸۰۳، سنن ابن ماجہ: ۳۷۵۰، مسنداحمد: ۶/ ۱۷۳، ۱۹۸)\nاگر عورت بیمارہوتوعلاج معالجےکے لیےایسی جگہوں پر پردےکی شرط کے ساتھ جاسکتی ہے۔\n(۱۱)پیشاب کے چھینٹے کپڑے پر نہ لگ جائیں، اس لیے اس سے بچنا چاہیے (صحیح البخاری:۲۱۸ وصحیح مسلم:۲۹۲)\n(۱۲)مُنہ کی صفائی کے لیے مسواک کرنی چاہیے۔(صحیح البخاری:۸۸۷ وصحیح مسلم:۲۵۲)\n(۱۳)ہوسکے تو آدمی ہمیشہ وضوکی حالت میں رہے، کیونکہ اس حالت میں مومن ہی رہ سکتا ہے۔ (مسند احمد:۵/۲۸۲)\n(۱۴) ختنہ کرانا۔شرم گاہ اور بغل کے بال موڈنا۔مونچھ کٹانا اور ناخن تراشنا۔ یہ سب کام انسان کی فطرت میں شامل ہیں۔(صحیح البخاری:۵۸۸۹ وصحیح مسلم:۲۵۷)\n(۱۵) حمام(باتھ روم) میں داخل ہونےسے پہلے یہ دعا پڑھے: «اللَّهُمَّ إِنِّی أَعُوذُ بِکَ مِنَ الْخُبُثِ وَالْخَبَائِثِ». \" اے اللہ، میں شیطان عورتوں اور شیطان مردوں سے تیری پناہ مانگتاہوں\"۔ (سنن ابی داود :۶، سنن ابن ماجہ: ۲۹۶)\n(۱۶) حیض والی بیوی سے ہمبستری کرنا حرام ہے، جب تک کہ وہ پاک نہ ہوجائے۔( البقرہ:۲۲۲)\n(۱۷)بیوی کے ساتھ پیچھے کی شرم گاہ میں جماع کرنا حرام ہے، لیکن پیچھے سے آگے کی جگہ میں کی جاسکتی ہے۔\n(۱۸)لڑکوں کے ساتھ بد فعلی حرام ہے۔ اغلام بازی کی اسلام میں سزابہت سخت ہے۔ اسی وجہ سے اللہ تعالیٰ نے لوط علیہ السلام کی قوم کو نیست و نابود کردیاتھا۔ (النمل:۵۸،۵۷)\n(۱۹)پیشاب بیٹھ کرکرنا چاہیے۔تاکہ پیشاب کی چھینٹیں کپڑوں پر نہ آئیں،لیکن ضرورت پڑنے پر کھڑے ہوکر بھی پیشاب کیا جا سکتا ہے۔(صحیح البخاری:۲۲۴ وصحیح مسلم:۲۷۳)\n(۲۰)ٹھہرے ہوے پانی میں پیشاب نہیں کرنا چاہیے۔ (صحیح البخاری:۲۸۹ وصحیح مسلم:۲۷۲)\n(۲۱)دو جگہوں کی لعنتوں سے بچنا چاہیے: ایک یہ کہ لوگوں کے راستے میں قضائے حاجت کی جائے، دوسرے ان سایہ والی جگہوں میں جہاں لوگ آرام کرتے ہوں۔(صحیح مسلم:۲۸۹)\n(۲۲)کپڑے پر منی لگ جائے تو دھونا چاہیے اور خشک ہو جائے تو اسےکھرچ دینا بھی ٹھیک ہے۔ (صحیح مسلم:۲۹)\n(۲۳)اگرکسی نےغلطی سے مسجد میں پیشاب کردیاتو اسےپانی سے صاف کردینا چاہیے۔ (صحیح البخاری:۲۲۱ وصحیح مسلم:۲۸۴)\n(۲۴)مردوں کو مردوں کی شرمگاہ نہیں دیکھنی چاہیے۔اسی طرح عورتوں کی شرمگاہ عورتوں کو نہیں دیکھنی چاہیے۔ایک لحاف میں دو مرد نہ سوئیں۔ اسی طرح ایک لحاف میں دو عورتیں بھی نہ سوئیں۔\n(۲۵)اپنے کپڑوں کو ہمیشہ صاف ستھرا رکھنا چاہیے۔(المدثر:۴)\n(۲۶)قرآن مجیدکو ناپاکی کی حالت میں نہیں چھونا چاہیے۔( الواقعہ:۷۹)\nکچھ خاص مواقع پر غسل ضرور کرنا چاہیے جیسے:\n(۱)جمعہ کے روز غسل کرنا واجب ہے۔کم ازکم اس کا حکم سنت موکدہ کاہے۔ خوشبو کا استعمال مستحب ہے۔\n(۲)عیدالفطر اور عیدالاضحیٰ(بقرعید) کے دن غسل سنت ہے۔\n(۳)حج اور عمرے کا احرام باندھتے وقت غسل مسنون ہے۔\n(۴)مزدلفہ سےمنی واپسی پرجب جمرات کو کنکری مار لیں اور قربانی کر لیں تو بال منڈوائیں یا چھوٹا کروائیں اور غسل کریں۔\n(۵) اسی طرح ایک مسلمان اپنے آپ کو پاک وصاف رکھ کر پوری زندگی گزارتا ہے اور صبح سے شام تک پانچ وقت نماز پڑھتا ہے۔ جس کی مثال ایک صحیح حدیث میں اس طرح آئی ہے: «أَرَأَيْتُمْ لَوْ أَنَّ نَهَرًا بِبَابِ أَحَدِکُمْ يَغْتَسِلُ فِيهِ کُلَّ يَوْمٍ خَمْسًا مَا تَقُولُ ذَلِکَ يُبْقِي مِنْ دَرَنِهِ، قَالُوا: لا يُبْقِي مِنْ دَرَنِهِ شَيْئًا، قَالَ: فَذَلِکَ مِثْلُ الصَّلَوَاتِ الْخَمْسِ يَمْحُو اللَّهُ بِهِ الْخَطَايَا». (صحیح البخاری: ۵۲۸، صحیح مسلم: ۶۶۷/۲۸۳ بروایت ابوہریرہ رضی اللہ عنہ ) \"نبی اکرم صلی اللہ علیہ وسلم نے ایک مرتبہ صحابہ رضی اللہ عنہم سے پوچھا کہ اگر ایک شخص پانچ مرتبہ بہتی ہوئی ندی میں غسل کرے تو کیا اس کے جسم پر میل(گندگی) باقی رہے گا؟ صحابہ نے کہا، نہیں۔تو آپ صلی اللہ علیہ وسلم نے فرمایا: پانچ نمازوں کی مثال بھی اسی طرح ہے۔ ان کے ذریعےسے اللہ تعالیٰ گناہوں کو مٹا دیتا ہے\"۔\n§دل کی پاکیزگی:\nدل کی پاکی یہ ہے کہ اس میں توحید مضبوطی سے بیٹھ جائے اور شرک سے اس طرح نفرت ہونے لگے جیسے ناپاک چیزسے نفرت ہوتی ہے:﴿ٱلشِّرۡكَ لَظُلۡمٌ عَظِيمࣱ‏﴾ [لقمان: ۱۳] \"یقیناًشرک گناہ عظیم ہے\"۔\nجو اپنے دل میں اللہ کے سوا کسی اور کو بٹھا لیتا ہے تو وہ ناپاک ہوجاتا ہے۔اللہ تعالیٰ نے ابراہیم علیہ السلام کو ایسے ناپاک لوگوں سے اپنے گھر کو پاک و صاف رکھنے کا حکم دیا: ﴿وَإِذۡ بَوَّأۡنَا لِإِبۡرَٰهِيمَ مَكَانَ ٱلۡبَيۡتِ أَن لَّا تُشۡرِكۡ بِي شَيۡـࣰٔ ا وَطَهِّرۡ بَيۡتِيَ لِلطَّآئِفِينَ وَٱلۡقَآئِمِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ﴾ [الحج: ۲۶] \"یاد کرو جب ہم نے ابراہیم کے لیے اس گھر(کعبہ) کو ٹھکانا بنایا، اس حکم کے ساتھ کہ میرے ساتھ کسی کو شریک نہ کرنا اور میرے گھر کو طواف کرنے والوں اورقیام رکوع اور سجدہ کرنے والوں کے لیے پاک صاف رکھنا\"۔\nمطلب یہ ہے کہ ان لوگوں سے میرا گھرپاک وصاف رکھنا جو میرے سوا کسی اور پر ایمان لاتے ہیں اور میرے ساتھ اس کی بھی بندگی کرتے ہیں۔ ایسے لوگ ناپاک ہیں اور ان کی یہ ناپاکی ان کے دل کی ناپاکی ہے۔ یہی سبب تھا کہ جب مکہ فتح ہوگیا تو آپ صلی اللہ علیہ وسلم نے کعبے میں رکھے ہوے سارے بتوں کو باہرنکال دیا اور اللہ کی طرف سے یہ اعلان ہوگیا:﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّمَا ٱلۡمُشۡرِكُونَ نَجَسࣱ فَلَا يَقۡرَبُواْ ٱلۡمَسۡجِدَ ٱلۡحَرَامَ بَعۡدَ عَامِهِمۡ هَٰذَاۚ وَإِنۡ خِفۡتُمۡ عَيۡلَةࣰ فَسَوۡفَ يُغۡنِيكُمُ ٱللَّهُ مِن فَضۡلِهِۦٓ إِن شَآءَۚ إِنَّ ٱللَّهَ عَلِيمٌ حَكِيمࣱ‏﴾ [التوبة: ۲۸] \"اے ایمان والو! بے شک مشرک ناپاک ہیں تو اس سال کے بعد یہ مسجد حرام کے پاس نہ آئیں\"۔\nدل کی پاکی یہ بھی ہے کہ جو بھی ثواب کاکام کیا جائے وہ صرف اللہ کے لیے ہو۔(دیکھیے: صحیح بخاری: ۳۴۶۵ وصحیح مسلم: ۲۷۴۳)\nاگر کسی نے ثواب کا کام دکھاوے کے لیے کیا تو وہ اللہ کے نزدیک قبول نہیں ہوگا،بلکہ ایسا شخص جہنم میں جائے گا۔ (دیکھیے : صحیح مسلم: ۱۹۰۵)\nاسلام نےدل کی پاکی کو جسم کی پاکی سے زیادہ اہمیت دی ہے، کیوں کہ اعمال کا قبول ہونا یا نہ ہونا دل کی پاکی پر ہی منحصر ہے: ﴿يَوۡمَ لَا يَنفَعُ مَالࣱ وَلَا بَنُونَ إِلَّا مَنۡ أَتَى ٱللَّهَ بِقَلۡبࣲ سَلِيمࣲ‏﴾ [الشعراء: ۸۸-۸۹] \"جس دن (روزِقیامت)نہ مال کام آئے گانہ اولاد،سوائے اس کے کہ کوئی نیک دل لیے ہوے اللہ کے پاس آیا ہو\"۔\nوہ دل جو شرک، کفر،دنیوی لالچ،بدعت، ریاکاری اور غرور وغیرہ سے پاک ہواور صرف اللہ کے ذکر سے سکون حاصل کرتا ہو۔\nدلوں کے شرک کے دو دروازے تھے۔ ان کو ایک ہی آیت میں ہمیشہ کے لیے بند کردیا گیا: ﴿إِيَّاكَ نَعۡبُدُ وَإِيَّاكَ نَسۡتَعِينُ﴾ [الفاتحة: ۵] \"اے رب ہم تیری ہی عبادت کرتے ہیں اور تجھ ہی سے مدد مانگتے ہیں\"۔","",{}],[403,"§ظاہر(اسم باری تعالی)","",{}],[404,"§ظاہرمیں دوستی باطن میں دشمنی\nدیکھیے: نفاق","",{}],[405,"§ظہار\nظہار: \"ظہر\" سے بنا ہے جس کا لفظی معنی \"پیٹھ\" ہے۔\nزمانہ جاہلیت میں شوہر اور بیوی میں جھگڑا یا ناچاکی ہوجانے کی صورت میں شوہر اپنی بیوی سے کہتا تھا: \"تم میری ماں کی پیٹھ کی طرح ہو\"۔ یعنی تجھ سے مباشرت کرنا ایسا ہی ہے جیسے ماں سے مباشرت کرنا، اور یہ طلاق کی ایک صورت تھی۔\nعہد نبوی میں ایسا ہی ایک واقعہ پیش آیا۔ خولہ بنت ثعلبہ رضی اللہ عنہا کے شوہر اوس بن صامت بڑے شدید اور غصے والے شخص تھے، ناراضگی کی حالت میں اپنی بیوی سے ظہار کر بیٹھے۔ جب غصہ ختم ہوا اور انہیں اپنی غلطی کا احساس ہوا تو خولہ رضی اللہ عنہا بارگاہِ نبوت میں حاضر ہوئی اور کہنے لگی کہ اے اللہ کے رسول صلی اللہ علیہ وسلم! \"میرے شوہر نے میری جوانی کا فائدہ اٹھایا، میں نے اس کے لئے اپنے پیٹ کو کھول دیا تاکہ وہ ہمبستری کرسکے، مگر اب چونکہ میں بوڑھی ہوچکی ہوں اور اولاد پیدا کرنے کے قابل نہیں ہوں، اس لئے اس نے مجھ سے ظہار کرلیا، اے اللہ! میں تجھ سے ہی شکایت کر رہی ہوں\"۔\nعائشہ رضی اللہ عنہا کہتی ہیں کہ جب وہ شکایت کررہی تھی تو میں بھی وہاں موجود تھی، لیکن مجھے ان کی باتیں صاف طور پر سنائی نہیں دے رہی تھی، جبکہ اللہ تعالی آسمان سے ان کی باتوں کو سن رہا تھا۔ اللہ تعالی کو خولہ رضی اللہ عنہا کا اصرار کرنا بے حد پسند آیا، چنانچہ سورہ مجادلہ کی ابتدائی آیتیں نازل ہوئیں۔\n﴿قَدۡ سَمِعَ ٱللَّهُ قَوۡلَ ٱلَّتِي تُجَٰدِلُكَ فِي زَوۡجِهَا وَتَشۡتَكِيٓ إِلَى ٱللَّهِ وَٱللَّهُ يَسۡمَعُ تَحَاوُرَكُمَآۚ إِنَّ ٱللَّهَ سَمِيعُۢ بَصِيرٌ ٱلَّذِينَ يُظَٰهِرُونَ مِنكُم مِّن نِّسَآئِهِم مَّا هُنَّ أُمَّهَٰتِهِمۡۖ إِنۡ أُمَّهَٰتُهُمۡ إِلَّا ٱلَّٰٓـِٔي وَلَدۡنَهُمۡۚ وَإِنَّهُمۡ لَيَقُولُونَ مُنكَرࣰ ا مِّنَ ٱلۡقَوۡلِ وَزُورࣰ اۚ وَإِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورࣱ وَٱلَّذِينَ يُظَٰهِرُونَ مِن نِّسَآئِهِمۡ ثُمَّ يَعُودُونَ لِمَا قَالُواْ فَتَحۡرِيرُ رَقَبَةࣲ مِّن قَبۡلِ أَن يَتَمَآسَّاۚ ذَٰلِكُمۡ تُوعَظُونَ بِهِۦۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرࣱ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ شَهۡرَيۡنِ مُتَتَابِعَيۡنِ مِن قَبۡلِ أَن يَتَمَآسَّاۖ فَمَن لَّمۡ يَسۡتَطِعۡ فَإِطۡعَامُ سِتِّينَ مِسۡكِينࣰ اۚ ذَٰلِكَ لِتُؤۡمِنُواْ بِٱللَّهِ وَرَسُولِهِۦۚ وَتِلۡكَ حُدُودُ ٱللَّهِۗ وَلِلۡكَٰفِرِينَ عَذَابٌ أَلِيمٌ﴾ [المجادلة: ۱-۴]\nترجمہ: اللہ نے سن لی اس عورت کی بات جو اپنے شوہر کے معاملہ میں تم سے تکرار کر رہی تھی، اور اللہ تعالی سے فریاد کئے جارہی تھی، اللہ تعالی تم دونوں کی گفتگو سن رہا تھا، وہ سب کچھ سننے اور دیکھنے والا ہے۔\nتم میں سے جو لوگ اپنی بیویوں سے ظہار کرتے ہیں، ان کی بیویاں ان کی مائیں نہیں ہیں، ان کی مائیں تو وہی ہیں جنہوں نے ان کو جنا ہے۔یہ لوگ ایک سخت ناپسندیدہ اور جھوٹی بات کرتے ہیں، اور حقیقت یہ ہے کہ اللہ تعالی معاف کرنے والا اور درگزر فرمانے والا ہے۔\nجو لوگ اپنی بیویوں سے ظہار کرنے کے بعد پھر اپنی اس بات سے رجوع کرنا چاہتے ہیں جو انہوں نے کہی تھی، تو قبل اس کے کہ دونوں ایکدوسرے کو چھوئیں، انہیں ایک غلام آزاد کرنا ہوگا۔ اسی بات کی تمہیں نصیحت کی جاتی ہے۔ اور جو کچھ تم کرتے ہو اللہ تعالی اس سے با خبر ہے۔\nاور جو شخص غلام نہ پائے، وہ مسلسل دو مہینہ روزہ رکھے قبل اس کے کہ دونوں ایکدوسرے کو چھوئیں، اور جو اس پر بھی قادر نہ ہوتو وہ (۶۰) مسکینوں کو کھانا کھلائے۔ یہ حکم اس لئے دیا جارہا ہے تاکہ تم اللہ اور اس کے رسول پر ایمان رکھو۔یہ اللہ تعالی کی مقرر کردہ حدیں ہیں، اور کافروں کے لئے دردناک عذاب ہے۔\nاسی طرح سورہ احزاب میں اللہ تعالی کا ارشاد ہے:﴿مَّا جَعَلَ ٱللَّهُ لِرَجُلࣲ مِّن قَلۡبَيۡنِ فِي جَوۡفِهِۦۚ وَمَا جَعَلَ أَزۡوَٰجَكُمُ ٱلَّٰٓـِٔي تُظَٰهِرُونَ مِنۡهُنَّ أُمَّهَٰتِكُمۡۚ وَمَا جَعَلَ أَدۡعِيَآءَكُمۡ أَبۡنَآءَكُمۡۚ ذَٰلِكُمۡ قَوۡلُكُم بِأَفۡوَٰهِكُمۡۖ وَٱللَّهُ يَقُولُ ٱلۡحَقَّ وَهُوَ يَهۡدِي ٱلسَّبِيلَ﴾ [الأحزاب: ۴]\nترجمہ: اور نہ اس نے تم لوگوں کی ان بیویوں کو جن سے تم ظہار کرتے ہو تمہاری ماں بنایا۔\nیعنی تمہاری ماں تو وہ ہیں جنہوں نے تمہیں جنم دیا ہے۔\nابن عباس رضی اللہ عنہما سے روایت ہے کہ ایک شخص نے اپنی بیوی سے ظہار کیا، اور پھر اس سے جماع بھی کیا قبل اس کے کہ وہ کفارہ ظہار ادا کرے۔ پھر وہ نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور اپنا واقعہ کہہ سنایا۔\nنبی کریم صلی اللہ علیہ وسلم نے پوچھا کہ اس نے ایسا کیوں کیا؟ اس نے کہا: اے اللہ کے رسول! میں نے اس کی سفید ٹانگوں کو چاند کی روشنی میں دیکھا، اور صبر نہ کرسکا۔ اس پر آپ صلی اللہ علیہ وسلم مسکرائےاور پھر اسے حکم دیا کہ کفارہ ادا کرنے سے قبل دوبارہ جماع نہیں کرنا۔\nاس حدیث کو امام ترمذی، نسائی اور ابن ماجہ وغیرہ نے روایت کیا ہے اور اس کی سند حسن ہے۔\nاس حدیث سے جمہور علماء نے استدلال کیا ہےکہ اگر کوئی ظہار کا کفارہ ادا کرنے سے پہلے اپنی بیوی سے جماع کر بیٹھے، تب بھی اس پر ایک ہی کفارہ لازم آئے گا۔\nاور اس کا کفارہ یہ ہے کہ ایک غلام آزاد کرے، اگر غلام میسر نہ ہو تو مسلسل دو ماہ کا روزہ رکھے، اگر اس کی استطاعت نہ ہو تو (۶۰) مسکینوں کو کھانا کھلائے، اور اگر اس کی بھی استطاعت نہ ہو تو لوگوں کو اس کی مدد کرنی چاہئے، کیونکہ نبی اکرم صلی اللہ علیہ وسلم نے کفارہ کے ادا کرنے میں اس شخص کی مدد فرمائی تھی جو رمضان کے دنوں میں اپنی بیوی سے جماع کر بیٹھا۔\nخلاصہ یہ کہ دور جاہلیت میں طلاق کے تین طریقے تھے: ۱) ایلاء ۲) ظہار ۳) طلاق۔\nان میں سے اول اور دوم کو اسلام نے ملغی قرار دیا جبکہ تیسرے طریقے یعنی طلاق کو باقی رکھا، اگر طلاق بھی اسلامی اصولوں کے تحت دیا جائے تواسلامی معاشرے میں اس کی نسبت بہت کم ہوجائے گی۔ تفصیل کے لئے دیکھئے: \"طلاق\"۔","",{}],[406,"§ظلم\nقرآن اور صحیح احادیث میں ظلم کی شدید مذمت کی گئی ہے۔دراصل اسلام کی بنیادعدل وانصاف کی حمایت اورہرطرح کےظلم کے خلاف اعلان جنگ ہے۔کائنات کاسب سے بڑا ظلم کفراورشرک ہے۔اللہ تعالیٰ نے شرک اورکفرکےمرتکب ظالموں اوراسلام کے دشمنوں کوبارباربرے انجام سے ڈرایاہے۔ارشادباری تعالیٰ ہے :﴿وَلَوۡ أَنَّ لِلَّذِينَ ظَلَمُواْ مَا فِي ٱلۡأَرۡضِ جَمِيعࣰ ا وَمِثۡلَهُۥ مَعَهُۥ لَٱفۡتَدَوۡاْ بِهِۦ مِن سُوٓءِ ٱلۡعَذَابِ يَوۡمَ ٱلۡقِيَٰمَةِۚ وَبَدَا لَهُم مِّنَ ٱللَّهِ مَا لَمۡ يَكُونُواْ يَحۡتَسِبُونَ﴾ [الزمر: ۴۷] \"اگر ظلم کرنے والوں کے پاس وہ سب کچھ ہوجو روئے زمین پر ہےاور اس کے ساتھ اتنا ہی اور ہوتو بھی بدترین سزا کے بدلے میں قیامت کے دن یہ سب کچھ دے دیں اور ان کے سامنے االلہ کی طرف سے وہ ظاہر ہوگا جس کا گمان بھی انھیں نہ تھا\"۔\nصحیح حدیث میں مذکورہے: «الظُّلْمُ ظُلُمَاتٌ يَوْمَ الْقِيَامَةِ». (صحیح البخاری: ۲۴۴۷، صحیح مسلم: ۲۵۸۰/۵۸ بروایت عبداللہ بن عمر رضی اللہ عنہما ) \"دنیا میں ظلم کرنے والا آخرت میں گہری تاریکی میں ہوگا\"۔االلہ کی گرفت سے نجات کےلیے روشنی کی کوئی کرن اسے نہیں دی جائے گی۔\nظلم کی تعریف یہ کی جاتی کہ کسی چیز کواس کی اصل جگہ سےہٹاکردوسرے مقام پر رکھ دیا جائے۔ ظلم کی یہاں پرکچھ تفصیل دی جارہی ہے:\nا-االلہ تعالیٰ اس پوری کائنات کا خالق اوررب ہے۔ وہی رازق اور وہی ہادی ہے۔وہی متصرف اور قدیرہے۔اس اعتبار سے وہی حقیقی معبودبھی ہے۔اب اگر کوئی اس حقیقی معبود کے مقام پرکسی اور کو معبود سمجھتا یاکسی غیر کی عبادت کرتا ہے تو یہ االلہ کے نزدیک سب سے بڑاظلم ہے۔ اس لیے قرآن کریم میں آیا ہے: ﴿ٱلشِّرۡكَ لَظُلۡمٌ عَظِيمࣱ‏﴾ [لقمان: ۱۳] \"یقیناً شرک بہت بڑا ظلم ہے\"۔\n۲- االلہ تعالیٰ کبھی کسی پر ظلم نہیں کرتا۔ لیکن لوگ خود پر ظلم کرتے ہیں۔کیونکہ االلہ تعالیٰ جس کو بھی کوئی سزا دیتا ہے، وہ اس کےبْرے اعمال کی وجہ سے دیتا ہے۔ (ہود :ا۰ا،النحل:۸اا، الزخرف :۷۶)\nبلکہ حدیث قدسی میں اللہ تعالیٰ فرماتاہے: «إِنِّي حَرَّمْتُ الظُّلْمَ عَلَی نَفْسِي وَجَعَلْتُهُ بَيْنَکُمْ مُحَرَّمًا فَلاَ تَظَالـَمَوا يَا عِبَادِي» \"میں نے اپنے اوپر ظلم حرام قرار دیاہے، اس لیے میرے بندوتم آپس میں ظلم وزیادتی نہ کرو\"۔(صحیح مسلم: ۲۵۷۷)\n۳-قیامت کے دن کسی پر ظلم نہیں ہوگا۔ارشادباری تعالیٰ ہے: ﴿وَنَضَعُ ٱلۡمَوَٰزِينَ ٱلۡقِسۡطَ لِيَوۡمِ ٱلۡقِيَٰمَةِ فَلَا تُظۡلَمُ نَفۡسࣱ شَيۡـࣰٔ اۖ وَإِن كَانَ مِثۡقَالَ حَبَّةࣲ مِّنۡ خَرۡدَلٍ أَتَيۡنَا بِهَاۗ وَكَفَىٰ بِنَا حَٰسِبِينَ﴾ [الأنبیاء: ۴۷] \"قیامت کے دن ہم درمیان میں لارکھیں گے ٹھیک ٹھیک تولنے والی ترازوکو۔پهر کسی پر کچھ بھی ظلم نہ کیا جائے گا۔ اگر ایک رائی کے دانے کے برابر بھی عمل ہوگاہم اسے لاحاضرکریں گےاور ہم کافی ہیں حساب کرنے والے\"۔\n۲-قانون شکنی کوبھی ظلم کہاجاتاہے۔ ایک شخص قانون شکنی کا ارتکاب کرکے خود پر ظلم کرتا ہے۔ اس لیے قرآن مجید میں بتایا گیا ہے کہ االلہتعالیٰ کے بنائے ہوے قوانین کوتوڑنےوالاخود اپنے اوپر ظلم کر رہاہے۔کیونکہ وہ االلہ کا توکچھ بگاڑ نہیں سکتا۔(البقرة: ا۲۳، الطلاق: ا)\n۵-قرآن مجید میں جن بڑے مظالم کا ذکر ہے وہ درج ذیل ہیں:\n(الف)شرک وکفر\n(ب)مساجد میں عبادت سے روکنا۔(البقرة:۴اا)\n(ج)االلہ کی طرف سے نازل کردہ شہادت کو چھپانا۔ (البقرة:۱۴۰)\n(د)االلہ پر افترا کرنا۔(الانعام:۲۱)\n(ہ)االلہ تعالیٰ کی آیتوں کی تکذیب کرنا۔ (الانعام:۵۷ا)\nظلم کرنے والے اگر توبہ کرلیں توااللہ تعالیٰ ان کو معاف کرسکتاہے: ﴿فَمَن تَابَ مِنۢ بَعۡدِ ظُلۡمِهِۦ وَأَصۡلَحَ فَإِنَّ ٱللَّهَ يَتُوبُ عَلَيۡهِۚ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِيمٌ﴾ [المائدة: ۳۹] \"جوشخص اپنے گنا ہ کے بعد توبہ کرلے اور اصلاح کرلے توااللہ تعالیٰ رحمت کے ساتھ اس کی طرف لوٹتاہے\"۔\nیہاں توبہ کرنے کامطلب ہے کہ اگر کسی نے کسی کا مال لےکر اس پر ظلم کیا،تو اس کا مال واپس کرے۔کسی پر جرمانےاور سزا کے ذریعے سے ظلم کیا تواس سے جرمانہ معاف کروائےاور پھر االلہ کے سامنےاپنے ظلم پر سچے دل سے توبہ کرے کہ وہ دوبارہ کسی پر ظلم نہیں کرےگا۔پھر االلہ تعالیٰ اس پر رحم کرے گا۔ اور اس کی توبہ قبول کرے گا۔ اسی کو توبۃ النصوح کہتے ہیں۔","",{}],[407,"§عاد\nعادایک بہت بڑی قوم تھی،جس کامسکن سلطنت عمان اور حضرموت کے درمیان تھا۔اس کاکچھ حصہ سعودی عرب کے جنوبی علاقہ’ربع خالی‘میں تھا۔جس کواحقاف کہتے تھے۔ اس قوم کی جانب ایک نبی بھیجے گئے، جن کانام ہود تھا۔لیکن اس قوم نے ان کا انکار کیا، جس کی وجہ سے اس قوم کوایک ہولناک طوفان نے جوسات رات اور آٹھ روز آندھی کی شکل میں چلتا رہااسے ہلاک وبرباد کردیا۔\nعاد اس قوم کے سردار کانام ہے،لیکن ہمیں صحیح طور سے اس قوم کی تاریخ نہیں معلوم ہے۔قرآن مجیدسے معلوم ہوتا ہے کہ یہ ایک بڑی قوم تھی۔جس کوعرب اچھی طرح جانتے تھے۔ ان کاجوانجام ہوا، اس کوبھی وہ سنتے آئے تھے۔اس لیے جب قرآن مجید نے ان کاباربار ذکر کیا توکسی کوزیادہ جاننے کی ضرورت نہیں پڑی۔عوامی شہرت کے مطابق ہود علیہ السلام کی قبر بھی حضرموت (یمن)میں مکلاّ شہر سے ۲۵ا کلومیٹر کے فاصلہ پر موجود ہے۔جہاں ہرسال میلہ لگتا ہے۔ وہاں کے لوگوں میں یہ بات مشہور ہے کہ یہی وہ جگہ ہے جہاں قوم عاد رہتی تھی۔لیکن درحقیقت یہ ایک بے نبیادچیزہے۔نبی اکرم صلی اللہ علیہ وسلم کی قبرمبارک کے علاوہ کسی اور نبی اوررسول کی قبر کے بارے میں عوام میں مشہور حکایات سب بے اصل ہیں۔مزید تفاصیل کے لیے دیکھیے لفظ ’ہود‘اور لفظ ’احقاف‘۔","",{}],[408,"§عاقر\nدیکھیے: عقیم","",{}],[409,"§عالم\nدیکھیے: اسماےحسنی","",{}],[410,"§عبادت\nعبادت کا مطلب ہے بندگی کرنا،پرستش کرنا۔ پوجا کرنا۔عاجزی وانکساری سے کسی کے سامنے خود کو جھکا دینا وغیرہ۔\nاسلام کی خصوصیات میں سےایک امتیازی خصوصیت یہ ہے کہ وہ صرف ایک االلہ کی عبادت اور پرستش کاحکم دیتا ہے۔یہی تعلیم قبل اسلام تمام انبیا کی بھی تھی۔مگر ان کے متبعین نے اسے بد ل ڈالا۔ بلکہ سارےانبیاورسل کا اپنی قوموں سےسب سے بڑا اختلاف اللہ تعالیٰ کے ساتھ شرک تھا۔لوگ االلہتعالیٰ کو چھوڑکر دوسرے بہت سے دیوی دیوتاؤں اور جھوٹے معبودوں کی عبادت کرتے تھےیا االلہ کی عبادت میں دوسروں کوشریک کرتے تھے،تاکہ وہ االلہ کے یہاں ان کی سفارش کرسکیں۔\nقرآن کریم اوردیگر آسمانی کتابوں میں اس کی مذمت اور تردید کی گئی ہے۔جن معبودوں کی وہ لوگ عبادت کرتے تھے،وہ آخرت میں صاف کہہ دیں گے کہ ہمارا ان سے کوئی تعلق نہیں ہے،بلکہ اپنے پوجنے والوں سےوہ لاتعلقی کا اعلان کریں گے۔\nقرآن کریم نے عیسیٰ علیہ السلام کی ایسے لوگوں سے لا تعلقی اوران پرتردید کا تذکرہ بڑے خوبصورت انداز میں کیا ہے: ﴿وَإِذۡ قَالَ ٱللَّهُ يَٰعِيسَى ٱبۡنَ مَرۡيَمَ ءَأَنتَ قُلۡتَ لِلنَّاسِ ٱتَّخِذُونِي وَأُمِّيَ إِلَٰهَيۡنِ مِن دُونِ ٱللَّهِۖ قَالَ سُبۡحَٰنَكَ مَا يَكُونُ لِيٓ أَنۡ أَقُولَ مَا لَيۡسَ لِي بِحَقٍّۚ إِن كُنتُ قُلۡتُهُۥ فَقَدۡ عَلِمۡتَهُۥۚ تَعۡلَمُ مَا فِي نَفۡسِي وَلَآ أَعۡلَمُ مَا فِي نَفۡسِكَۚ إِنَّكَ أَنتَ عَلَّٰمُ ٱلۡغُيُوبِ مَا قُلۡتُ لَهُمۡ إِلَّا مَآ أَمَرۡتَنِي بِهِۦٓ أَنِ ٱعۡبُدُواْ ٱللَّهَ رَبِّي وَرَبَّكُمۡۚ وَكُنتُ عَلَيۡهِمۡ شَهِيدࣰ ا مَّا دُمۡتُ فِيهِمۡۖ فَلَمَّا تَوَفَّيۡتَنِي كُنتَ أَنتَ ٱلرَّقِيبَ عَلَيۡهِمۡۚ وَأَنتَ عَلَىٰ كُلِّ شَيۡءࣲ شَهِيدٌ إِن تُعَذِّبۡهُمۡ فَإِنَّهُمۡ عِبَادُكَۖ وَإِن تَغۡفِرۡ لَهُمۡ فَإِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ﴾ [المائدة: ۱۱۶-۱۱۸] \"اور وہ وقت بھی قابل ذکر ہے جب کہ االلہ تعالیٰ فرمائے گاکہ اےعیسیٰ ابن مریم!کیاتم نے ان لوگوں سے کہہ دیا تھا کہ مجھ کو اور میری ماں کوبھی علاوہ االلہ کے معبود قرار دے لو! عیسیٰ عرض کریں گے کہ میں تو تجھ کومنزہ سمجھتا ہوں مجھ کو کسی طرح زیبانہ تھا کہ میں ایسی بات کہتا،جس کے کہنے کا مجھ کوکوئی حق نہیں۔ اگر میں نے کہا ہوگا توتجھ کو اس کاعلم ہوگا۔ تو تومیرے دل کے اندر کی بات بھی جانتا ہے اور میں تیرے جی میں جو کچھ ہے اس کونہیں جانتا۔تمام غیبوں کاجاننے والا تو ہی ہے۔میں نے تو ان سے اور کچھ نہیں کہا مگر صرف وہی جو تو نے مجھ سے کہنے کو فرمایا تھا کہ تم االلہ کی بندگی اختیار کرو جو میرا بھی رب ہے اور تمھارا بھی رب ہے۔میں ان پر گواہ رہا جب تک ان میں رہا۔پھر جب تو نے مجھ کو اٹھا لیا تو تو ہی ان پر مطلع رہااور تو ہر چیز کی پوری خبر رکھتا ہے۔ اگرتو ان کو سزا دے تو یہ تیرے بندے ہیں اور اگر تو ان کو معاف فرمادے توتوعزیزوحکیم (زبردست اوربڑی حکمت والا) ہے\"۔\nاسی طرح قرآن کریم نے مُوَحِّد ابراہیم اور ان کے مشرک باپ کا مکالمہ بھی بہترین اسلوب میں پیش کیاہے،جس میں ابراہیم علیہ السلام نے اپنے باپ کوبتوں کی عبادت چھوڑکر صرف ایک االلہ کی عبادت کرنے کوکہاہے: ﴿وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ إِبۡرَٰهِيمَۚ إِنَّهُۥ كَانَ صِدِّيقࣰ ا نَّبِيًّا إِذۡ قَالَ لِأَبِيهِ يَٰٓأَبَتِ لِمَ تَعۡبُدُ مَا لَا يَسۡمَعُ وَلَا يُبۡصِرُ وَلَا يُغۡنِي عَنكَ شَيۡـࣰٔ ا يَٰٓأَبَتِ إِنِّي قَدۡ جَآءَنِي مِنَ ٱلۡعِلۡمِ مَا لَمۡ يَأۡتِكَ فَٱتَّبِعۡنِيٓ أَهۡدِكَ صِرَٰطࣰ ا سَوِيࣰّ ا يَٰٓأَبَتِ لَا تَعۡبُدِ ٱلشَّيۡطَٰنَۖ إِنَّ ٱلشَّيۡطَٰنَ كَانَ لِلرَّحۡمَٰنِ عَصِيࣰّ ا يَٰٓأَبَتِ إِنِّيٓ أَخَافُ أَن يَمَسَّكَ عَذَابࣱ مِّنَ ٱلرَّحۡمَٰنِ فَتَكُونَ لِلشَّيۡطَٰنِ وَلِيࣰّ ا قَالَ أَرَاغِبٌ أَنتَ عَنۡ ءَالِهَتِي يَٰٓإِبۡرَٰهِيمُۖ لَئِن لَّمۡ تَنتَهِ لَأَرۡجُمَنَّكَۖ وَٱهۡجُرۡنِي مَلِيࣰّ ا قَالَ سَلَٰمٌ عَلَيۡكَۖ سَأَسۡتَغۡفِرُ لَكَ رَبِّيٓۖ إِنَّهُۥ كَانَ بِي حَفِيࣰّ ا وَأَعۡتَزِلُكُمۡ وَمَا تَدۡعُونَ مِن دُونِ ٱللَّهِ وَأَدۡعُواْ رَبِّي عَسَىٰٓ أَلَّآ أَكُونَ بِدُعَآءِ رَبِّي شَقِيࣰّ ا فَلَمَّا ٱعۡتَزَلَهُمۡ وَمَا يَعۡبُدُونَ مِن دُونِ ٱللَّهِ وَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَۖ وَكُلࣰّ ا جَعَلۡنَا نَبِيࣰّ ا وَوَهَبۡنَا لَهُم مِّن رَّحۡمَتِنَا وَجَعَلۡنَا لَهُمۡ لِسَانَ صِدۡقٍ عَلِيࣰّ ا﴾ [مریم: ۴۱-۵۰] \"اس کتاب میں ابراہیم (علیہ السلام) کا قصہ بیان کربےشک وہ بڑی سچائی والےرسول تھے۔جب انھوں نے اپنے باپ سے کہا کہ ابا جان! آپ ان کی پوجاپاٹ کیوں کررہے ہیں، جونہ سنیں نہ دیکھیں؟ نہ آپ کو کچھ بھی فائدہ پہنچاسکیں۔ میرے مہربان باپ!آپ دیکھیے میرے پاس وہ علم آیا ہے جو آپ کے پاس آیا ہی نہیں،آپ میری ہی مانیں،میں بالکل سیدھی راہ کی طرف آپ کی رہبری کروں گا۔ میرے ابا جان آپ شیطان کی پرستش سے باز آجائیں، شیطان تو رحم وکرم والے االلہ تعالیٰ کا بڑا ہی نافرمان ہے۔ابا جان!مجھے خوف لگاہوا ہے کہ کہیں آپ پر کوئی عذاب الٰہی نہ آپڑے کہ آپ شیطان کے ساتھی بن جائیں۔اس نے جواب دیا کہ اے ابراہیم!کیا تو ہمارے معبودوں سے روگردانی کررہاہے۔سن اگر توباز نہ آیاتومیں تجھے پتھروں سے مار ڈالوں گاجا ایک مدت دراز تک مجھ سے الگ رہ۔کہا: اچھا تم پر سلام ہومیں تو اپنے رب سے تمھاری بخشش کی دعا کرتا رہوں گا۔ وہ مجھ پر حددرجہ مہربان ہے۔میں تو تمھیں بھی اور جن جن کوتم االلہ تعالیٰ کے سوا پکارتے ہو انھیں بھی سب کو چھوڑرہاہوں۔صرف اپنے رب کوپکارتارہوں گا۔ مجھے یقین ہے کہ میں اپنے پروردگار سے دعا مانگ کر محروم نہ رہوں گا۔ جب ابراہیم علیہ السلام ان سب کو اور االلہ کے سوا ان کے سب معبودوں کو چھوڑچکے تو ہم نے انھیں اسحاق و یعقوب علیہما السلام عطا فرمائے اور دونوں کو نبی بنادیااور ان سب کو ہم نے اپنی بہت سی رحمتیں عطا فرمائیں اور ہم نے ان کے ذکر جمیل کوبلند درجے کا کر دیا\"۔\nیہ توعبادت کا وہ مفہوم ہے، جس سے اکثرلوگ واقف ہیں اور دین اسلام کی اہم خصوصیات میں سے ایک ہے،جس میں کوئی بھی مذہب اس کی برابری نہیں کرسکتا۔ لیکن اسلام نے عبادت کو بہت ہی عملی معنیٰ میں استعمال کیا ہے۔ اس کے مطابق عبادت کا مطلب ہے کہ االلہ کے مقرر کردہ اصول وضوابط کے مطابق پوری زندگی گزاری جائے، جس چیز کو االلہتعالیٰ نے حلال کیا ہے، اسےحلال مانا جائے اور جس چیز کوحرام ٹھہرایا ہے،اسے حرام تسلیم کیا جائے اور اس کی الوہیت میں کسی کو اس کا شریک نہ سمجھا جائے۔\nاس کی توثیق وتائید ایک حسن حدیث سے بھی ہوتی ہے:\nعدی بن حاتم نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے، ان کے گلے میں صلیب لٹک رہی تھی۔آپ نے فرمایا: عدی اپنے گلے سے اس بت کونکال دو\"۔عدی کہتے ہیں کہ میں نے آپ کوسورہ التوبہ کی آیت ا۳پڑھتے ہوے سنا جس میں کہا گیاہے: ﴿ٱتَّخَذُوٓاْ أَحۡبَارَهُمۡ وَرُهۡبَٰنَهُمۡ أَرۡبَابࣰ ا مِّن دُونِ﴾ [التوبة: ۳۱] \"ان لوگوں نے االلہ کوچھوڑکر اپنے عالموں اور درویشوں کو رب بنالیا ہے\"۔آپ نےفرمایا: «أَمَا إِنَّهُمْ لَمْ يَکُونُوا يَعْبُدُونَهُمْ، وَلَکِنَّهُمْ کَانُوا إِذَا أَحَلُّوا لَهُمْ شَيْئًا اسْتَحَلُّوهُ، وَإِذَا حَرَّمُوا عليهِمْ شَيْئًا حَرَّمُوهُ». \"وہ ان کی عبادت تونہیں کرتے تھے،لیکن اگروہ کوئی چیز حلال ٹھہراتے تو اسے وہ لوگ حلال کرلیتے اور اگر کوئی چیز حرام ٹھہراتے تو اسے حرام ٹھہرالیتے تھے۔گویا یہی ان کی عبادت ہے\"۔ (سنن الترمذی: ۳۰۹۵)۔\nحذیفہ بن یمان اور ابن عباس رضی اللہ عنہم وغیرہ کاقول ہےکہ علماء اور درویشوں کا حلال وحرام میں اتباع کرنا حقیقت میں ان کی عبادت کرنا ہے۔\nاس سے معلوم ہوا کہ اسلامی شریعت کودل سے قبول کرنا اور ان کا اتباع کرنا عبادت ہے اوراسلام کے سوا کسی غیر کی راہ پر چلنا حقیقت میں شرک ہے جو ظلم عظیم اور گناہ کبیرہ ہے۔","",{}],[411,"§عبد\n’عبد‘ کااستعمال قرآن واحادیث میں آزاداور غلام دونوں کے لیے آیا ہے۔اسی سے عبداللہ کامطلب اللہ کا بندہ اورعباد اللہ کامطلب اللہ کے بندےہیں،اس معنی میں سارے انسان اللہ کے بندے ہیں اوراسی معنی میں ارشادگرامی ہے:﴿أَفَلَمۡ يَرَوۡاْ إِلَىٰ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُم مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِۚ إِن نَّشَأۡ نَخۡسِفۡ بِهِمُ ٱلۡأَرۡضَ أَوۡ نُسۡقِطۡ عَلَيۡهِمۡ كِسَفࣰ ا مِّنَ ٱلسَّمَآءِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةࣰ لِّكُلِّ عَبۡدࣲ مُّنِيبࣲ‏﴾ [سبأ: ۹] \"یقیناًاس میں ہر اس عبد کے لیے نشانی ہے جو(اللہ کی طرف) رجوع کرنے والا ہے\"۔\nنوح علیہ السلام کے بارے میں کہا گیا ہے:﴿ذُرِّيَّةَ مَنۡ حَمَلۡنَا مَعَ نُوحٍۚ إِنَّهُۥ كَانَ عَبۡدࣰ ا شَكُورࣰ ا﴾ [الإسراء: ۳] \"یقیناً ہی وہ ایک پرہیزگار عبد(بندہ) تھا\"۔\nاورفرمایا: ﴿أَرَءَيۡتَ ٱلَّذِي يَنۡهَىٰ عَبۡدًا إِذَا صَلَّىٰٓ﴾ [العلق: ۹-۱۰] \"کیا تم نے دیکھا نہیں اس آدمی کو جو ایک بندے کو روکتا ہے، جب وہ نماز پڑھتا ہے\"۔\nیہ اشارہ دشمنان ا سلام کےسردارابو لہب کی طرف ہے جونبی اکرم صلی اللہ علیہ وسلم کو نماز پڑھنے سے روکا کرتا تھا۔\nعبد کے دوسرےمعنی داس یا ہندستانی زبانوں میں غلام کے ہیں اورمونث کے لیے باندی کالفظ استعمال کیاجاتاہے۔اس معنی میں قرآن مجیدمیں ارشاد ہے:﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُتِبَ عَلَيۡكُمُ ٱلۡقِصَاصُ فِي ٱلۡقَتۡلَىۖ ٱلۡحُرُّ بِٱلۡحُرِّ وَٱلۡعَبۡدُ بِٱلۡعَبۡدِ وَٱلۡأُنثَىٰ بِٱلۡأُنثَىٰۚ فَمَنۡ عُفِيَ لَهُۥ مِنۡ أَخِيهِ شَيۡءࣱ فَٱتِّبَاعُۢ بِٱلۡمَعۡرُوفِ وَأَدَآءٌ إِلَيۡهِ بِإِحۡسَٰنࣲۗ ذَٰلِكَ تَخۡفِيفࣱ مِّن رَّبِّكُمۡ وَرَحۡمَةࣱۗ فَمَنِ ٱعۡتَدَىٰ بَعۡدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمࣱ‏﴾ [البقرة: ۱۷۸] \"اے ایمان والوں، مارے گئے لوگوں کے بارے میں قصاص ضروری ٹھہرایا گیا ہے۔آزاد کا بدلہ آزاد،عبد (غلام ) کا بدلہ عبد (غلام )اورغلام عورت(باندی)کا بدلہ (باندی) عورت\"۔\nاورفرمایا: ﴿وَلَا تَنكِحُواْ ٱلۡمُشۡرِكَٰتِ حَتَّىٰ يُؤۡمِنَّۚ وَلَأَمَةࣱ مُّؤۡمِنَةٌ خَيۡرࣱ مِّن مُّشۡرِكَةࣲ وَلَوۡ أَعۡجَبَتۡكُمۡۗ وَلَا تُنكِحُواْ ٱلۡمُشۡرِكِينَ حَتَّىٰ يُؤۡمِنُواْۚ وَلَعَبۡدࣱ مُّؤۡمِنٌ خَيۡرࣱ مِّن مُّشۡرِكࣲ وَلَوۡ أَعۡجَبَكُمۡۗ أُوْلَٰٓئِكَ يَدۡعُونَ إِلَى ٱلنَّارِۖ وَٱللَّهُ يَدۡعُوٓاْ إِلَى ٱلۡجَنَّةِ وَٱلۡمَغۡفِرَةِ بِإِذۡنِهِۦۖ وَيُبَيِّنُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمۡ يَتَذَكَّرُونَ﴾ [البقرة: ۲۲۱] \"اور شرک کرنے والی عورتوں سے تاوقتیکہ وہ ایمان نہ لائیں تم نکاح نہ کرو ایمان والی لونڈی بھی شرک کرنے والی آزاد عورت سےبہتر ہے،گو تمھیں مشرکہ ہی اچھی لگتی ہو اور نہ شرک کرنے والے مردوں کے نکاح میں اپنی عورتوں کو دو جب تک وہ ایمان نہ لائیں، مومن غلام آزاد مشرک سے بہتر ہے، گو مشرک تمھیں اچھا لگے\"۔\nاب یہ سوال اٹھتا ہے کہ یہ غلام کیسے بنائے جاتے تھے؟:\nقدیم تاریخ سے پتا چلتا ہے کہ غلام بنانے کا رواج سب سے پہلے قبل مسیح سے شروع ہوا ہے۔ اس کے کچھ اسباب درج ذیل ہیں:\n۱- غربت کے سبب قرض نہ ادا کرنے کی حالت میں آدمی کا اپنے آپ کو کچھ وقت کے لیے فروخت کردینا۔\n۲- غریب ہونے کی وجہ سے اپنی بیٹی یا بیٹا کو ہمیشہ کے لیے فروخت کر دینا۔\n۳- چوری کرتے ہوے پکڑے جانے کی حالت میں غلام بنا لینا۔\n۴- جنگ میں پکڑے جانے والے قیدیوں کو غلام بنا لینا اور فاتح فوج میں تقسیم کردینا۔\n۵- خرید و فروخت کرنے والے غریب ملک کے لوگوں کو پکڑ کر دولت مند ملک کے لوگوں کے ہاتھوں فروخت کر دینا،جیسے افریقہ میں بسنے والے کو یورپ اور امریکہ میں فروخت کیا گیا۔ آج بھی سینیگال میں وہ جگہ موجود ہے، جہاں یورپ کے جہاز کھڑے ہوتے تھے اور لوگوں کو بندوق کی نوک پر دوڑاتے ہوے لایا جاتا تھا اور جب جہاز بھر جا تا تو ان کو یورپ کے بازاروں میں بیچ دیا جاتا تھااور وہ ہمیشہ کے لیے غلام بنا لیے جاتے تھے۔\nاس میں پہلے تین طریقوں کا بیان تو بائبل میں بھی آیا ہے، لیکن ان وجوہ سے صرف غیر یہودیوں کو غلام بنایا جاتا تھا، یہودیوں کو نہیں۔(دیکھیے: کتاب استثناء:۴۳ـ۳۹:۲۵، خروج:۳ـ۱:۲۲،۷:۲۱)\nلیکن اسلام نے ان تمام ضابطوں کومنسوخ کر دیا۔ کسی آزاد شخص کو کسی بھی وجہ سے فروخت کرنے کو گناہ عظیم قرار دیا اور مختلف طریقوں سے غلام کو آزاد کرنے کی تعلیم دی۔ ان میں سے کچھ یہ ہیں جن کا ذکر قرآن اور احادیث میں آیا ہے۔\n۱- اگر کسی نے غلطی سے کسی مسلمان کو قتل کردیا تو اسے چاہیے کہ خون بہا کے ساتھ ایک غلام بھی آزاد کرے۔ (سورہ النساء: ۹۲)\n۲- ظہار کا کفارہ یہ ہے کہ ایک غلام آزاد کیا جائے۔ (سورہ المجادلہ: ۳)\n۳- قسم کا کفارہ یہ ہے کہ ایک غلام آزاد کرے۔ (سورہ المائدہ: ۸۹)\n۴- ثواب کے لیے غلام آزاد کرنا۔ قرآن نے جس کو عقبہ (گھاٹی) کا نام دیا ہے۔ کیوں کہ ثواب کے کام خواہشوں کے خلاف کرنے پڑتے ہیں اورشیطان طرح طرح سے شبہ میں ڈالتا رہتا ہے۔(سورہ البلد:۱۲،۱۱)\n۵- اگر سورج گرہن یا چاند گرہن لگ جائے تو غلام آزاد کرنا چاہیے،جیسا کہ نبی اکرم صلی اللہ علیہ وسلم کیا کرتے تھے۔ (صحیح البخاری: ۲۵۱۹)\n۶- جو شخص کسی مسلمان غلام کو آزاد کرےگا اللہ اس کے جسم کے ہرعضو کو جہنم کی آگ سے آزاد کر دےگا۔ (صحیح البخاری: ۲۵۱۷ وصحیح مسلم : ۱۵۰۹)\n۷- جس کے پاس کوئی لونڈی(غلام لڑکی)ہو اور اس نے اس کی اچھی طرح پرورش کی،پھر اس سے شادی کرلی،اس کے لیے اللہ کے نزدیک دوگنا ثواب ہے۔ (صحیح البخاری: ۲۵۴۴)\n۸- صحیح احادیث میں آتا ہے: اگر کسی شخص نے رمضان میں اپنی بیوی سے دن میں ہم بستری کی تو اسے چاہیے کہ ایک غلام آزاد کرے۔ (دیکھیے: کفارہ)\nیعنی اسلام نے غلام آزاد کرنے کے بے شمار دروازے کھول دیےاورغلام بنانے کے سارے دروازے بند کر دیے ہیں۔لیکن صرف ایک دروازہ باقی رکھا اور وہ ہے جنگ میں پکڑے گئے فوجی۔ کیوں کہ ان کو غلام بناکر ان سے خدمت لینے کے سوا اور کوئی راستا نہیں تھا۔ پھر اسلام نے ان کو بھی آزاد کرنے کے بے شمار طریقے بتائے ہیں، جن میں سے کچھ یہ ہیں:\n۱- مسلم فوجی قیدی کے بدلے غیر مسلم فوجی قیدی کو آزاد کرنا۔\n۲- فدیہ( جرمانہ) لے کر آزاد کرنا۔\n۳- اگر وہ کسی طرح کی تعلیم دے سکتے ہوں تو اس کے بدلے آزاد کرنا۔\n۴- اگر مالک چاہے تو اپنی طرف سے معاف کر دے۔\n۵-اگر کوئی خود اپنی خوشی سے اسلام قبول کرلے تو اسے آزاد کرنا۔\nاس کے بعد بھی اگر کوئی غلام بنا لیا جائے تو اس کے ساتھ نیک سلوک کرنے کی تاکید کی گئی ہے جو اس طرح ہے:\n۱- غلاموں اور لونڈیوں کی آپس میں شادی کرادی جائے۔ (سورہ النور:۳۲)\n۲- زمانہ قدیم کی طرح لونڈیوں کو بدکاری پر مجبور نہ کیا جائے۔ (سورہ النور: ۳۳)\n۳- اگروہ اپنی آزادی کے لیے کوئی مکاتبت (کاغذی کارروائی)کرنا چاہیں تو ان سےایسا کرلیا جائے۔(سورہ النور: ۳۳)\n۴- لونڈی اور اس کے بچوں کو جدا نہ کیا جائے۔ اگر کسی نے ایسا کیا تو قیامت کے دن اللہ اس کے عزیزوں میں جدائی ڈال دےگا۔ ایک حدیث میں آتا ہے کہ علی رضی اللہ عنہ نے دو غلام بھائیوں میں سے ایک کو فروخت کر دیا، جب نبی اکرم صلی اللہ علیہ وسلم کو معلوم ہوا تو آپ نے واپس کرنے کا حکم دیاکیوں کہ اس طرح دو بھائیوں میں جدائی ہوگئی تھی۔\n۵- ایک اور صحیح حدیث میں آتا ہے: ابوہریرہ رضی اللہ عنہ سے مروی حدیث میں نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «إِذَا أَتَی أَحَدَکُمْ خَادِمُهُ بِطَعَامِهِ فَإِنْ لَمْ يُجْلِسْهُ مَعَهُ فَليُنَاوِلْهُ لُقْمَةً أَوْ لُقْمَتَيْنِ أَوْ أُکْلَةً أَوْ أُکْلَتَيْنِ فَإِنَّهُ وَلِيَ عِلاجَهُ». (صحیح البخاری: ۲۵۵۷،وصحیح مسلم: ۱۶۶۳/۴۲). \"اگر کوئی غلام کھانا پکائے تو کھاتے وقت اس کو بھی اس کھانے میں شامل کر لیا جائے، اگر کھانا بہت کم ہے تو دو چار لقمے ہی اسے دیئے جائیں\"۔\nاسی طرح کے اور بھی بہت سارے حقوق ہیں جو اسلام میں غلاموں کو دیے گئے ہیں جن کی کوئی مثال تاریخ میں نہیں ملتی۔","",{}],[412,"§عبداللہ بن ابی بن سلول\nاس کا نام قرآن کریم میں واضح طور پر تو نہیں آیا ہے۔لیکن سورہ النور آیت نمبر اا میں جس شخص کا ذکر ہوا ہے،وہ یہی عبدا اللہبن ابی ہے: ﴿إِنَّ ٱلَّذِينَ جَآءُو بِٱلۡإِفۡكِ عُصۡبَةࣱ مِّنكُمۡۚ لَا تَحۡسَبُوهُ شَرࣰّ ا لَّكُمۖ بَلۡ هُوَ خَيۡرࣱ لَّكُمۡۚ لِكُلِّ ٱمۡرِيࣲٕ مِّنۡهُم مَّا ٱكۡتَسَبَ مِنَ ٱلۡإِثۡمِۚ وَٱلَّذِي تَوَلَّىٰ كِبۡرَهُۥ مِنۡهُمۡ لَهُۥ عَذَابٌ عَظِيمࣱ‏﴾ [النور: ۱۱] \"جو لوگ یہ بہت بڑا بہتان باندھ لائے ہیں،یہ بھی تم میں سے ہی ایک گروہ ہے۔تم اسے اپنے لیے برا نہ سمجھو۔بلکہ یہ تو تمھارے حق میں بہتر ہے۔ہاں ان میں سے ہر ایک شخص پر اتنا گناہ ہے جتنا اس نے کمایاہے اور ان میں سے جس نے اس کے بہت بڑے حصے کوسرانجام دیاہے اس کے لیے عذاب بھی بہت ہی بڑا ہے\"۔\nاس آیت میں جس شخص کے بارے میں ام المومنین عائشہڤپربہتا ن کا بڑا حصہ اپنے سرلینے کاذکرکیا گیا ہے، وہ یہی عبدااللہ بن ابی ہے،جو منافقوں کا سردار تھا۔ وہ اسلام اورنبی اکرم صلی اللہ علیہ وسلم کو نقصان پہنچانےمیں ہمیشہ پیش پیش رہتا تھا۔اس کو غزوۂ بنو مصطلق کے وقت ایک موقع مل گیا اور اس سے فائدہ اٹھاتے ہوے اس نے مسلمانوں میں فتنہ پھیلانے کے لیے عائشہڤجو آپ صلی اللہ علیہ وسلم کی زوجہ مطہرہ تھیں پر بہتان لگانے کی کوشش کی۔جس سے کچھ کمزور ایمان کے مسلمان بھی متاثر ہوگئے۔اس بہتان کا قصہ یوں ہے:\nام المومنین عائشہڤکہتی ہیں:\"آپ صلی اللہ علیہ وسلم کا معمول تھا، آپ جب سفر میں جاتے تو اپنی ازواج میں قرعہ ڈالتے،جس کانام نکلتا اس کو سفر میں لے جاتے۔ایک بار ایساہوایک لڑائی (غزوۂ مریسیع)میں آپ نے ہم پر قرعہ ڈالا۔ میرا نام نکلا۔میں آپ کے ساتھ گئی۔اس وقت پردے کا حکم اترچکا تھا۔ میں ہودے میں بیٹھا کر (اونٹ پر)چڑھائی جاتی اور اسی میں رہ کر اتاری جاتی،خیر ہم اسی طرح سفر کرتے رہے۔جب آپ اس جہاد سے لوٹے اور ہم مدینہ کے نزدیک پہنچے تو ایک رات آپ نے کوچ پکارا۔جب کوچ پکاراگیا تو میں اٹھی اور (حاجت کے لیے اکیلی)چلی،لشکر کے پرے نکل گئی،جب حاجت سے فارغ ہوئی تو اپنی جگہ پر آئی میں نے اپنی گردن جو چھوا تو معلوم ہوا میر ا ہار جو اظفار کے نگینوں کا تھا۔ وہ ٹوٹ کر گرگیا ہے،میں پھر لوٹی اور ہار ڈھونڈنے لگی،اس کوڈھونڈنے میں مجھ کو دیر ہوگئی ادھر وہ لوگ آن پہنچے جو میرا ہودہ اٹھایا کرتے تھے۔ وہ سمجھے میں ہودہ میں بیٹھی ہوں۔انھوں نے ہودہ اٹھاکر میرے اونٹ پر رکھ دیا جس پر میں سوار ہوا کرتی تھی، اس زمانےمیں عورتیں ہلکی پھلکی تھیں، آج کی سی موٹی اور پر گوشت نہ تھیں۔ ذرا سا تو کھانا کھانی تھیں اس لیے ہودہ اٹھانے والوں نے جب ہودہ اٹھایا،انھوں نے اس کے ہلکے پن پر خیال نہیں کیا اور یہ بھی تھا کہ میں اس وقت کمسن لڑکی تھی (میرا بوجھ ہی کیا تھا) غرض انھوں نے اونٹ اٹھایا اورچلتے بنے، جب سارا لشکر روانہ ہوگیا۔اس وقت میرا ہار ملا۔میں جوان کے ٹھکانوں میں آئی تو دیکھتی کیا ہوں کہ آدمی کانام نہیں، نہ کوئی بات کرنے والا نہ کوئی جواب دینے والا۔ آخر (مجبوراً) میں اس مقام پر چلی گئی، جہاں میں ٹھہری تھی۔میں نے یہ خیال کیا کہ جب قافلے والے مجھ کو(ہودہ میں) نہ پائیں گے،تو یہیں ڈھونڈنے آئیں گے۔خیر میں اسی جگہ بیٹھی تھی،اتنے میں میری آنکھ لگ گئی،یہیں سوگئی ایک شخص تھا صفوان بن معطل سلمیٰ ذکوانی،وہ لشکر کے پیچھے رہا کرتا (گراپڑا اٹھا لیتا) وہ جو میرےٹھکانے میں آیا، اس نے دیکھا کوئی شخص سورہا ہے، اس نے دیکھتے ہی مجھ کو پہچان لیا۔ کیونکہ پردے کا حکم اترنے سے پہلے اس نے مجھ کودیکھا تھا۔ اس نے مجھ کوپہچان کرجو إِنَّا لِلهِ وَإِنَّا إِلَيْهِ رَاجِعُونَپڑھا تومیری آنکھ کھل گئی،میں نے اوڑھنی سے منہ ڈھانپ لیاالله کی قسم نہ ہم دونوں نے کوئی بات کی نہ میں نے اس کی کوئی بات سنی۔ ایک انا اللہوانا الیہ راجعون کہناتوسنا، خیروہ اونٹ پر سے اتر ااس نے اونٹ بٹھایا اور اونٹ کے ہاتھ پر پاؤں رکھا میں کھڑی ہوئی۔اونٹ پرچڑھ گئی اور وہ بے چارہ پیدل چلتا رہا یہاں تک کہ ہم دونوں سخت گرمی کے وقت ٹھیک دوپہرکو لشکر میں پہنچے،اس وقت لشکر کے لوگ (آرام کے لیے اترپڑے تھے۔ عائشہ کہتی ہیں:پھر جو لوگ تباہ ہونے والے تھے،وہ اس مقدمہ میں (بہتان لگاکر) تباہ ہوے۔بہتان والوں کا سرغنہ (بانی مبانی) عبدااللہ بن ابی بن سلول منافق مشہور تھا۔عروہ نے کہا: مجھ کو یہ خبر پہنچی ہے کہ اس بہتان کااس کے پاس چرچاہوتا لوگ بیان کرتے تووہ اس کوتسلیم کرتا۔ کان لگاکرسنتا کھودکر خواہ مخواہ اس کو پوچھتا۔ اور (اسی سند سے)عروہ سے منقول ہے کہ ان بہتان جوڑنے والوں میں ان لوگوں کانام لیاگیا،حسان بن ثابت،مسطح بن اثاثہ،حمنہ بنت جحش باقی لوگوں کے نام معلوم نہیں ہوے، مگر ان کی جماعت تھی جیسے االلہ تعالیٰ نے(سورہ النورمیں)فرمایا، ان سب میں (بڑا) عبدااللہ بن ابی بن سلول تھا۔خیر میں سفر سے مدینہ آئی،بیمار پڑگئی ایک مہینے تک بیمار رہی ادھر لوگ بہتان والوں کی باتوں میں گھس پیٹھ کرتے رہے۔ مجھ کو کچھ خبر نہیں ہوئی۔ ایک ذرا وہم میرے دل میں اس وجہ سے آتا کہ جیسی مہربانی آپ صلی اللہ علیہ وسلم مجھ پر پہلےرکھتے تھے ویسی میں نے اس بیماری میں نہ پائی۔آپ اندر آکرسلام کرتےاور صرف یہ پوچھ کرچلے جاتے، اب کیسی طبیعت ہے؟ اس سے مجھ کوشک ہوا(کہ آپ کچھ ناراض ہیں)مگر اس بہتان کی مجھ کو خبر نہ تھی۔ خیر جب میں بیماری سے ذرا اچھی ہوئی تومسطح کی ماں کے ساتھ مناصع کی طرف گئی،وہاں ہم لوگ راتوں کو قضائےحاجت کے لیے جایاکرتے تھے،ایک رات کو جاتے پھر دوسری رات کو،اس زمانے میں ہمارے گھروں کے پاس بیت الخلا نہیں بنے تھے اور ہم اگلے زمانے کے عربوں کی طرح جنگل میں بیت الخلا کو جایا کرتے۔ گھروں میں حمام(باتھ روم) بنانے سے ہم کوتکلیف ہوتی اور مسطح کی ماں (سلمیٰ) جو ابو رہم بن مطلب بن عبدمناف کی بیٹی تھی۔ اس کی ماں صخر بن عامر کی بیٹی ابوبکر(میرے والد)کی خالہ تھی۔ مسطح بن اثاثہ بن عباد بن مطلب اس کابیٹا تھا ساتھ ساتھ گئے۔ جب میں اور وہ دونوں بیت الخلا سے فراغت پاکر گھر کو لوٹے آرہے تھے، اس وقت اس کاپاؤں چادر میں الجھا وہ گرپڑی،کہنے لگی: برا ہومسطح کا، میں نے کہا: ہائے بری بات، مسطح بدر کی جنگ میں شریک تھا تو اس کو برا کہتی ہے؟ اس نے کہا:اری بندی تونے مسطح کی بات نہیں سنی؟میں نے کہا:کیابات ہے؟ اس نے بیان کی جب تو(مارے رنج کے) میری بیماری دوگنی ہوگئی۔جب میں گھر پہنچی توآپ میرے پاس آئے۔آپ نے (دورہی سے) سلام کیا،پوچھا: اب کیسی طبیعت ہے؟میں نے عرض کیا: مجھے آپ اپنے ماں باپ کے پاس جانے کی اجازت دیجیے۔ میری نیت یہ تھی کہ میں ان کے پاس جاکر اس خبر کی تحقیق کروں (شاید مسطح کی ماں نے غلط کہاہو)۔ آپ نے اجازت دے دی۔(میں گئی)، میں نے اپنی ماں سے کہا:اماں یہ لوگ کیاباتیں بنارہے ہیں؟انھوں نے کہا:بیٹا تواتنا رنج نہ کر،االلہکی قسم،یہ تو اکثر ہوتا آیاہے۔جب کسی خوب صورت عورت کی سوکنیں ہوں اور خاوند اس کوچاہتا ہو تووہ ایسے ہی بہت حیلہ کرتی ہیں۔میں نے کہا: سبحان االلہ، کیا لوگ ایسی (جھوٹی) بات منہ سےنکالنے لگے (اس کاچرچاکرنے لگے)۔میری ساری رات روتے روتے گزری، صبح تک نہ آنسو تھمے، نہ نیند آئی۔ صبح کوبھی میں رورہی تھی۔آپ نے جب وحی اترنے میں دیر ہوئی تو علی اور اسامہ بن زید کوبلوایا، ان سےپوچھا، مشورہ لیا۔کہا:میں اس عورت (عائشہ) کوچھوڑدوں۔اسامہ نے توآپ کو جیسے وہ جانتے تھے کہ وہ عورت ایسی باتوں سے پاک ہے اور جیسے وہ ہمارے لوگوں سے دلی محبت رکھتے تھے،یہی مشورہ دیا،انھوں نے کہا:اللہ کےرسول!یہ آپ کی بی بی ہے اور ہم تواس کونیک (پاک دامن) ہی سمجھتے ہیں۔علی نے کہا:اللہ کےرسول! االلہ نے آپ پر عورتوں کی تنگی نہیں رکھی۔ کیایہی ایک عورت ہے اور بہت سی عورتیں ہیں۔آپ ذرا بریرہ اس کی لونڈی سےتوپوچھیے، وہ سچ سچ اس کا حال بتادے گی۔ عائشہ فرماتی ہیں: آپ نے بریرہ کوبلایا اور پوچھا:بریرہ (سچ کہو) کیاتونے عائشہ سے کبھی کوئی بات دیکھی ہے جس سے اس کی پاک دامنی میں شک پیدا ہو؟بریرہ نے کہا: قسم اس االلہ کی جس نے آپ کو سچانبی بناکر بھیجا،میں نے تو کبھی کوئی بات اس میں عیب کی نہیں دیکھی۔اتنی بات ہے (االلہ رکھے)ابھی کم عمر لڑکی ہے(ایسی بھولی بھالی ہے)۔گھر میں آٹاگْندھارکھاہوتا ہے وہ سوجاتی ہے بکر ی آن کر آٹاکھالیتی ہے۔ عائشہ کہتی ہیں: آپ صلی اللہ علیہ وسلم یہ سن کر اسی دن کھڑےہوے اور منبر پر آن کر عبدااللہ بن ابی کی شکایت کرنے لگے۔آپ نے فرمایا: مسلمانو! اس شخص سے کون میرا بدلہ لیتا ہے جس نے میری بی بی کی بدنامی تک بات پہنچائی۔ االلہکی قسم میں تو اپنی بی بی کونیک (پاک دامن) ہی سمجھتا ہوں اور جس (بیچارے)سے تہمت لگاتے ہیں اس کوبھی بھلا آدمی جانتا ہوں، وہ کبھی میری بی بی کے پاس نہیں گیا جب تک میں اس کے ساتھ نہیں ہوا۔یہ سنتے ہی سعدبن معاذ (اوس قبیلے) میں سے کھڑے ہوے کہنے لگے:یارسول االلہ میں آپ کابدلہ لیتا ہوں۔ اگر یہ تہمت لگانے والا میرے قبیلے اوس میں سے ہے تو ابھی اس کی گردن مارتاہوں اور اگر ہمارے بھائیوں خزرج میں کاہے تو آپ حکم دیجیے، جوآپ حکم دیں گے، وہ ہم بجا لائیں گے۔ عائشہ نے کہا: یہ سْن کر خزرج کاایک آدمی کھڑا ہوا۔ (تہمت کرنے والے) کی ماں اس کی چچازاد بہن ہوتی تھی، اس کے قبیلے کی تھی۔ اس کانام سعد بن عبادہ تھا۔ وہ خزرج کاسردار تھا۔ پہلے تو وہ اچھا نیک آدمی تھا، مگر اس کو (سعد بن معاذ کے کلام پر) اپنی قوم کی حمیت آگئی، وہ سعد بن معاذ سے کہنے لگا: اللہ کی قسم تم جھوٹےہو، تم اس کونہیں قتل کرسکتے۔تمھاری کیا مجال کہ تم اسےقتل کرو۔اگر (وہ تہمت لگانے والا)تمھارےخاندان کا ہوتا تو کبھی ا س کا قتل گوارانہ کرتے؟یہ سن کر اسید بن حضیر کھڑے ہوے،جوسعدبن معاذکے چچازاد بھائی تھےاورسعدبن عبادہ سے کہا: تم جھوٹے ہو،قسم االلہ کی، ہم اسےضرور قتل کردیں گے، تم تو منافق ہو۔ اسی لیےتم منافقوں کی حمایت کرتےہو۔عائشہ کہتی ہیں: (اس گفتگو پر) دونوں قبیلوں اوس اور خزرج کے لوگ کھڑے ہوے اورلڑنے پرمستعد ہوگئے۔آپ منبر پر کھڑے تھے۔ آپ ان کو چپ کراتےاورسمجھاتےرہے، یہاں تک کہ وہ خاموش ہوگئے اور آپ بھی خاموش ہوگئے۔عائشہ کہتی ہیں: میں برابر سارا دن روتی رہی۔ نہ تومیرے آنسو تھمتے تھے اور نہ مجھ کو نیند آتی تھی۔میرے ماں باپ بھی میرے پاس رہے۔دور ات اور ایک دن سے میں برابر رورہی تھی، نہ تو آنسو تھمتا تھا نہ مجھ کو نیند آتی تھی یہاں تک کہ میں سمجھی میرا کلیجہ (روتے روتے)پھٹ جائے گا۔ اس حال میں میرے ماں باپ بھی میرے پاس تھے۔ میں رورہی تھی کہ انصار کی ایک عورت نے (اس کانام معلوم نہیں ہوا)اندر آنے کی اجازت مانگی۔میں نے اس کو اجازت دی۔ وہ بیٹھ کر میرے ساتھ رونے لگی۔ خیر ہم اس حال میں تھے، اتنے میں آپ تشریف لائے۔ آپ نے سلام کیا۔پھر بیٹھ گئے۔ جس دن سے مجھ پر تہمت لگائی گئی تھی آپ میرے پاس نہیں بیٹھے تھے۔ تہمت کے بعد ایک مہینہ تک ٹھہرے رہے۔میرے باب میں کوئی وحی آ پ پر نہیں آئی۔ عائشہ کہتی ہیں: آپ نے بیٹھ کر کلمۂ شہادت پڑھا۔پھر فرمانے لگے: اما بعد! عائشہ مجھ کوتیری طرف سے ایسی ایسی خبر پہنچی ہے۔ اگر تو بے گناہ ہے تو االلہ عنقریب تیری پاک دامنی بیان کردے گا اور اگر (بالفرض) تو کسی گناہ میں آلودہ ہوگئی ہےتو االلہ سے بخشش مانگ، توبہ کر، کیونکہ بندہ اگر اپنے گناہ کا اقرار کرے،پھر توبہ کرےتوااللہ تعالیٰ اسےمعاف کردیتا ہے۔جب رسول اللہ صلی اللہ علیہ وسلم نے اپنی بات ختم کی تو میرے آنسو ایسےتھمے کہ میں نے اپنی آنکھوں میں ایک قطرہ بھی نہیں پایا۔میں نےاپنے والد سے کہا:رسول اللہ صلی اللہ علیہ وسلم کی بات کا آپ میری طرف سے جواب دیں۔انھوں نے کہا: االلہ کی قسم میری سمجھ میں نہیں آتاکہ میں آپ کی بات کا کیا جواب دوں۔پھر میں نے اپنی والدہ سےکہاکہ آپ ہی رسول اللہ صلی اللہ علیہ وسلم کی بات کا کچھ جواب دیں۔انھوں نے بھی یہی کہا: االلہ کی قسم میری سمجھ میں نہیں آتاکہ میں آپ کو کیاجواب دوں۔ (جب میں نے دیکھاکہ میرے ماں باپ بھی کچھ کہنے سےعاجز ہیں)تو میں نے خود ہی کہنا شروع کیا۔اس وقت میں ایک کم سن لڑکی تھی۔قرآن بھی میں نے زیادہ نہیں پڑھا تھا۔میں نے کہا: االلہ کی قسم مجھے معلوم ہے کہ آپ نے تویہ بات سن لی اوروہ آپ لوگوں کےدلوں میں جم گئی۔ آپ لوگوں نے اس کو سچ سمجھا۔اب اگر میں آپ لوگوں سےیہ کہوں کہ میں بے گناہ ہوں،جب بھی آپ لوگ مجھ کو سچانہیں سمجھیں گےاوراگر میں آپ کے سامنےایک ایسے گناہ کااقرار کرلوں اور االلہ تعالیٰ جانتا ہےکہ میں اس سے بَری ہوں تو آپ لوگ مجھ کوسچاسمجھیں گے۔االلہ کی قسم اب میری اور آپ لوگوں کی مثال وہی ہے جویوسف کے والد کی تھی۔انھوں نے کہاتھا: اب اچھی طرح صبرکرنا یہی بہتر ہے اور تم جو کہہ رہے ہو،اس پر االلہ میری مددکرنے والا ہے۔یہ کہہ کر میں نے اپنا منہ پھیرلیا اور اپنے بستر پر لیٹ رہی۔ مجھے یقین تھاکہ االلہ خوب جانتا ہے کہ میں بے گناہ ہوں اور وہ ضرور میری پاک دامنی بیان کرے گا۔مگر مجھ کو یہ گمان نہ تھا کہ میرے بارے میں قرآن اترے گا جو(قیامت تک) پڑھا جائے گا کیونکہ میں اپنی حیثیت اتنی نہ سمجھتی تھی کہ االلہ تعالیٰ (اتنا بڑا شہنشاہ) میرے باب میں کچھ کلام کرے۔مجھ کو یہ امید تھی کہ شاید رسول اللہ صلی اللہ علیہ وسلم کومیرے بارے میں کوئی خواب آئے گا،جس کے ذریعےااللہ تعالیٰ میری پاکی کھول دے گا۔پھر االلہ کی قسم آپ اپنی جگہ سے جہاں بیٹھے تھے، سرکے بھی نہیں، نہ کوئی گھر کا آدمی باہر گیا۔اتنے میں آپ پر وحی کی حالت طاری ہوئی،جیسے سختی وحی کے وقت آپ پر ہوا کرتی تھی وہ ہونے لگی۔یہ سختی اس کلام کے بوجھ سے جو آپ پر اترتا تھاایسی ہوتی تھی کہ سردی کے موسم میں آپ کے جسم سےموتی کی طرح پسینہ ٹپکنے لگتا۔خیر جب وحی کی حالت گزرچکی تو آپ (خوشی سے)ہنسنے لگے۔پہلی بات جو آپ نے منہ سے نکالی وہ یہ تھی: عائشہ االلہ تعالیٰ نےتیری پاک دامنی بیان فرمادی۔اس وقت میری والدہ کہنے لگیں: اُٹھ کررسول اللہ صلی اللہ علیہ وسلم کاشکریہ ادا کر۔میں نےکہا: االلہ کی قسم، میں توکبھی اُٹھ کر آپ کاشکریہ ادانہیں کرنے کی۔میں توبس اپنے مالک رب کا شکراداکروں گی۔االلہ تعالیٰ نے دس آیتیں اتاریں: \"جن لوگوں نے تم میں یہ بہتان اٹھایا \" اخیر تک اور االلہ تعالیٰ نے میری بے گناہی صاف فرمادی اور ابوبکر صدیق جورشتہ داری اور محتاجی کی وجہ سے مسطح سے کچھ سلوک کرتے تھے انھوں نے کہا:اب میں مسطح سے کبھی کوئی سلوک نہیں کرنے کا(اس نے ایسی شرارت کی) عائشہ پر ایسی تہمت لگائی تب االلہ تعالیٰ نے (اسی سورہ نور) میں یہ آیت اتاری: جو لوگ تم میں بزرگی اور مقدور والے ہیں وہ یوں قسم نہ کھائیں -اخیر آیت -غفور رحیم تک، اس وقت ابوبکر کہنے لگے: کیوں نہیں، میں تو یہ چاہتاہوں۔ االلہ مجھ کوبخشے اور انھوں نے مسطح کو جو دیاکرتے تھے پھر دیناشروع کردیا۔کہنے لگے: االلہ کی قسم،میں یہ معمول کبھی بند نہیں کرنے کا۔ عائشہ کہتی ہیں: آپ نے (تہمت کے دنوں میں) ام المومنین زینب (جومیری سوکن تھیں) سے میرا حال پوچھا۔ آپ نےفرمایا: تم عائشہ کو کیسا سمجھتی ہو؟ تم نے اس کوکیسا دیکھا؟ انھوں نے کہا: اللہ کےرسول!میں اپنے کان اور آنکھ کو بچائے رکھتی ہوں۔ االلہ کی قسم، میں توعائشہ کو اچھی ہی سمجھتی ہوں۔عائشہ کہتی ہیں: آپ کی بیویوں میں زینب ہی میرے برابر کی تھیں۔ االلہ تعالیٰ نے ان کی پرہیزگاری کی وجہ سے ان کوبچائےرکھا، لیکن ان کی بہن حمنہ نے اپنی بہن کے خیال سے لڑنا شروع کیا۔دوسرے تہمت لگانے والوں کے ساتھ تباہ ہوئیں۔\nاسی موقعے پر درج ذیل آیات کانزول ہوا: ﴿إِنَّ ٱلَّذِينَ جَآءُو بِٱلۡإِفۡكِ عُصۡبَةࣱ مِّنكُمۡۚ لَا تَحۡسَبُوهُ شَرࣰّ ا لَّكُمۖ بَلۡ هُوَ خَيۡرࣱ لَّكُمۡۚ لِكُلِّ ٱمۡرِيࣲٕ مِّنۡهُم مَّا ٱكۡتَسَبَ مِنَ ٱلۡإِثۡمِۚ وَٱلَّذِي تَوَلَّىٰ كِبۡرَهُۥ مِنۡهُمۡ لَهُۥ عَذَابٌ عَظِيمࣱ لَّوۡلَآ إِذۡ سَمِعۡتُمُوهُ ظَنَّ ٱلۡمُؤۡمِنُونَ وَٱلۡمُؤۡمِنَٰتُ بِأَنفُسِهِمۡ خَيۡرࣰ ا وَقَالُواْ هَٰذَآ إِفۡكࣱ مُّبِينࣱ لَّوۡلَا جَآءُو عَلَيۡهِ بِأَرۡبَعَةِ شُهَدَآءَۚ فَإِذۡ لَمۡ يَأۡتُواْ بِٱلشُّهَدَآءِ فَأُوْلَٰٓئِكَ عِندَ ٱللَّهِ هُمُ ٱلۡكَٰذِبُونَ وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ لَمَسَّكُمۡ فِي مَآ أَفَضۡتُمۡ فِيهِ عَذَابٌ عَظِيمٌ إِذۡ تَلَقَّوۡنَهُۥ بِأَلۡسِنَتِكُمۡ وَتَقُولُونَ بِأَفۡوَاهِكُم مَّا لَيۡسَ لَكُم بِهِۦ عِلۡمࣱ وَتَحۡسَبُونَهُۥ هَيِّنࣰ ا وَهُوَ عِندَ ٱللَّهِ عَظِيمࣱ وَلَوۡلَآ إِذۡ سَمِعۡتُمُوهُ قُلۡتُم مَّا يَكُونُ لَنَآ أَن نَّتَكَلَّمَ بِهَٰذَا سُبۡحَٰنَكَ هَٰذَا بُهۡتَٰنٌ عَظِيمࣱ يَعِظُكُمُ ٱللَّهُ أَن تَعُودُواْ لِمِثۡلِهِۦٓ أَبَدًا إِن كُنتُم مُّؤۡمِنِينَ وَيُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِۚ وَٱللَّهُ عَلِيمٌ حَكِيمٌ إِنَّ ٱلَّذِينَ يُحِبُّونَ أَن تَشِيعَ ٱلۡفَٰحِشَةُ فِي ٱلَّذِينَ ءَامَنُواْ لَهُمۡ عَذَابٌ أَلِيمࣱ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ وَأَنَّ ٱللَّهَ رَءُوفࣱ رَّحِيمࣱ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ وَمَن يَتَّبِعۡ خُطُوَٰتِ ٱلشَّيۡطَٰنِ فَإِنَّهُۥ يَأۡمُرُ بِٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِۚ وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ مَا زَكَىٰ مِنكُم مِّنۡ أَحَدٍ أَبَدࣰ ا وَلَٰكِنَّ ٱللَّهَ يُزَكِّي مَن يَشَآءُۗ وَٱللَّهُ سَمِيعٌ عَلِيمࣱ‏﴾ [النور: ۱۱-۲۱] \"جولوگ یہ بہت بڑا بہتان باندھ لائے ہیں،یہ بھی تم میں سے ہی ایک گروہ ہے۔تم اسے اپنے لیے برانہ سمجھو،بلکہ یہ تو تمھارے حق میں بہتر ہے۔ہاں ان میں سے ہر ایک شخص پر اتنا گناہ ہے،جتنا اس نےکمایا ہےاور ان میں سےجس نے اس کے بہت بڑے حصے کو سرانجام دیا ہے، اس کے لیے عذاب بھی بہت ہی بڑاہے۔اسے سنتے ہی مومن مردوں عورتوں نے اپنے حق میں نیک گمانی کیوں نہ کیا اور کیوں نہ کہہ دیا کہ یہ تو کھلم کھلا صریح بہتان ہے۔وہ اس پر چار گواہ کیوں نہ لائے؟ اور جب گواہ نہیں لائے تو یہ بہتان بازلوگ یقیناً االلہ کے نزدیک بالکل جھوٹے ہیں۔اگر االلہ تعالیٰ کافضل وکرم تم پر دنیا اور آخرت میں نہ ہوتا تویقیناً تم نے جس بات کے چرچے شروع کررکھے تھے اس بارے میں تمھیں بہت بڑا عذاب پہنچتا۔جبکہ تم اسے اپنی زبانوں سے نقل در نقل کرنے لگے اور اپنے منہ سے وہ بات نکالنے لگے جس کی تمھیں مطلق خبر نہ تھی،گو یاتم اسے ہلکی بات سمجھتے رہے، لیکن االلہ تعالیٰ کے نزدیک وہ بہت بڑ ی بات تھی۔تم نے ایسی بات کو سنتے ہی کیوں نہ کہہ دیا کہ ہمیں ایسی بات منہ سے نکالنی بھی لائق نہیں۔یاااللہ! توپاک ہے، یہ توبہت بڑا بہتان ہے اور تہمت ہے۔االلہ تعالیٰ تمھیں نصیحت کرتا ہے کہ پھر کبھی ایسا کام نہ کرنا، اگر تم سچے مومن ہو۔ االلہ تعالیٰ تمھارے سامنے اپنی آیتیں بیان فرمارہا ہے اور االلہ تعالیٰ علم وحکمت والا ہے۔ جو لوگ مسلمانوں میں بے حیائی پھیلانے کے آرزو مند رہتے ہیں، ان کے لیے دنیا اور آخرت میں درد ناک عذاب ہیں۔االلہ سب کچھ جانتا ہے اور تم کچھ بھی نہیں جانتے۔اگر تم پر االلہ تعالیٰ کافضل اور اس کی رحمت نہ ہوتی اور یہ بھی کہ االلہ تعالیٰ بڑی شفقت رکھنے والامہربان ہے۔(توتم پر عذاب اترجاتا)۔ ایمان والو!شیطان کے قدموں کی پیروی نہ کرو۔ جوشخص شیطانی قدموں کی پیروی کرے تووہ بے حیائی اور برے کاموں کاہی حکم کرے گا اوراگر االلہ تعالیٰ کا فضل وکرم تم پر نہ ہوتا تو تم میں سے کوئی بھی کبھی بھی پاک صاف نہ ہوتا۔ لیکن االلہ تعالیٰ جسے پاک کرنا چاہےکردیتا ہے اورااللہ سب سننے والا سب جاننے والاہے\"۔(صحیح البخاری: ۴۱۴۱، وصحیح مسلم: ۲۷۷۰/۵۶)\nیہی منافقوں کا سردار عبدااللہ بن ابی ہے،جس نے غزوہ بنومصطلق کے موقعے پر یہ بات کہی تھی: ﴿يَقُولُونَ لَئِن رَّجَعۡنَآ إِلَى ٱلۡمَدِينَةِ لَيُخۡرِجَنَّ ٱلۡأَعَزُّ مِنۡهَا ٱلۡأَذَلَّۚ وَلِلَّهِ ٱلۡعِزَّةُ وَلِرَسُولِهِۦ وَلِلۡمُؤۡمِنِينَ وَلَٰكِنَّ ٱلۡمُنَٰفِقِينَ لَا يَعۡلَمُونَ﴾ [المنافقون: ۸] \"یہ کہتے ہیں کہ اگر ہم اب لوٹ کر مدینے جائیں گے تو عزت والا وہاں سے ذلت والےکو نکال دے گا۔سنو! عزت تو صرف اللہ تعالیٰ کے لیے اور اس کے رسول کے لیے اور ایمان داروں کے لیے ہے، لیکن یہ منافق جانتے نہیں\"۔\nاس کے بیٹے عبدااللہبن عبدااللہ بن ابی اس واقعہ سے پہلے ہی مسلمان ہوچکے تھے۔اس موقعے پر انھوں نے اپنے منافق باپ کوقتل کرنے کے لیےنبی اکرم صلی اللہ علیہ وسلم سےاجازت مانگی۔لیکن آپ نے ایسا کرنے سےمنع کردیا۔کچھ ہی دنوں بعد اس کی وفات ہوگئی۔اس کےبیٹے نے رسول اللہ صلی اللہ علیہ وسلم سے آپ کا کُرتا مانگا تاکہ اس میں لپیٹ کر اپنے باپ کودفن کردے۔آپ نے اپنا کرتا اسے دے دیا۔پھر بیٹے نے آپ سے گزارش کی آپ اس کے باپ کی نماز جنازہ بھی پڑھادیں۔ آپ چونکہ رحمۃ للعالمین تھے،اس لیے آپ نے اس کی نماز جنازہ بھی پڑھادی،جوآپ کو اور تمام مسلمانوں کو ہمیشہ تکلیف پہنچایا کرتا تھا۔اسی موقعے پر قرآن مجید کی یہ آیت نازل ہوئی: ﴿وَلَا تُصَلِّ عَلَىٰٓ أَحَدࣲ مِّنۡهُم مَّاتَ أَبَدࣰ ا وَلَا تَقُمۡ عَلَىٰ قَبۡرِهِۦٓۖ إِنَّهُمۡ كَفَرُواْ بِٱللَّهِ وَرَسُولِهِۦ وَمَاتُواْ وَهُمۡ فَٰسِقُونَ﴾ [التوبة: ۸۴] \"ان میں سے اگر کوئی مرجائے تو آپ اس کے جنازے کی نماز ہرگز نہ ادا کریں اور نہ اس کی قبر پر کھڑے ہوں۔ یہ االلہ اور اس کے رسول کے منکر ہیں اور مرے بھی تو بدکار اور بے اطاعت ہوکر\"۔","",{}],[413,"§عجل\nاردو میں عجل کوبچھڑاکہتے ہیں۔گائے کا چھوٹا بچہ(بچھڑا)قدیم زمانے سے ہی کھانے اور قربانی کےلیے استعمال ہوتا چلاآرہاہے۔\nجب ابراہیم علیہ السلام کو فرشتے خوش خبری دینے آئے تو ان کومہمان سمجھ کر فوراً بھنا ہوابچھڑے کا گوشت لےکر آئے۔ارشادباری تعالیٰ ہے:﴿فَرَاغَ إِلَىٰٓ أَهۡلِهِۦ فَجَآءَ بِعِجۡلࣲ سَمِينࣲ فَقَرَّبَهُۥٓ إِلَيۡهِمۡ قَالَ أَلَا تَأۡكُلُونَ﴾ [الذاریات: ۲۶-۲۷] \"پھر وہ خاموشی سے اپنے گھر والوں کے پاس ایک موٹا تازہ بچھڑا (بھنا ہوا گوشت) لےکر آئے اور اسے ان کے سامنے پیش کیااور کہا: آپ کھاتے کیوں نہیں؟\"۔\nلیکن مشرک لوگ جس طرح دوسری فائدہ مند اشیا کو بت بنا کران کی پرستش کرنے لگے،اسی طرح انھوں نےبچھڑے کو بھی بت بنا لیا۔مصر کے لوگ بھی بچھڑے کا بت بنا کراس کی عبادت کرتے تھے، جس کو عبیس کہا جاتا تھا۔اس لیے ان سے متاثر ہوکر بنی اسرائیل نے بھی جب موسیٰ علیہ السلام کوہ طور پرتورات لینے گئے تھے تو بچھڑے کا بت بنالیا۔ارشادباری تعالیٰ ہے: ﴿وَإِذۡ وَٰعَدۡنَا مُوسَىٰٓ أَرۡبَعِينَ لَيۡلَةࣰ ثُمَّ ٱتَّخَذۡتُمُ ٱلۡعِجۡلَ مِنۢ بَعۡدِهِۦ وَأَنتُمۡ ظَٰلِمُونَ﴾ [البقرة: ۵۱] \"یاد کرو جب ہم نے موسیٰ سے چالیس راتوں کا وعدہ ٹھہرایا تو اس کے پیچھے تم بچھڑےکو اپنا معبود بنا بیٹھے اورتم ظالم تھے\"۔\nاورفرمایا:﴿وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ يَٰقَوۡمِ إِنَّكُمۡ ظَلَمۡتُمۡ أَنفُسَكُم بِٱتِّخَاذِكُمُ ٱلۡعِجۡلَ فَتُوبُوٓاْ إِلَىٰ بَارِئِكُمۡ فَٱقۡتُلُوٓاْ أَنفُسَكُمۡ ذَٰلِكُمۡ خَيۡرࣱ لَّكُمۡ عِندَ بَارِئِكُمۡ فَتَابَ عَلَيۡكُمۡۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ﴾ [البقرة: ۵۴] \"جب موسیٰ نے اپنی قوم سے کہا:اے میری قوم کے لوگو!تم لوگوں نے بچھڑے کو معبود بنا کر اپنے اوپر ظلم کیا\"۔\nمزیدارشادہے: ﴿وَلَقَدۡ جَآءَكُم مُّوسَىٰ بِٱلۡبَيِّنَٰتِ ثُمَّ ٱتَّخَذۡتُمُ ٱلۡعِجۡلَ مِنۢ بَعۡدِهِۦ وَأَنتُمۡ ظَٰلِمُونَ﴾ [البقرة: ۹۲] \"تمھارے پاس موسیٰ کھلی نشانیاں لےکر آیا پھر بھی تم نےبچھڑے کو اپنا دیوتابنا لیااور تم بڑے ظالم تھے\"۔\nموسیٰ علیہ السلام نے جو اللہ کے رسول تھے اور دوسرے رسولوں کی طرح خالص توحید کی دعوت لےکر آئے تھے، انھوں نے جب دیکھا کہ ان کی قوم بچھڑا بنا کر اس کو پوجنے لگی ہے،تو بہت ناراض ہوےاور اسی حالت میں اپنے بھائی ہارون علیہ السلام کا جو ان کے ساتھ نبی بنا کر بھیجے گئے تھے،سر پکڑ کر کھینچنےلگے،کیونکہ موسیٰ علیہ السلام طور پر جاتے ہوے ہارون علیہ السلام کو اپنا قائم مقام بناکر گئے تھے۔ اللہ تعالیٰ کا ارشادہے: ﴿وَلَمَّا رَجَعَ مُوسَىٰٓ إِلَىٰ قَوۡمِهِۦ غَضۡبَٰنَ أَسِفࣰ ا قَالَ بِئۡسَمَا خَلَفۡتُمُونِي مِنۢ بَعۡدِيٓۖ أَعَجِلۡتُمۡ أَمۡرَ رَبِّكُمۡۖ وَأَلۡقَى ٱلۡأَلۡوَاحَ وَأَخَذَ بِرَأۡسِ أَخِيهِ يَجُرُّهُۥٓ إِلَيۡهِۚ قَالَ ٱبۡنَ أُمَّ إِنَّ ٱلۡقَوۡمَ ٱسۡتَضۡعَفُونِي وَكَادُواْ يَقۡتُلُونَنِي فَلَا تُشۡمِتۡ بِيَ ٱلۡأَعۡدَآءَ وَلَا تَجۡعَلۡنِي مَعَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ﴾ [الأعراف: ۱۵۰] \"جب موسیٰ غصّے اور غم میں بھرے ہوے اپنی قوم کی جانب لوٹے تو انھوں نے کہا: تم لوگوں نے میرے پیچھے میری جگہ برا کیا۔کیا تم اپنے رب کے حکم سے پہلے ہی عجلت کر بیٹھے؟پھر انھوں نے تختیاں ڈال دیں اور اپنے بھائی کا سر پکڑکر اسے اپنی جانب کھینچنے لگے۔وہ بولااے میری ماں کے بیٹے!لوگوں نے مجھے کمزور سمجھ لیااور قریب تھا کہ مار ڈالتے،اس لیے دشمنوں کو مجھ پر ہنسنےکا موقعے نہ دیجیےاور ظالم لوگوں میں مجھے شامل نہ کیجیے\"۔\nاس آیت سے پتا چلتا ہے کہ ہارون علیہ السلام نے بچھڑے کی عبادت کی اجازت نہیں دی تھی۔ لیکن اس خوف سے کہ کہیں ان کو نقصان نہ پہنچایا جائے وہ خاموش رہے۔ان کو یہ بھی خوف تھا کہ اگر سختی کرتے ہیں تو بنی اسرائیل میں کہیں اختلاف نہ ہوجائے۔ قرآن مجیدمیں ہے:﴿قَالَ يَبۡنَؤُمَّ لَا تَأۡخُذۡ بِلِحۡيَتِي وَلَا بِرَأۡسِيٓۖ إِنِّي خَشِيتُ أَن تَقُولَ فَرَّقۡتَ بَيۡنَ بَنِيٓ إِسۡرَٰٓءِيلَ وَلَمۡ تَرۡقُبۡ قَوۡلِي﴾ [طه: ۹۴] \"اس نے کہا:اے میری ماں کے بیٹے!میری داڑھی نہ پکڑ اور نہ میراسر۔میں ڈرا کہ آپ کہیں گے کہ تونے بنی اسرائیل میں پھوٹ ڈال دی اور میری بات پر دھیان نہیں دیا\"۔\nہارون علیہ السلام کےاس بیان سے بائبل کے اس دعوے کی تردید ہوتی ہے کہ بچھڑا بنانے والے اور اس کی عبادت کرنے والے ہارون تھے،جنھوں نے بنی اسرائیل کی عورتوں سےسونے کی بالیاں اکٹھی کیں اورپھر ہارون نے انھیں اپنے ہاتھ میں لیا اور سونے کا ایک بچھڑا ڈھال کر بنایا اور کہا:اے اسرائیل!یہ تمھارا وہ دیوتاہے جو تمھیں ملک مصر سے آزاد کرا لایا ہے اورپھر اس کے آگے ایک قربان گاہ بنائی، تاکہ کل سے لوگ قربانی کریں۔(ملاحظہ فرمائیں:خروج: ۳۲:۴ـ۶)\nجب کہ صحیح بات یہ ہے کہ بچھڑا بنانے والا سامری نامی شخص تھا،جس کی تفصیل قرآن میں آئی ہے۔بیشتر مفسروں کا خیال ہےکہ یہ کوئی منافق تھا،جوموسیٰ علیہ السلام پر ایمان لانے والوں کو راہ راست سے بھٹکایا کرتاتھا۔ہمارے پاس اس کے بارے میں کوئی زیادہ معلومات نہیں ہے۔بہرحال،یہ کوئی بت پرست تھا جو کسی طرح بنی اسرائیل کے ساتھ مصر سے نکل کر سینا میں آگیا تھا،جہاں موسیٰ علیہ السلام اپنی قوم کے ساتھ ۴۰سال تک رکے رہے۔\nموسیٰ علیہ السلام نے سامری سے بھی بات کی۔قرآن مجیدمیں ہے:﴿قَالَ فَمَا خَطۡبُكَ يَٰسَٰمِرِيُّ قَالَ بَصُرۡتُ بِمَا لَمۡ يَبۡصُرُواْ بِهِۦ فَقَبَضۡتُ قَبۡضَةࣰ مِّنۡ أَثَرِ ٱلرَّسُولِ فَنَبَذۡتُهَا وَكَذَٰلِكَ سَوَّلَتۡ لِي نَفۡسِي قَالَ فَٱذۡهَبۡ فَإِنَّ لَكَ فِي ٱلۡحَيَوٰةِ أَن تَقُولَ لَا مِسَاسَۖ وَإِنَّ لَكَ مَوۡعِدࣰ ا لَّن تُخۡلَفَهُۥۖ وَٱنظُرۡ إِلَىٰٓ إِلَٰهِكَ ٱلَّذِي ظَلۡتَ عَلَيۡهِ عَاكِفࣰ اۖ لَّنُحَرِّقَنَّهُۥ ثُمَّ لَنَنسِفَنَّهُۥ فِي ٱلۡيَمِّ نَسۡفًا إِنَّمَآ إِلَٰهُكُمُ ٱللَّهُ ٱلَّذِي لَآ إِلَٰهَ إِلَّا هُوَۚ وَسِعَ كُلَّ شَيۡءٍ عِلۡمࣰ ا﴾ [طه: ۹۵-۹۸] \"(موسیٰ نے)کہا: اے سامری!تیرا کیا معاملہ ہے؟ اس نے کہا: میں نے وہ کچھ دیکھا جسے دوسروں نےنہیں دیکھا،پھر میں نے رسول (فرشتے)کی راہ قدم سے ایک مٹھی مٹی لی،پھراس کو (بچھڑےمیں)ڈال دیا۔میرے دل نے مجھے ایسی ہی پٹی پڑھائی۔ (موسیٰ نے)کہا: اچھا تو جا!اب اس زندگی میں تیرے لیے یہی ہے کہ تو یہ کہتا رہے کہ مجھے کوئی چھوئے نہیں اور یقیناً تیرے لیے (آخرت میں سزا کا)ایک یقینی وعدہ ہے جو تجھ سے ہر گز ہرگز نہیں ٹلے گا اوردیکھ اپنے الہ کوجس پر توجما بیٹھا ہے۔یقیناً ہم اسے جلا ڈالیں گے۔پھر اسے چو ر اچور اکر کے دریا میں بہا دیں گے۔(لوگو!)تمھارا الہ (معبود) تو بس وہی اللہ ہے، جس کے سوا کوئی الہ نہیں۔اپنے علم سے وہ ہر چیز کو محیط ہے\"۔\nاس طرح بنی اسرائیل کے دلوں میں بچھڑے کی محبت بیٹھ گئی،جس کی وجہ سے وہ اس کی بندگی سے آزادنہیں ہوسکے۔ارشادباری تعالیٰ ہے: ﴿وَإِذۡ أَخَذۡنَا مِيثَٰقَكُمۡ وَرَفَعۡنَا فَوۡقَكُمُ ٱلطُّورَ خُذُواْ مَآ ءَاتَيۡنَٰكُم بِقُوَّةࣲ وَٱسۡمَعُواْۖ قَالُواْ سَمِعۡنَا وَعَصَيۡنَا وَأُشۡرِبُواْ فِي قُلُوبِهِمُ ٱلۡعِجۡلَ بِكُفۡرِهِمۡۚ قُلۡ بِئۡسَمَا يَأۡمُرُكُم بِهِۦٓ إِيمَٰنُكُمۡ إِن كُنتُم مُّؤۡمِنِينَ﴾ [البقرة: ۹۳] \"یاد کرو جب ہم نے تم سے وعدہ لیااور طور کو تم پراٹھائے رکھا (اور کہا):جو کچھ تمھیں دیا جارہاہے اسے پوری طاقت سے پکڑ لواور سنو،انھوں نے کہا:ہم نے سنا لیکن ہم نے نافرمانی کیان کے کفر کی وجہ سے ان کے دلوں میں بچھڑے کی محبت ڈال دی گئی\"۔\nقرآن مجیدمیں ان بچھڑے کی پوجا کرنے والوں کو دنیا اور آخرت میں سزا کی خبر دی گئی ہے:﴿إِنَّ ٱلَّذِينَ ٱتَّخَذُواْ ٱلۡعِجۡلَ سَيَنَالُهُمۡ غَضَبࣱ مِّن رَّبِّهِمۡ وَذِلَّةࣱ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُفۡتَرِينَ﴾ [الأعراف: ۱۵۲] \"جن لوگوں نے بچھڑے کومعبود بنایا،وہ اپنے رب کی جانب سے عذاب اور دُنیوی زندگی میں بے عزت ہوکر رہیں گے اور جھوٹ گھڑنے والوں کو ہم ایسا ہی بدلہ دیتے ہیں\"۔\nیہودیوں کی تاریخ سے بھی پتا چلتا ہے کہ وہ بچھڑے کی محبت سے کبھی الگ نہیں ہوسکے۔بنی اسرائیل کی حکومت جب دو حصوں میں تقسیم ہوگئی تویربعام بن نابات نے جو شمالی حصہ کا پہلا بادشاہ تھا بچھڑے کے دو بت بنائے۔ایک کو’ایل‘میں اور دوسرے کو ’دان‘میں نصب کروادیا۔پھر بنی اسرائیل بچھڑے کےساتھ ساتھ بیل کا بھی بت بنانے لگےاور اپنی عبادت گاہوں میں رکھنے لگے،جس کی وجہ سے ان میں بچھڑے اور بیل کی پرستش رائج ہوئی۔بائبل میں بھی بار بار ان دونوں کا ذکر ہوا ہے۔","",{}],[414,"§عدت\nعدت کے لفظی معنی حساب اورگنتی کے ہیں۔لیکن تین مقامات پر قرآن نے عدت کو اس اصطلاحی معنی میں استعمال کیا ہے کہ جب کوئی عورت اپنے شوہر سے علاحدہ ہوجائے تواس پر لازم ہے کہ وہ عدت میں رہے۔ اس اثنا میں وہ دوسرا نکاح نہ کرے۔تاکہ یقین کے ساتھ یہ معلوم ہوجائے کہ وہ حاملہ نہیں ہے۔یہ عدتیں مختلف حالات میں مختلف ہوتی ہیں۔ ان کا مختصر ذکر درج ذیل ہے:\n۱-اگر کوئی شخص اپنی بیوی کوطلاق دینا چاہے تو اس کامناسب وقت یہ ہے کہ بیوی طہارت کی حالت میں ہو۔ حالت حیض میں نہ ہو۔سورہ الطلاق میں ہے:﴿يَٰٓأَيُّهَا ٱلنَّبِيُّ إِذَا طَلَّقۡتُمُ ٱلنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحۡصُواْ ٱلۡعِدَّةَۖ وَٱتَّقُواْ ٱللَّهَ رَبَّكُمۡۖ لَا تُخۡرِجُوهُنَّ مِنۢ بُيُوتِهِنَّ وَلَا يَخۡرُجۡنَ إِلَّآ أَن يَأۡتِينَ بِفَٰحِشَةࣲ مُّبَيِّنَةࣲۚ وَتِلۡكَ حُدُودُ ٱللَّهِۚ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَقَدۡ ظَلَمَ نَفۡسَهُۥۚ لَا تَدۡرِي لَعَلَّ ٱللَّهَ يُحۡدِثُ بَعۡدَ ذَٰلِكَ أَمۡرࣰ ا﴾ [الطلاق: ۱] \"اے نبی! (اپنی امت سے کہو کہ) جب تم اپنی بیویوں کو طلا ق دینا چاہو تو ان کی عدت (کے دنوں کے آغاز) میں انھیں طلاق دو اورعدت کاحساب رکھو\"۔\n۲- مطلقہ عورت کی عدت تین بارحیض سے پاکیاورصفائی ہے۔اللہ تعالیٰ کا ارشادہے: ﴿وَٱلۡمُطَلَّقَٰتُ يَتَرَبَّصۡنَ بِأَنفُسِهِنَّ ثَلَٰثَةَ قُرُوٓءࣲۚ وَلَا يَحِلُّ لَهُنَّ أَن يَكۡتُمۡنَ مَا خَلَقَ ٱللَّهُ فِيٓ أَرۡحَامِهِنَّ إِن كُنَّ يُؤۡمِنَّ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِي ذَٰلِكَ إِنۡ أَرَادُوٓاْ إِصۡلَٰحࣰ اۚ وَلَهُنَّ مِثۡلُ ٱلَّذِي عَلَيۡهِنَّ بِٱلۡمَعۡرُوفِۚ وَلِلرِّجَالِ عَلَيۡهِنَّ دَرَجَةࣱۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ﴾ [البقرة: ۲۲۸] \"طلاق والی عورتیں اپنے آپ کوتین حیض تک روکے رکھیں۔انھیں حلال نہیں کہ االلہ نے ان کےرحم میں جوپیدا کیا ہو، وہ ا سے چھپائیں۔ اگر انھیں االلہ تعالیٰ اور قیامت کے دن پر ایمان ہو، ان کے خاوند اس مدت میں انھیں لوٹالینے کے پورے حق دار ہیں اگر ان کاارادہ اصلاح کاہو اورعورتوں کے بھی ویسے ہی حق ہیں،جیسے ان پر مردوں کے ہیں اچھائی کے ساتھ۔ہاں مردوں کوعورتوں پر فضلیت ہے اور االلہ تعالیٰ عزیز وحکیم(غالب ہے حکمت والا) ہے\"۔\n۳- عدت کے درمیان مطلقہ عورت اپنے شوہر کے گھر میں ہی رہے گی۔تاکہ اگر شوہر طلاق سے رجوع کرنا چاہے تو رجوع کرلےاور وہ میاں بیوی کی طرح حسب سابق زندگی گزارنے لگیں۔\n۴- وہ عورت جس کا حیض بند ہوچکا ہو،اس کی عدت تین ماہ ہےاورجوابھی بلوغت کے مرحلے کونہ پہنچی ہو اس کی عدت بھی تین ماہ ہے۔ سورہ الطلاق میں ہے:﴿وَٱلَّٰٓـِٔي يَئِسۡنَ مِنَ ٱلۡمَحِيضِ مِن نِّسَآئِكُمۡ إِنِ ٱرۡتَبۡتُمۡ فَعِدَّتُهُنَّ ثَلَٰثَةُ أَشۡهُرࣲ وَٱلَّٰٓـِٔي لَمۡ يَحِضۡنَۚ وَأُوْلَٰتُ ٱلۡأَحۡمَالِ أَجَلُهُنَّ أَن يَضَعۡنَ حَمۡلَهُنَّۚ وَمَن يَتَّقِ ٱللَّهَ يَجۡعَل لَّهُۥ مِنۡ أَمۡرِهِۦ يُسۡرࣰ ا﴾ [الطلاق: ۴] \"تمھاری عورتوں میں سے جو عورتیں حیض سے ناامید ہوگئی ہوں،اگر تمھیں شبہ ہو توان کی عدت تین مہینے ہے اور ان کی بھی جنھیں حیض آنا شروع نہ ہواہواور حاملہ عورتوں کی عدت ان کا وضع حمل ہے اور جو شخص االلہ تعالیٰ سے ڈر ے گا االلہ اس کے(ہر) کام میں آسانی کردے گا\"۔\n۵- اگرکسی حاملہ عورت کو طلاق ہوئی ہوتو اس کی عدت بچے کی پیدایش ہے۔ولادت کے بعد ہی اس کی عدت پوری ہوجائے گی۔سورہ الطلاق ہی میں ہے:﴿وَٱلَّٰٓـِٔي يَئِسۡنَ مِنَ ٱلۡمَحِيضِ مِن نِّسَآئِكُمۡ إِنِ ٱرۡتَبۡتُمۡ فَعِدَّتُهُنَّ ثَلَٰثَةُ أَشۡهُرࣲ وَٱلَّٰٓـِٔي لَمۡ يَحِضۡنَۚ وَأُوْلَٰتُ ٱلۡأَحۡمَالِ أَجَلُهُنَّ أَن يَضَعۡنَ حَمۡلَهُنَّۚ وَمَن يَتَّقِ ٱللَّهَ يَجۡعَل لَّهُۥ مِنۡ أَمۡرِهِۦ يُسۡرࣰ ا﴾ [الطلاق: ۴] \"اور حاملہ عورتوں کی عدت ان کا وضع حمل ہے\"۔\n۶- اگرکسی ایسی عورت کوطلاق دی گئی ہو جس کے ساتھ جسمانی تعلقات قائم نہ ہوے ہو ں تو اس کےلیے کوئی عدت نہیں ہے۔ سورہ الاحزاب میں ہے:﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا نَكَحۡتُمُ ٱلۡمُؤۡمِنَٰتِ ثُمَّ طَلَّقۡتُمُوهُنَّ مِن قَبۡلِ أَن تَمَسُّوهُنَّ فَمَا لَكُمۡ عَلَيۡهِنَّ مِنۡ عِدَّةࣲ تَعۡتَدُّونَهَاۖ فَمَتِّعُوهُنَّ وَسَرِّحُوهُنَّ سَرَاحࣰ ا جَمِيلࣰ ا﴾ [الأحزاب: ۴۹] \"اے مومنو! جب تم مومن عورتوں سے نکاح کرو پھرہاتھ لگانے سے پہلے (ہی) طلاق دے دو تو ان پرتمھارا کوئی حق عدت کانھیں جسے تم شمار کرو،پس تم کچھ نہ کچھ انھیں دےدواور بھلےطریقے پر انھیں رخصت کردو\"۔\n۷- اگر کسی عورت کے شوہر کی وفات ہوجائے تو اس کی عدت چار ماہ دس دن ہے۔ سورہ البقرة میں ہے: ﴿وَٱلَّذِينَ يُتَوَفَّوۡنَ مِنكُمۡ وَيَذَرُونَ أَزۡوَٰجࣰ ا يَتَرَبَّصۡنَ بِأَنفُسِهِنَّ أَرۡبَعَةَ أَشۡهُرࣲ وَعَشۡرࣰ اۖ فَإِذَا بَلَغۡنَ أَجَلَهُنَّ فَلَا جُنَاحَ عَلَيۡكُمۡ فِيمَا فَعَلۡنَ فِيٓ أَنفُسِهِنَّ بِٱلۡمَعۡرُوفِۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرࣱ‏﴾ [البقرة: ۲۳۴] \"تم میں سے جو لوگ فوت ہو جائیں اور بیویاں چھوڑ جائیں، وہ عورتیں اپنے آپ کو چار مہینے اور دس دن عدت میں رکھیں پھر جب مدت ختم کرلیں تو جو اچھائی کے ساتھ وہ اپنے لیےکریں اس میں تم پر کوئی گناہ نہیں اور اللہ تعالیٰ تمھارے عمل سے خبردار ہے\"۔\n۸- اگر وہ بیوی جس کے شوہر کی وفات ہوگئی ہو حاملہ ہوتو اس کی عدت وضع حمل ہے۔ ایک صحیح حدیث میں آیا ہے کہ سبیعہ اسلمیہ نامی ایک عورت کے شوہر کی وفات ہوگئی اور دوتین روز کے بعد اس کے یہاں ولادت ہوئی،اس نے یہ معاملہ نبی اکرم صلی اللہ علیہ وسلم کے پاس پیش کیا توآپنے ولادت کے بعد ہی اسے دوسری شادی کرنے کی اجازت دےدی۔\n۹- یہاں عدت گزارنے کے جن حالات کا ذکر ہوا ہے،ان میں عدت پوری ہونےکے بعد ہی عورت دوسری شادی کرسکتی ہے۔عدت کے دنوں میں عورت کو اس کے شوہر کے گھر سے نکالا نہیں جاسکتا ہے۔بلکہ اس دوران شوہر کی جانب سے عورت کےاخراجات اوررہایش کا انتظام کرنا لازمی ہے۔\n۱۰- عدت کی تکمیل کے بعد مطلّقہ اپنے باپ کے گھر چلی جائے گی۔پھر اگرشادی کی خواہش مند ہو تو دوبارہ شادی کی اجازت ہے۔ بیوہ عورت بھی اگر نکاح کی خواہش مند ہوں تو وہ بھی متوفی شوہر کے گھر سے اپنے باپ کے گھر چلی جائے گی (الا یہ کہ ان کے بیٹے ہوں اور نہ جانے دیں) اس طرح ایک عورت خواہ وہ مطلقہ ہو یا بیوہ اسلامی معاشرے میں اپنے پورے حقوق کے ساتھ دوبارہ نئی زندگی گزارسکتی ہے۔ اس لیے کہ اس اس پر کوئی پابندی اور رکاوٹ نہیں جیساکہ دوسرے مذاہب اور معاشرے میں بیوہ اور مطلقہ عورتوں پر لگائی جاتی ہے۔","",{}],[415,"§عدس\nاردو میں عدس کو دال کہتے ہیں۔ریگستان سینامیں بنی اسرائیل من و سلوٰی کھاتے کھاتے اکتا گئے تو انھوں نے موسی علیہ السلام سے کہا:﴿وَإِذۡ قُلۡتُمۡ يَٰمُوسَىٰ لَن نَّصۡبِرَ عَلَىٰ طَعَامࣲ وَٰحِدࣲ فَٱدۡعُ لَنَا رَبَّكَ يُخۡرِجۡ لَنَا مِمَّا تُنۢبِتُ ٱلۡأَرۡضُ مِنۢ بَقۡلِهَا وَقِثَّآئِهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَاۖ قَالَ أَتَسۡتَبۡدِلُونَ ٱلَّذِي هُوَ أَدۡنَىٰ بِٱلَّذِي هُوَ خَيۡرٌۚ ٱهۡبِطُواْ مِصۡرࣰ ا فَإِنَّ لَكُم مَّا سَأَلۡتُمۡۗ وَضُرِبَتۡ عَلَيۡهِمُ ٱلذِّلَّةُ وَٱلۡمَسۡكَنَةُ وَبَآءُو بِغَضَبࣲ مِّنَ ٱللَّهِۚ ذَٰلِكَ بِأَنَّهُمۡ كَانُواْ يَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقۡتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيۡرِ ٱلۡحَقِّۚ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ﴾ [البقرة: ۶۱] \"اے موسیٰ! ہم ایک ہی طرح کے کھانے پر صبر نہیں کرسکتے۔ لہٰذا اپنے رب سے دعا کرو کہ ہمارے لیے زمین سے ساگ، ککڑی، لہسن،دال اور پیاز پیدا کرے۔ اس نے کہا: کیاتم عمدہ چیزوں کوچھوڑ کر حقیرچیزوں کو لینا چاہتے ہو؟ اچھا!تم لوگ کسی شہر میں جابسو وہاں تمھاری مانگ پوری ہوجائے گی\"۔\nیہ موسی علیہ السلام کی طرف سے ایک طرح کی دھمکی تھی کہ تمھیں جس کام کے لیے مصر سے نکال کر یہاں لایا گیا ہے۔اس مقصد کو چھوڑ کر کھانے پینے میں لگ گئے ہو تو جاؤ کسی شہر میں آباد ہوجاؤ۔ وہاں تمھیں یہ ساری چیزیں ملیں گی۔ارشادباری تعالیٰ ہے: ﴿وَإِذۡ قُلۡتُمۡ يَٰمُوسَىٰ لَن نَّصۡبِرَ عَلَىٰ طَعَامࣲ وَٰحِدࣲ فَٱدۡعُ لَنَا رَبَّكَ يُخۡرِجۡ لَنَا مِمَّا تُنۢبِتُ ٱلۡأَرۡضُ مِنۢ بَقۡلِهَا وَقِثَّآئِهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَاۖ قَالَ أَتَسۡتَبۡدِلُونَ ٱلَّذِي هُوَ أَدۡنَىٰ بِٱلَّذِي هُوَ خَيۡرٌۚ ٱهۡبِطُواْ مِصۡرࣰ ا فَإِنَّ لَكُم مَّا سَأَلۡتُمۡۗ وَضُرِبَتۡ عَلَيۡهِمُ ٱلذِّلَّةُ وَٱلۡمَسۡكَنَةُ وَبَآءُو بِغَضَبࣲ مِّنَ ٱللَّهِۚ ذَٰلِكَ بِأَنَّهُمۡ كَانُواْ يَكۡفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقۡتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيۡرِ ٱلۡحَقِّۚ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ﴾ [البقرة: ۶۱] \"اسی وجہ سے ان پر ذلت ومسکنت مسلط کردی گئی اور وہ اللہ کے غیظ وغضب میں گھر گئے\"۔","",{}],[416,"§عدن\nعدن کےلفظی معنی اقامت کرنےاوروطن بنالینے کےہیں۔اسی سےقرآن مجیدمیں جنت عدن کا تذکرہ ہے۔جس کامطلب جنت کے دائمی ٹھکانے کا ہے۔جنت اہل ایمان کادائمی اورابدی ٹھکاناہے۔جو اس میں داخل ہوگا، وہ وہاں سےکبھی نہیں نکلے گا۔قرآن مجید میں ہے:﴿وَعَدَ ٱللَّهُ ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ جَنَّٰتࣲ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا وَمَسَٰكِنَ طَيِّبَةࣰ فِي جَنَّٰتِ عَدۡنࣲۚ وَرِضۡوَٰنࣱ﴾ [التوبة: ۷۲] \"ان ایمان دار مردوں اور عورتوں سے االلہ نے ان جنتوں کا وعدہ فرمایا ہے جن کے نیچے نہریں لہریں لے رہی ہیں،جہاں وہ ہمیشہ ہمیشہ رہنے والے ہیں اور ان سے صاف ستھر ے پاکیزہ محلات کا وعدہ ہے جو ہمیشہ رہنےوالی جنتوں میں ہیں\" اورعرش کے حاملین فرشتے االلہتعالیٰ سےکہیں گے:﴿رَبَّنَا وَأَدۡخِلۡهُمۡ جَنَّٰتِ عَدۡنٍ ٱلَّتِي وَعَدتَّهُمۡ وَمَن صَلَحَ مِنۡ ءَابَآئِهِمۡ وَأَزۡوَٰجِهِمۡ وَذُرِّيَّٰتِهِمۡۚ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ﴾ [المومن: ۸] \"اے ہمارے رب تو انھیں ہمیشہ رہنے والی جنت میں داخل کر جن کا تونے ان سے وعدہ کیا ہے\"۔(مزید تفصیل کے لیے دیکھیے: سورہ النحل: ا۳، سورہ الکہف: ا۳، سورہ طہ: ۷۶ وغیرہ)","",{}],[417,"§عذاب\nعذاب کےمعنی ہروہ چیزجوانسان کے لیے باعث مشقت ہو، تکلیف اورسزاہے۔یہ لفظ قرآن مجیدمیں باربار آیا ہے۔جس کا مطلب ہے،االلہ کی طرف سے سزا جوایمان نہ لانے والوں کو دی جائے گی،خواہ وہ اس دنیا میں دیجائے،جیسے مکہ کے بڑے بڑے سرداروں کو بدر کے میدان میں دی گئی یا وہ عذاب جوانھیں مرنے کے بعد دیا جائے۔کیونکہ االلہ اور اس کے رسول پر ایمان نہ لانا سب سے بڑا ظلم ہے۔ایسا شخص حقیقت میں االلہ تعالیٰ کی الوہیت کاانکار کررہاہے،جس نے اسے پیدا کیا۔اس کے رزق کاانتظام کیا۔اس کے لیے سورج اور چاند بنائے ایک محدودوقت تک روئے زمین پر زندگی گزارنے کا موقعے میسر کیا وغیرہ۔ ایسے شخص کے لیے االلہ تعالیٰ کے پاس کوئی انعام نہیں ہے۔بلکہ اس کے اعمال بد کی وجہ سے اس کے پاس دردناک عذاب ہے۔\nقرآن مجید اس وقت روئے زمین پرایسی تنہامذہبی کتاب ہے، جس میں مرنے کے بعد عذاب کا تفصیلی ذکرموجود ہے۔جب کہ دوسری آسمانی کتابوںمیں اس کی جانب اشارہ تو ملتا ہے، لیکن تفصیل نہیں۔یہ قرآن مجید کی خصوصیات میں سے ایک ہے کہ اس میں ایمان کے بارے میں تفصیلی بیان پایا جاتاہے۔تاکہ آدمی کواس بارے میں کوئی شک وشبہ نہ رہے۔ یہی تعلیم سارے انبیا ورسل کی تھی۔ لیکن ان کے پیروکاروں نے اس میں تغیر وتبدل کردیا۔وہ لوگ جنھیں عذاب دیا جائے گا وہ دو قسم کے ہوں گے۔ایک وہ لوگ ہوں گے،جنھوں نے االلہ اوراس کے رسول اور ان کی تعلیمات کو ٹھکرایا ہوگا۔ خواہ وہ ایک ہوں یاپورا گروہ۔اس ضمن میں انبیاے کرام کی ان قوموں کا تذکرہ قرآن مجید میں بار بار آیا ہے،جنھوں نے اپنے انبیاورسل کو ٹھکرادیا تو االلہ تعالیٰ نے ان کو عذاب میں مبتلا کردیا۔مثال کےلیے دیکھیے:نوح، صالح،ہود،لوط اورموسی علیہم السلام کی قومیں۔ان کو دُنیوی عذاب بھی دیا گیااور آخرت میں بھی یہ لوگ االلہ کےعذاب سے نجات نہیں پاسکیں گے۔بلکہ آخرت کا عذاب مزید سخت اور درد ناک ہوگا۔دوسرے وہ لوگ بھی عذاب کے مستحق ہوں گے جو انبیاے کرام پرایمان تولائے اورموحد تھےاورشرک سے دورتھے۔لیکن انھوں نےلوگوں پر ظلم وزیادتی کی۔کسی کی دولت غصب کرلی۔کسی کو قتل کردیا۔االلہ کے بندوں کے حقوق دبالیے اوردنیا میں ان سے معافی نہیں مانگی۔تو قیامت کے دن ان کو بھی اس ظلم وستم کے بدلے عذاب جھیلنا پڑے گا۔ جھیلنےکے بعد پھر جنت میں داخلہ ملے گا۔\nقرآن مجیدنے عذاب کے بارے میں کچھ اصول وضوابط بیان کیے ہیں۔ ان میں سے کچھ درج ذیل ہیں:\nا-کسی قو م پر اس وقت تک عذاب نہیں آئےگا، جب تک ان میں کوئی ڈرانے اور آگاہ کرنے والا رسول نہ بھیجا جائےاور لوگ اس کی دعوت ٹھکرانہ دیں۔ (دیکھیں: سورہ الاسراء : ۵ا)\nصرف نبی اکرم صلی اللہ علیہ وسلم کویہ خصوصیت دی گئی ہےکہ آپ کی امت اس دنیوی عذاب سے بچ گئی۔ ارشادباری تعالیٰ ہے:﴿وَمَا كَانَ ٱللَّهُ لِيُعَذِّبَهُمۡ وَأَنتَ فِيهِمۡۚ وَمَا كَانَ ٱللَّهُ مُعَذِّبَهُمۡ وَهُمۡ يَسۡتَغۡفِرُونَ﴾ [الأنفال: ۳۳] \"اور االلہ تعالیٰ ایسا نہیں کرے گا کہ ان میں آپ کے ہوتے ہوے ان کو عذاب دے اورااللہ تعالیٰ ان کو عذاب نہ دے گا اس حالت میں کہ وہ استغفارکررہے ہوں\"۔\nجب کہ آپ کی قو م نے یہ کہا بھی:﴿وَإِذۡ قَالُواْ ٱللَّهُمَّ إِن كَانَ هَٰذَا هُوَ ٱلۡحَقَّ مِنۡ عِندِكَ فَأَمۡطِرۡ عَلَيۡنَا حِجَارَةࣰ مِّنَ ٱلسَّمَآءِ أَوِ ٱئۡتِنَا بِعَذَابٍ أَلِيمࣲ‏﴾ [الأنفال: ۳۲] \"اے االلہ اگر یہ قرآن(دین) تیری جانب سے سچ ہے۔ تو ہم پر آسمان سے پتھر برسایا ہم پر کوئی دردناک عذاب ڈال دے\"۔\nمگر چونکہ آپ ساری دنیا کے لیے رحمت بناکر بھیجے گئے تھے۔اس لیے االلہتعالیٰ نے آپ کی قوم کو عذاب سےبچالیا۔ جبکہ جبریل علیہ السلام نے کہا بھی تھا کہ اگر آپ حکم کریں تو اسلام دشمنوں کو دوپہاڑوں کے درمیان کچل دیا جائے۔لیکن آپ نے فرمایا : نہیں۔ان کی اولاد میں ایسے لوگ پیدا ہوں گے جواسلام کی تبلیغ کریں گے۔ پھر ایسا ہی ہوا۔\n۲- عذاب سے پہلے آخری بار تنبیہ کی جاتی ہے اور نیک لوگوں سے بستی خالی کرالی جاتی ہے۔\n۳-جب عذاب آجاتا ہے تو توبہ قبول نہیں ہوتی۔\n۴-دنیا کا عذاب جتنابھی سخت ہو مگر آخرت کا عذاب اس سے زیادہ ہولناک ہوگا۔ (دیکھیے:سورہ البقرة:۸۵، سورہ الرعد : ۳۴)\n۵-مشرکین اور مخالفین اسلام کے علاوہ وہ لوگ بھی دنیا کے عذاب میں گھر جاتے ہیں،جن کی قوم میں زنا، بے حیائی،شراب نوشی، جوا اورسودخوری وغیرہ جیسی برائیاں عام ہوجاتی ہیں اور االلہ تعالیٰ کے احکام و قوانین کا مذاق اڑایا جاتا ہےیہ لوگ کبھی زلزلے،کبھی سیلاب، کبھی طوفان وغیرہ میں گھر جاتے ہیں اور زمین سے ہمیشہ کےلیے مٹادیے جاتے ہیں۔","",{}],[418,"§عربی زبان\nایسا مانا جاتاہےکہ عربی زبان دنیا کی تمام زبانوں میں عظیم اور قدیم ترین ہے۔اسی زبان میں قرآن مجید کا نزول ہوا۔مورخین کا خیال ہے کے عربی زبان تقریبا ۲۰۰۰ ق م سے پہلے بھی بولی جاتی تھی۔ ابراہیم علیہ السلام کے صاحبزا دےاسماعیل علیہ السلام بھی اس زبان کا استعمال کرتے تھے۔کیونکہ ان کی سسرال کے لوگوں کی زبان بھی عربی تھی۔جو یمن کے جرہم قبیلہ سے تعلق رکھتے تھے۔\nعرب کے قدیم قبائل طسم جُدیس اور عاد اولیٰ وغیرہ نے بھی عربی زبان کا استعمال کیا تھا۔اس لیے کچھ علماء کا خیال ہےکہ عربی لغت حقیقت میں عبرانی، آرامی،آشوری اور فینقی وغیرہ زبانوں کی اصل ہے۔اس لیے بہت سارےالفاظ آج بھی ان زبانوں میں اورعربی میں ایک سے پائے جاتے ہیں۔لیکن دوسرےعلماے لسانیات ان زبانوں کو آپس میں بہنیں مانتے ہیں۔کیونکہ وہ بھی اتنے ہی قدیم ہیں جتنی عربی ہے۔لیکن ان سب کی اصل (ماں)کے بارے میں کوئی بھی بات یقین کے ساتھ نہیں کہہ سکتے کہ وہ کون ہے؟ کچھ مغربی ماہرین لغت کا خیال ہے کہ ان کی اصل’سامی‘ ہے۔عربی زبان سامی زبانوں میں سب سےقریب ترین ہے۔اس لیے کہ عربی لغت میں بہت سے الفاظ اور جملوں کے قاعدے سامی زبانوں کے پائے جاتے ہیں۔\nنزول قرآن کے وقت تک عربی زبان بہت ترقی یافتہ ہوچکی تھی۔طائف سے ریاض جاتے ہوے عکاظ نامی عربوں کاایک اہم اورمشہور بازارتھا،جس میں بڑے بڑے شعراء اور ماہرین لغت ہرسال اکٹھا ہوتے تھےاور اپنی اپنی شاعری سناتے۔لیکن قرآن کریم کی عربی زبان سن کر یہ شعراء اور ادباء حیرت زدہ رہ جاتے کیونکہ ان کا خیال تھا کہ ان سے اچھی عربی زبان کوئی اور بول نہیں سکتا تھا۔ اس لیے جب قرآن مجید انتہائی رسیلی اور انتہائی موثرپیرایہ اور اسلوب بیان میں نبی اکرم صلی اللہ علیہ وسلم پر نازل ہونے لگا جب کہ آپ خود لکھنا پڑھنا نہیں جانتے تھے تو یہ اہل زبان حیرت زدہ رہ گئے۔ اس کی طرف قرآن کریم نےان آیتوں میں اشارہ کیاہے:﴿وَلَقَدۡ نَعۡلَمُ أَنَّهُمۡ يَقُولُونَ إِنَّمَا يُعَلِّمُهُۥ بَشَرࣱۗ لِّسَانُ ٱلَّذِي يُلۡحِدُونَ إِلَيۡهِ أَعۡجَمِيࣱّ وَهَٰذَا لِسَانٌ عَرَبِيࣱّ مُّبِينٌ﴾ [النحل: ۱۰۳] \"ہمیں بخوبی علم ہے کہ یہ کافر کہیں گےکہ اسے تو ایک آدمی سکھاتا ہے۔اس کی زبان جس کی طرف یہ اشارہ کررہے ہیں عجمی ہے اوریہ قرآن تو صاف عربی زبان میں ہے\"۔\nاس لیے قرآن کو یہ اعلان کرنا پڑا کہ یہ کسی انسان کا کلام نہیں ہے۔بلکہ یہ تو االلہ کا کلام ہے:﴿وَإِنَّهُۥ لَتَنزِيلُ رَبِّ ٱلۡعَٰلَمِينَ نَزَلَ بِهِ ٱلرُّوحُ ٱلۡأَمِينُ عَلَىٰ قَلۡبِكَ لِتَكُونَ مِنَ ٱلۡمُنذِرِينَ بِلِسَانٍ عَرَبِيࣲّ مُّبِينࣲ وَإِنَّهُۥ لَفِي زُبُرِ ٱلۡأَوَّلِينَ﴾ [الشعراء: ۱۹۲-۱۹۶] \"اور بےشک یہ قرآن رب العالمین کانازل فرمایاہوا ہےاسے امانت دار فرشتےلےکر آئے ہیں، آپ کے دل پر اترا ہے تاکہ آپ آگاہ کردینے والوں میں سے ہوجائیں، صاف عربی زبان میں ہے۔ اگلے نبیوں کی کتابوں میں بھی اس قرآن کا تذکرہ ہے\"۔\nنیزفرمایا: ﴿وَلَقَدۡ ضَرَبۡنَا لِلنَّاسِ فِي هَٰذَا ٱلۡقُرۡءَانِ مِن كُلِّ مَثَلࣲ لَّعَلَّهُمۡ يَتَذَكَّرُونَ قُرۡءَانًا عَرَبِيًّا غَيۡرَ ذِي عِوَجࣲ لَّعَلَّهُمۡ يَتَّقُونَ﴾ [الزمر: ۲۷-۲۸] \"ہم نے اس قرآن میں لوگوں کےلیے ہرقسم کی مثالیں بیان کردی ہیں، تاکہ وہ لوگ نصیحت حاصل کریں۔قرآن ہے عربی میں جس میں کوئی کجی نہیں ہے، ہوسکتا ہے کہ وہ پرہیز گاری اختیارکریں\"۔\nقرآن کریم نے ایک دائمی نظام قانون کی طرف اشارہ کیا ہے۔ اور وہ یہ ہے:﴿وَمَآ أَرۡسَلۡنَا مِن رَّسُولٍ إِلَّا بِلِسَانِ قَوۡمِهِۦ لِيُبَيِّنَ لَهُمۡۖ فَيُضِلُّ ٱللَّهُ مَن يَشَآءُ وَيَهۡدِي مَن يَشَآءُۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ﴾ [إبراهيم: ۴]\n\"ہم نے ہر نبی کو اس کی قوم کی زبان میں مبعوث کیا ہے\"۔\nاسی لئے عربی زبان میں وحی کا نزول ہوا اور نبی اکرم صلی اللہ علیہ وسلم نے اسی زبان میں لوگوں کو اسلام کاپیغام پہنچا یا۔\nاس آیت کریمہ میں ایک اہم نکتہ پوشیدہ ہے۔ اور وہ یہ ہے کہ آیت کریمہ میں \"لسان قوم\" کہا گیا نہ کہ \"لسان امت\" کیونکہ نبی صلی اللہ علیہ وسلم کے قوم کی زبان عربی تھی جبکہ آپ کے امتیوں کی زبانیں مختلف ہیں جیسے: اردو، فارسی، بنغالی، انگریزی اور جرمنی وغیرہ وغیرہ۔\nآپ لکھنا پڑھنا نہیں جانتے تھے۔پھر بھی شیریں اور فصیح زبان بولتے تھے۔بلکہ ایک موقعے پر آپ صلی اللہ علیہ وسلم نے فرمایا: أَنَا أَفْصَحُ العَرَبَمیں سب سے اچھی زبان بولنے والا عرب ہوں۔\nقرآن وحدیث کی یہی وہ عربی زبان ہے، جو آج بھی زندہ ہے۔ساری عربی دنیامیں یہی زبان مستعمل ہے۔\nعربی زبان کےقواعد اس وقت مدون کئے گئے، جب دین اسلام عرب ممالک سے نکل کر دوسرے ان ممالک میں پھیلنےلگا،جہاں کے لوگ عربی نہیں جانتے تھے۔اس لیے کہا جاتا ہے کہ ابو الاسود الدولی (ف ۷۹ھ)پہلےشخص ہیں، جنھوں نے اس کی گرامر(صرف ونحوکے قواعد)تیار کیے۔اس کے بعد عبدااللہ بن اسحاق حضرمی(ف ۷ااھ)، عیسیٰ بن عمر الثقفی (ف ۴۹ا ھ) اور ابو عمر و بن العلاء (ف ۵۴ا ھ) نے قواعد کی کتابیں مرتب کیں۔ سب سے معروف کتاب سیبویہ (ف ۸۰اھ) کی تھی، جس کا نام ہی اس نے الکتاب رکھا تھا۔\nعصر حاضر میں عربی زبان کوسہل بنانے کےلیے اور ان لوگوں کی تعلیم کےلیے، جن کی زبان عربی نہیں ہے، بہت سی کتابیں تیار کی گئی ہیں، ان میں کچھ درج ذیل ہیں:\nا-علی جازم اور مصطفی امین کی: النحو الواضح\n۲-مصطفی علیانی کی: جامع دروس عربیہ\n۳-ہندستان کے معروف عربی کے عالم: ڈاکٹرف. عبدالرحیم کی دروس اللغہ العربیہ۔جو اوّلا جامعہ اسلامیہ مدینہ منورہ سے شائع ہوئی اور اب ہندستان، پاکستان، ترکی، برطانیہ، کوریا، روس، امریکہ وغیرہ ممالک سے بھی شائع ہوچکی ہے۔عربی زبان آسانی سےسیکھی جاسکتی ہے۔آج پاک وہند اور دوسرے غیر عرب ممالک میں بھی مراکز اسلامیہ اور مدارس اسلامیہ میں اسی عربی زبان کی تعلیم دی جاتی ہے۔ یہ قرآن کا ہی معجزہ ہے کہ آج عربی زبان اسی طرح محفوظ ہے جس طرح نزول قرآن کے وقت تھی۔دیگر لغات تو ہر دوچار سو سال بعد بدلتی رہتی ہیں۔یا پھر وہ نابود ہوجاتی ہیں۔","",{}],[419,"§عرجون\nعرجون کا مطلب ہے کھجور کی شاخ۔ قرآن مجید میں ایک مقام پریہ بتایاگیا ہے کہ االلہ تعالیٰ نے چاند کے لیے منزلیں متعین کردی ہیں۔ ان پر چلتے چلتے ایک وقت ایسا بھی آتا ہے کہ جب چاندعرجون (کھجور کی خشک ٹہنی) کی طرح باریک ہوجاتا ہے۔ (سورہ یسین: ۳۹)\nدر حقیقت االلہ تعالیٰ یہ بتانا چاہتا ہے کہ اس کائنات میں جو کچھ ہورہا ہے اس کی مشیت وقدرت سے ہورہاہے۔ کیونکہ اس سے پہلی والی آیت میں سورج کا ذکر آیا ہے جواپنے مرکز اور مدار میں گردش کررہاہے۔ مذکوربالا آیات میں ان لوگوں کو تنبیہ کی گئی ہے جو االلہ کوچھوڑ کر سورج اور چاند کو اپنا معبود بنابیٹھے ہیں۔جب کہ حقیقت میں یہ بھی ہماری طرح االلہ تعالیٰ کی مخلوق ہیں۔یہ کسی بھی طرح معبود نہیں ہوسکتے۔قرآن مجید نے بہت ہی خوبصورت اور بے مثال انداز میں ابراہیم علیہ السلام کی اس کیفیت کا ذکر کیا ہے، جوستارے،چاند اور سورج کو دیکھ کر ان کے دل میں ان کی عبادت کےتعلق سے پیدا ہوئی تھی۔لیکن جب وہ غروب ہوگئے تو انھوں نے برجستہ کہا کہ میں ان تمام چیزوں سے بری ہوں اور اپنا چہرہ صرف اس ذات کی طرف پھیردیا ہے جس نے یہ ساری کائنات بنائی ہے:\"اور ہم نےاسی طور پر ابراہیم (علیہ السلام) کو آسمانوں اور زمین کی مخلوقات دکھائیں تاکہ وہ کامل یقین کرنے والوں میں سے ہوجائیں۔پھر جب رات کی تاریکی ان پر چھاگئی توانھوں نے ایک ستارہ دیکھا۔ آپ نےفرمایا : یہ میرا رب ( حقیقی معبود)ہے۔مگر جب وہ ڈوب گیا تو فرمایا کہ میں ڈوب جانے والوں سے محبت نہیں رکھتا۔پھر جب چاند کو چمکتا ہوا دیکھا تو فرمایا : یہ میرا رب (حقیقی معبود)ہے۔ لیکن جب وہ ڈوب ہوگیا تو فرمایا : اگر مجھ کو میرے رب ( حقیقی معبود)نے ہدایت نہ دی تومیں گمراہ لوگوں میں شامل ہوجاؤں گا۔پھر جب سورج کو چمکتا ہوادیکھا تو فرمایا : یہ میرا رب ( حقیقی معبود)ہے۔یہ تو سب سے بڑا ہے۔پھر جب وہ بھی ڈوب ہوگیا تو فرمایا: بے شک میں تمھارے شرک سے بیزار ہوں۔میں یکسوہوکر اپنا رخ اس کی طرف کرتاہوں، جس نے آسمانوں اورزمین کو پیدا کیا، میں شرک کرنے والوں میں سے نہیں ہوں\"۔(الانعام: ۷۵- ۷۹)","",{}],[420,"§عرش\nقرآن مجید میں عرش دومعنوں میں استعمال ہوا ہے۔ایک گھر کی چھت کے لیے۔ جیسے االلہتعالیٰ کا یہ فرمان: ﴿أَوۡ كَٱلَّذِي مَرَّ عَلَىٰ قَرۡيَةࣲ وَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا قَالَ أَنَّىٰ يُحۡيِۦ هَٰذِهِ ٱللَّهُ بَعۡدَ مَوۡتِهَاۖ فَأَمَاتَهُ ٱللَّهُ مِاْئَةَ عَامࣲ ثُمَّ بَعَثَهُۥۖ قَالَ كَمۡ لَبِثۡتَۖ قَالَ لَبِثۡتُ يَوۡمًا أَوۡ بَعۡضَ يَوۡمࣲۖ قَالَ بَل لَّبِثۡتَ مِاْئَةَ عَامࣲ فَٱنظُرۡ إِلَىٰ طَعَامِكَ وَشَرَابِكَ لَمۡ يَتَسَنَّهۡۖ وَٱنظُرۡ إِلَىٰ حِمَارِكَ وَلِنَجۡعَلَكَ ءَايَةࣰ لِّلنَّاسِۖ وَٱنظُرۡ إِلَى ٱلۡعِظَامِ كَيۡفَ نُنشِزُهَا ثُمَّ نَكۡسُوهَا لَحۡمࣰ اۚ فَلَمَّا تَبَيَّنَ لَهُۥ قَالَ أَعۡلَمُ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرࣱ‏﴾ [البقرة: ۲۵۹] \"یا اس شخص کے مانند کہ جس کا گزرا س بستی پر ہوا جو چھت کے بل اوندھی پڑی ہوئی تھی،وہ کہنے لگا:اس کی موت کے بعد االلہ تعالیٰ اسےکس طرح زندہ کرے گا؟تو االلہ تعالیٰ نے اسے ماردیا، سوسال کے لیےپھر اسے اٹھایاپوچھا: کتنی مدت تجھ پر گزری؟کہنے لگا:ایک دن یادن کا کچھ حصہ، فرمایا: بلکہ تو سوسال تک رہا، پھر اب تو اپنے کھانے پینے کو دیکھ کہ بالکل خراب نہیں ہوا ور اپنے گدھے کو بھی دیکھ ہم تجھے لوگوں کے لیے ایک نشانی بناتے ہیں،تو دیکھ کہ ہم ہڈیوں کوکس طرح اٹھاتے ہیں پھر ان پر گوشت چڑھاتے ہیں۔ جب یہ سب ظاہر ہو چکاتو کہنے لگا: میں جانتا ہوں کہ االلہ تعالیٰ ہر چیز پر قادر ہے\"۔\nکچھ علماء کاخیال ہے کہ اس آیت میں\"حز قیل\" نبی کی جانب اشارہ ہے۔\nدوسرے تخت شاہی کے معنی میں۔ جیسے قرآن مجید میں ہدہدنامی ایک پرندہ سلیمان علیہ السلام کو اطلاع دیتے ہوےکہتا ہے:﴿إِنِّي وَجَدتُّ ٱمۡرَأَةࣰ تَمۡلِكُهُمۡ وَأُوتِيَتۡ مِن كُلِّ شَيۡءࣲ وَلَهَا عَرۡشٌ عَظِيمࣱ‏﴾ [النمل: ۲۳] \"میں نے دیکھا کہ ان(سبا والوں) کی بادشاہت ایک عورت کررہی ہے،جسے ہر قسم کی چیز سے کچھ نہ کچھ دیا گیا ہےاور اس کا تخت بھی بڑی عظمت والا ہے\"۔\nااللہ تعالیٰ کی سب سے بڑی مخلوق عرش ہے۔قرآن مجیدمیں ایک مقام پرارشادہے:﴿ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ۩﴾ [النمل: ۲۶] \"االلہ کے سوا کوئی معبود برحق نہیں،وہی عظمت والے عرش کا مالک ہے\"۔\nعرش کا مالک ہونے کا مطلب ہے کہ االلہ نے اس کو بنایا ہےاور وہ ایک چیزہے جیسے کوئی چیز ہوتی ہے۔جب ہی توآٹھ فرشتے اس کو اٹھائے ہوے ہیں۔ ارشادباری تعالیٰ ہے :\n۱- ﴿ٱلَّذِينَ يَحۡمِلُونَ ٱلۡعَرۡشَ وَمَنۡ حَوۡلَهُۥ يُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡ وَيُؤۡمِنُونَ بِهِۦ وَيَسۡتَغۡفِرُونَ لِلَّذِينَ ءَامَنُواْۖ رَبَّنَا وَسِعۡتَ كُلَّ شَيۡءࣲ رَّحۡمَةࣰ وَعِلۡمࣰ ا فَٱغۡفِرۡ لِلَّذِينَ تَابُواْ وَٱتَّبَعُواْ سَبِيلَكَ وَقِهِمۡ عَذَابَ ٱلۡجَحِيمِ﴾ [المومن: ۷] \"عرش اٹھانے والے اور اس کے آس پاس کے (فرشتے) اپنے رب کی تسبیح حمد کے ساتھ کرتے ہیں اور اس پر ایمان رکھتے ہیں اور ایمان والوں کے لیے استغفار کرتے ہیں۔ کہتے ہیں کہ اے پروردگار! تونے ہر چیز کو اپنی رحمت اور علم سے گھیر رکھا ہے پس تو انھیں بخش دے۔ جو توبہ کریں اور تیری راہ کی پیروی کریں اور تو انھیں جہنم کے عذاب سے بھی بچالے\"۔\n۲- ﴿وَٱلۡمَلَكُ عَلَىٰٓ أَرۡجَآئِهَاۚ وَيَحۡمِلُ عَرۡشَ رَبِّكَ فَوۡقَهُمۡ يَوۡمَئِذࣲ ثَمَٰنِيَةࣱ‏﴾ [الحاقة: ۱۷] \"اس (آسمان) کے کنارے پر فرشتے ہوں گے اور اس دن تیرے رب کے عرش کو آٹھ فرشتے اٹھائے ہوے ہوں گے\"۔\nااللہ تعالیٰ کے عرش کواٹھانے والے فرشتوں کے بارے میں مذکورہے کہ وہ بہت قوی ہوں گے۔ان کے کان اور کندھے کے درمیان کا فاصلہ سات سو سال کے سفر کے برابر ہوگا۔ (سنن ابو داود : ۴۷۲۷)\nااللہ تعالیٰ کا عرش سب سے بلند اورسب سےعظیم مخلوق ہے۔ ساری کائنات اس کے نیچے ایسی ہے، جیسےریگستان میں ایک چھوٹا گڑھا۔صحیح بخاری کی ایک حدیث میں بھی اس جانب اشارہ کیا گیا ہے: ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «إِذَا سَأَلْتُمُ اللَّهَ فَسَلُوهُ الْفِرْدَوْسَ فَإِنَّهُ أَوْسَطُ الْجَنَّةِ وَأَعْلَی الْجَنَّةِ وَفَوْقَهُ عَرْشُ الرَّحْمَنِ وَمِنْهُ تَفَجَّرُ أَنْهَارُ الْجَنَّةِ». (صحیح البخاری: ۷۴۲۳، ۲۷۹۰) \"اگر تم االلہ تعالیٰ سے کچھ سوال کرو تو جنت الفردوس کا سوال کرو۔کیونکہ یہ جنت کا سب سے اونچا اور اعلی حصہ ہے۔ االلہ تعالیٰ کا عرش عظیم ہےاور وہیں سے جنت کی نہریں نکلتی ہیں\"۔ (صحیح البخاری :۷۴۲۳)\nقرآن مجید کی ایک دوسری آیت میں ہے:﴿وَهُوَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ فِي سِتَّةِ أَيَّامࣲ وَكَانَ عَرۡشُهُۥ عَلَى ٱلۡمَآءِ لِيَبۡلُوَكُمۡ أَيُّكُمۡ أَحۡسَنُ عَمَلࣰ اۗ وَلَئِن قُلۡتَ إِنَّكُم مَّبۡعُوثُونَ مِنۢ بَعۡدِ ٱلۡمَوۡتِ لَيَقُولَنَّ ٱلَّذِينَ كَفَرُوٓاْ إِنۡ هَٰذَآ إِلَّا سِحۡرࣱ مُّبِينࣱ‏﴾ [ہود: ۷] \"االلہ ہی وہ ہے جس نے چھ دن میں آسمان وزمین کو پیدا کیا اور اس کا عرش پانی پر تھا\"۔\nمذکورہ بالا آیات سے واضح ہوتا ہے کہ عرش کوئی چیز ہے، جس کو االلہ تعالی نے پیدا کیا ہے۔ پھر وہ اس کےاوپرمستوی یعنی بلندوبالاہے۔مخلوق سے دوراور الگ۔ اس استوا، استقرار اوربلندی کی کیفیت کا علم صرف اللہ تعالی کو ہے، کسی مخلوق کو نہیں ہے۔اسی بناپر ہم غیب پر ایمان رکھتے ہوے قرآن مجیدکی ان آیتوں اور صحیح احادیث میں جو کچھ عرش کے بارے میں آیا ہے اس پر ایمان رکھتے ہیں اور ہر قسم کے غلط اور نامناسب تصور سے احتراز کرتے ہیں۔ یہی وہ صحیح عقیدہ ہے جو صحابہ کرام اور اسلاف عظام اور اسلامی علما ءکارہاہے اور ہے۔","",{}]]);
